insert into public.illness_scripts (id, version, status, reviewed_by, reviewed_at, content) values
  ('zorblax-syndrome', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"kind":"disease","name":"Zorblax syndrome","aliases":["ZBX"],"systems":["general"],"rotation":["IM"],"confused_with":[{"script_id":"quellan-fever","how_to_tell_apart":"Quellan fever causes green nail beds and a normal blorp.","compare":[{"label":"Nails","text":"Blue nail beds","source_field":"key_findings.exam[0]"},{"label":"Blorp","text":"High","source_field":"key_findings.labs[0]"}]}],"pearls":["Zorblax syndrome never causes fever."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1000000001"},{"kind":"note","id":"1000000002","rung":"management"}],"sources":[{"title":"Rounds test fixture (fictional)"}],"epidemiology":{"who":"Fictional adults over 40 (test fixture, not a real disease)","risk_factors":["glimmer exposure","night shift work","low blorp diet","family history"]},"pathophysiology":"Fictional autoimmune attack on the glimmer gland.","timeline":{"onset":"Subacute, over weeks","course":"Relapsing-remitting"},"key_findings":{"history":["purple fatigue","itchy elbows"],"exam":["blue nail beds"],"labs":["high serum blorp"],"imaging":["swollen glimmer gland on ultrasound"]},"diagnosis":{"confirmatory_tests":["anti-glimmer antibody"],"criteria":["serum blorp above 40 units with blue nail beds"]},"management":{"first_line":["zorbicillin"],"next_line":["plasma swap"]},"complications":["glimmer storm"]}'::jsonb),
  ('quellan-fever', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"kind":"disease","name":"Quellan fever","aliases":["QF"],"systems":["general"],"rotation":["IM"],"confused_with":[{"script_id":"zorblax-syndrome","how_to_tell_apart":"Zorblax syndrome causes blue nail beds, high blorp and no fever.","compare":[{"label":"Nails","text":"Green nail beds","source_field":"key_findings.exam[0]"},{"label":"Blorp","text":"Normal","source_field":"key_findings.labs[0]"}]}],"pearls":[],"difficulty_tiers":{"MS1-2":[],"MS3":["key_findings.exam[0]"],"MS4":[]},"anki_refs":[],"sources":[{"title":"Rounds test fixture (fictional)"}],"epidemiology":{"who":"Fictional travelers (test fixture)","risk_factors":["quellan bites"]},"pathophysiology":"Fictional infection of the nail matrix.","timeline":{"onset":"Acute, over days","course":"Self-limited"},"key_findings":{"history":["fever","purple fatigue"],"exam":["green nail beds"],"labs":["normal blorp"],"imaging":[]},"diagnosis":{"confirmatory_tests":["quellan PCR"],"criteria":[]},"management":{"first_line":["supportive care"],"next_line":[]},"complications":[]}'::jsonb),
  ('abdominal-aortic-aneurysm', 1, 'in_review', null, null, '{"kind":"disease","name":"Abdominal aortic aneurysm","aliases":["AAA"],"systems":["cardio"],"rotation":["surgery","IM"],"confused_with":[{"script_id":"aortic-dissection","how_to_tell_apart":"An abdominal aortic aneurysm is a dilated aorta, silent until it expands or ruptures; aortic dissection is a tear in the intima with sudden tearing chest pain that radiates to the back."}],"pearls":["The classic triad of rupture is abdominal or back pain, hypotension and a pulsatile mass.","Most abdominal aortic aneurysms are infrarenal.","Diabetes is linked to a lower risk of abdominal aortic aneurysm."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.risk_factors"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2022 ACC/AHA Guideline for the Diagnosis and Management of Aortic Disease"},{"title":"Screening for Abdominal Aortic Aneurysm: US Preventive Services Task Force Recommendation Statement (2019)"}],"epidemiology":{"who":"Men over 65 who have smoked","risk_factors":["smoking","male sex","age over 65","family history","hypertension","atherosclerosis"]},"pathophysiology":"Inflammation and matrix metalloproteinases break down elastin and collagen in the wall of the infrarenal aorta, which dilates to 3 cm or more.","timeline":{"onset":"Grows silently over years","course":"The risk of rupture rises sharply above 5.5 cm"},"key_findings":{"history":["usually no symptoms","abdominal or back pain if expanding","sudden severe pain and collapse if ruptured"],"exam":["pulsatile abdominal mass","hypotension in rupture"],"labs":[],"imaging":["abdominal ultrasound for screening and surveillance","CT angiography to plan repair, or in a stable patient with suspected rupture"]},"diagnosis":{"confirmatory_tests":["abdominal ultrasound","CT angiography"],"criteria":["an aortic diameter of 3 cm or more"]},"management":{"first_line":["one-time ultrasound screening for men aged 65 to 75 who have ever smoked","stop smoking","surveillance ultrasound for small aneurysms"],"next_line":["elective repair, endovascular (EVAR) or open, at 5.5 cm or more in men, 5.0 cm in women, rapid growth (0.5 cm or more in a year under the 2022 ACC/AHA guideline), or symptoms","emergency repair for rupture"]},"complications":["rupture","distal embolism","aortoenteric fistula after repair"]}'::jsonb),
  ('ace-inhibitors', 1, 'in_review', null, null, '{"kind":"drug","name":"ACE inhibitors","aliases":["angiotensin-converting enzyme inhibitors"],"systems":["cardio","renal"],"rotation":[],"confused_with":[{"script_id":"angiotensin-receptor-blockers","how_to_tell_apart":"ACE inhibitors block angiotensin II production and raise bradykinin, causing cough and more angioedema; ARBs block the angiotensin II receptor and do not raise bradykinin."},{"script_id":"sacubitril-valsartan","how_to_tell_apart":"An ACE inhibitor is the older choice in heart failure with reduced ejection fraction; sacubitril-valsartan lowers mortality further, and the ACE inhibitor must be stopped 36 hours before switching."}],"pearls":["A creatinine rise of up to 30% after starting is expected, and the drug can be continued.","The cough comes from bradykinin; switch to an ARB, which does not raise bradykinin.","ACE inhibitors slow diabetic kidney disease by dilating the efferent arteriole, which lowers pressure in the glomerulus."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","monitoring"],"MS4":["contraindications[3]","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"KDIGO 2024 Clinical Practice Guideline for the Evaluation and Management of Chronic Kidney Disease"}],"class":"Angiotensin-converting enzyme inhibitors","class_members":["lisinopril","enalapril","ramipril","captopril","benazepril"],"mechanism":"Block angiotensin-converting enzyme, so less angiotensin I becomes angiotensin II. Aldosterone falls, the efferent arteriole dilates, and bradykinin builds up because ACE also breaks bradykinin down.","pharmacokinetics":["most are prodrugs activated in the liver; captopril and lisinopril are not","cleared by the kidneys"],"indications":["hypertension","heart failure with reduced ejection fraction","after myocardial infarction","diabetic kidney disease and chronic kidney disease with proteinuria"],"adverse_effects":["dry cough","angioedema","hyperkalemia","acute rise in creatinine","hypotension after the first dose","teratogenic: fetal kidney damage"],"contraindications":["pregnancy","history of angioedema","bilateral renal artery stenosis","within 36 hours of sacubitril-valsartan"],"interactions":["potassium-sparing diuretics and potassium supplements raise potassium further","NSAIDs blunt the effect and add to kidney injury","raise lithium levels"],"monitoring":["potassium and creatinine 1 to 2 weeks after starting or raising the dose"],"overdose":{"features":["hypotension"],"treatment":["IV fluids"]}}'::jsonb),
  ('acute-coronary-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute coronary syndrome","aliases":["ACS","myocardial infarction"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"aortic-dissection","how_to_tell_apart":"Aortic dissection gives sudden tearing pain radiating to the back, a blood pressure difference between arms and a widened mediastinum; exclude it before giving anticoagulants.","compare":[{"label":"Pain","text":"Pressure, to arm or jaw","source_field":"key_findings.history[0]"},{"label":"Exam","text":"Often normal","source_field":"key_findings.exam[0]"},{"label":"First drug","text":"Aspirin","source_field":"management.first_line[0]"}]},{"script_id":"pulmonary-embolism","how_to_tell_apart":"PE causes pleuritic pain, hypoxemia and tachycardia, usually without ST elevation.","compare":[{"label":"Pain","text":"Pressure, to arm or jaw","source_field":"key_findings.history[0]"},{"label":"First test","text":"ECG within 10 minutes","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"First drug","text":"Aspirin","source_field":"management.first_line[0]"}]}],"pearls":["Avoid nitrates in inferior MI with right ventricular involvement, or after a phosphodiesterase inhibitor such as sildenafil: they can cause severe hypotension."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1471899395392"},{"kind":"note","id":"1472320389702"},{"kind":"note","id":"1496961116835"},{"kind":"note","id":"1497314069507"},{"kind":"note","id":"1550527900362"},{"kind":"note","id":"1497804272202","rung":"recall"},{"kind":"note","id":"1543516065507","rung":"recall"},{"kind":"note","id":"1550522074335","rung":"recall"},{"kind":"note","id":"1471899090660","rung":"workup"},{"kind":"note","id":"1497804636687","rung":"workup"},{"kind":"note","id":"1550522074056","rung":"workup"},{"kind":"note","id":"1472747857568","rung":"management"},{"kind":"note","id":"1522940134564","rung":"management"},{"kind":"note","id":"1555271601101","rung":"management"}],"sources":[{"title":"2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Patients With Acute Coronary Syndromes"}],"epidemiology":{"who":"Adults with atherosclerotic risk factors","risk_factors":["smoking","diabetes","hypertension","hyperlipidemia","family history of premature coronary disease","older age"]},"pathophysiology":"Rupture or erosion of an atherosclerotic plaque triggers a thrombus that reduces or blocks coronary blood flow, causing myocardial ischemia or infarction.","timeline":{"onset":"Sudden, often at rest","course":"Heart muscle is lost with every minute of a complete occlusion"},"key_findings":{"history":["pressure-like chest pain radiating to the arm or jaw","dyspnea","diaphoresis","nausea"],"exam":["often normal","signs of heart failure or shock in large infarcts"],"labs":["rise and fall of high-sensitivity troponin","ECG: ST elevation in STEMI; ST depression or T-wave inversion in NSTE-ACS"],"imaging":["echocardiogram for wall motion abnormalities"]},"diagnosis":{"confirmatory_tests":["12-lead ECG within 10 minutes","high-sensitivity troponin, repeated"],"criteria":["STEMI: ST elevation in two contiguous leads","NSTEMI: troponin rise without ST elevation","unstable angina: ischemic symptoms without a troponin rise"]},"management":{"first_line":["aspirin","second antiplatelet agent (P2Y12 inhibitor such as ticagrelor)","anticoagulation with heparin","primary PCI within 90 minutes for STEMI"],"next_line":["fibrinolysis if PCI is not available within 120 minutes","high-intensity statin","beta-blocker if no heart failure or shock","nitroglycerin for ongoing pain"]},"complications":["arrhythmias","heart failure","cardiogenic shock","papillary muscle rupture","ventricular free wall rupture"]}'::jsonb),
  ('acute-ischemic-stroke', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute ischemic stroke","aliases":["stroke","CVA"],"systems":["neuro"],"rotation":["IM","EM","neuro"],"confused_with":[],"pearls":["Blood pressure must be below 185/110 mmHg before thrombolysis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1512752683399"},{"kind":"note","id":"1512955668550"},{"kind":"note","id":"1550409526747"},{"kind":"note","id":"1550450202537"},{"kind":"note","id":"1555754474939"},{"kind":"note","id":"1481771759221","rung":"recall"},{"kind":"note","id":"1512595785795","rung":"recall"},{"kind":"note","id":"1550694286485","rung":"recall"},{"kind":"note","id":"1472668510022","rung":"management"},{"kind":"note","id":"1481771888224","rung":"management"},{"kind":"note","id":"1481771899132","rung":"management"}],"sources":[{"title":"Guidelines for the Early Management of Patients With Acute Ischemic Stroke: 2019 Update (AHA/ASA)"}],"epidemiology":{"who":"Older adults with vascular risk factors","risk_factors":["hypertension","atrial fibrillation","diabetes","smoking","hyperlipidemia","prior stroke or TIA"]},"pathophysiology":"A thrombus or embolus blocks a brain artery; the ischemic penumbra around the core can be saved by fast reperfusion.","timeline":{"onset":"Sudden","course":"Brain tissue is lost each minute until reperfusion"},"key_findings":{"history":["sudden one-sided weakness or numbness","speech difficulty","facial droop","time last known well"],"exam":["focal neurologic deficit matching a vascular territory","NIH Stroke Scale to grade severity"],"labs":["fingerstick glucose to exclude hypoglycemia"],"imaging":["noncontrast CT head to exclude hemorrhage","CT angiography to find a large vessel occlusion"]},"diagnosis":{"confirmatory_tests":["noncontrast CT head","CT angiography"],"criteria":["sudden focal deficit with a vascular explanation and no hemorrhage on imaging"]},"management":{"first_line":["IV thrombolysis (alteplase or tenecteplase) within 4.5 hours of last known well","mechanical thrombectomy for large vessel occlusion, up to 24 hours in selected patients","check glucose before treatment"],"next_line":["aspirin within 24 to 48 hours if not thrombolysed","secondary prevention: antiplatelet, statin, and anticoagulation for atrial fibrillation"]},"complications":["hemorrhagic transformation","cerebral edema","aspiration pneumonia","dysphagia"]}'::jsonb),
  ('acute-kidney-injury', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute kidney injury","aliases":["AKI","acute renal failure"],"systems":["renal"],"rotation":["IM"],"confused_with":[],"pearls":["Indications for urgent dialysis (AEIOU): acidosis, electrolytes (hyperkalemia), ingestions, overload and uremia."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1475353385337"},{"kind":"note","id":"1475353595370"},{"kind":"note","id":"1475353706251"},{"kind":"note","id":"1475353706252"},{"kind":"note","id":"1556663045381"}],"sources":[{"title":"KDIGO Clinical Practice Guideline for Acute Kidney Injury (2012)"}],"epidemiology":{"who":"Hospitalized adults, especially older patients and those with chronic kidney disease","risk_factors":["volume depletion","sepsis","nephrotoxic drugs","IV contrast","urinary obstruction","chronic kidney disease"]},"pathophysiology":"A sudden fall in glomerular filtration, classified as prerenal (low perfusion), intrinsic (most often acute tubular necrosis) or postrenal (obstruction).","timeline":{"onset":"Hours to days","course":"Often recovers once the cause is fixed; can progress to dialysis or chronic kidney disease"},"key_findings":{"history":["reduced urine output","recent vomiting, diarrhea or poor intake","new medications such as NSAIDs, ACE inhibitors or aminoglycosides"],"exam":["signs of volume depletion or overload","palpable bladder in obstruction"],"labs":["creatinine rise of 0.3 mg/dL or more within 48 hours","BUN-to-creatinine ratio above 20 in prerenal AKI","muddy brown granular casts in acute tubular necrosis","fractional excretion of sodium below 1% in prerenal AKI"],"imaging":["renal ultrasound to look for hydronephrosis"]},"diagnosis":{"confirmatory_tests":["serum creatinine","urine output","urinalysis with microscopy","renal ultrasound"],"criteria":["creatinine rise of 0.3 mg/dL or more within 48 hours","creatinine 1.5 times baseline or more within 7 days","urine output below 0.5 mL/kg/h for 6 hours"]},"management":{"first_line":["treat the cause","IV fluids if volume depleted","stop nephrotoxic drugs","relieve obstruction"],"next_line":["dialysis for refractory hyperkalemia, acidosis, volume overload, uremic complications or toxins","adjust drug doses for kidney function"]},"complications":["hyperkalemia","metabolic acidosis","volume overload","uremic pericarditis","progression to chronic kidney disease"]}'::jsonb),
  ('acute-pancreatitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute pancreatitis","aliases":[],"systems":["gi"],"rotation":["IM","surgery"],"confused_with":[{"script_id":"diabetic-ketoacidosis","how_to_tell_apart":"DKA can cause abdominal pain and a mildly raised lipase, but it has high glucose, ketones and an anion gap acidosis, and the pain improves as the acidosis is treated.","compare":[{"label":"Key lab","text":"Lipase over 3x normal","source_field":"key_findings.labs[0]"},{"label":"Exam","text":"Epigastric tenderness","source_field":"key_findings.exam[0]"},{"label":"Treat","text":"Lactated Ringer''s","source_field":"management.first_line[0]"}]}],"pearls":["Gallstone pancreatitis is suggested by an ALT more than 3 times the upper limit of normal."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.history[0]","diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[{"kind":"note","id":"1495239550899"},{"kind":"note","id":"1495239811994"},{"kind":"note","id":"1511219527044"},{"kind":"note","id":"1511219634492"},{"kind":"note","id":"1535921440931"},{"kind":"note","id":"1482971305143","rung":"recall"},{"kind":"note","id":"1482971320837","rung":"recall"},{"kind":"note","id":"1482971441031","rung":"recall"},{"kind":"note","id":"1495670579999","rung":"management"},{"kind":"note","id":"1532131804405","rung":"management"},{"kind":"note","id":"1535304077148","rung":"management"}],"sources":[{"title":"American College of Gastroenterology Guideline: Management of Acute Pancreatitis (2024)"},{"title":"Classification of acute pancreatitis: revision of the Atlanta classification by international consensus (2012)"}],"epidemiology":{"who":"Adults; gallstones are the most common cause, then heavy alcohol use","risk_factors":["gallstones","alcohol","hypertriglyceridemia","post-ERCP","medications","hypercalcemia"]},"pathophysiology":"Premature activation of pancreatic enzymes (trypsin) inside the gland causes autodigestion and local inflammation, which can become a systemic inflammatory response.","timeline":{"onset":"Sudden, over hours","course":"Mild disease settles within a week; severe disease brings organ failure lasting over 48 hours and local complications"},"key_findings":{"history":["sudden epigastric pain radiating to the back","nausea and vomiting","recent heavy alcohol use or known gallstones"],"exam":["epigastric tenderness","tachycardia","flank or periumbilical bruising in severe disease"],"labs":["lipase more than 3 times the upper limit of normal","raised ALT in gallstone pancreatitis"],"imaging":["right upper quadrant ultrasound to look for gallstones","contrast CT only if the diagnosis is unclear or the patient is not improving"]},"diagnosis":{"confirmatory_tests":["serum lipase","right upper quadrant ultrasound"],"criteria":["two of three: typical epigastric pain, lipase more than 3 times the upper limit of normal, characteristic imaging findings"]},"management":{"first_line":["early goal-directed IV fluids with lactated Ringer''s","pain control","early oral feeding as tolerated"],"next_line":["cholecystectomy during the same admission for mild gallstone pancreatitis","ERCP within 24 hours if there is cholangitis","no prophylactic antibiotics"]},"complications":["pancreatic pseudocyst","walled-off necrosis","infected necrosis","ARDS","acute kidney injury"]}'::jsonb),
  ('acute-pericarditis', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute pericarditis","aliases":["pericarditis"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"Pericarditis pain is sharp, pleuritic and eased by leaning forward, with ST elevation in most leads and PR depression; a myocardial infarction causes ST elevation in one coronary territory with reciprocal depression."},{"script_id":"myocarditis","how_to_tell_apart":"Pericarditis inflames the pericardium, causing pleuritic pain, a rub and PR depression; myocarditis inflames the heart muscle, raising troponin and weakening contraction."}],"pearls":["After a myocardial infarction, aspirin is preferred over other NSAIDs for pericarditis.","Colchicine halves the risk of recurrence.","PR depression is a characteristic ECG sign of pericarditis; reciprocal ST depression points to an MI instead."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2025 ESC Guidelines for the management of myocarditis and pericarditis"},{"title":"2015 ESC Guidelines for the diagnosis and management of pericardial diseases"}],"epidemiology":{"who":"Young and middle-aged adults, more often men","risk_factors":["recent viral infection","myocardial infarction, early or weeks later (Dressler syndrome)","cardiac surgery","uremia","lupus and other autoimmune diseases","tuberculosis","cancer"]},"pathophysiology":"Inflammation of the pericardium, most often idiopathic or viral. The inflamed layers rub together, causing sharp pain and a friction rub, and may produce an effusion.","timeline":{"onset":"Sudden chest pain over hours","course":"Usually settles in 1 to 3 weeks; recurs in up to 30% without colchicine"},"key_findings":{"history":["sharp pleuritic chest pain","pain eased by sitting up and leaning forward","pain worse lying flat","recent viral illness"],"exam":["pericardial friction rub","fever"],"labs":["raised CRP","troponin may rise if the myocardium is involved (myopericarditis)"],"imaging":["ECG with diffuse ST elevation and PR depression","echocardiogram to look for an effusion"]},"diagnosis":{"confirmatory_tests":["ECG","echocardiogram"],"criteria":["at least two of four: typical chest pain, friction rub, diffuse ST elevation or PR depression, a new or worsening pericardial effusion"]},"management":{"first_line":["NSAID such as ibuprofen, or high-dose aspirin, plus colchicine for 3 months","limit strenuous exercise until symptoms and CRP settle"],"next_line":["low-dose glucocorticoids if NSAIDs fail or are contraindicated","admission for high-risk features: fever above 38 C, a large effusion, tamponade or failure of NSAIDs"]},"complications":["recurrent pericarditis","pericardial effusion","cardiac tamponade","constrictive pericarditis"]}'::jsonb),
  ('acute-pyelonephritis', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute pyelonephritis","aliases":["pyelonephritis","kidney infection"],"systems":["renal"],"rotation":["IM","EM","FM"],"confused_with":[],"pearls":["White blood cell casts in the urine point to the kidney (pyelonephritis) rather than the bladder."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1520885217485","rung":"recall"},{"kind":"note","id":"1547916133337","rung":"recall"},{"kind":"note","id":"1553043297138","rung":"recall"},{"kind":"note","id":"1543683644900","rung":"management"},{"kind":"note","id":"1547564850214","rung":"management"},{"kind":"note","id":"1553043297393","rung":"management"}],"sources":[{"title":"International Clinical Practice Guidelines for the Treatment of Acute Uncomplicated Cystitis and Pyelonephritis in Women (IDSA and ESCMID, 2010)"}],"epidemiology":{"who":"Mostly women; also men with urinary obstruction","risk_factors":["female sex","recent sexual intercourse","urinary obstruction or stones","pregnancy","diabetes","urinary catheter"]},"pathophysiology":"Bacteria, most often Escherichia coli, ascend from the bladder and infect the kidney.","timeline":{"onset":"Over 1 to 2 days","course":"Fever usually settles within 72 hours of antibiotics"},"key_findings":{"history":["fever and chills","flank pain","dysuria and frequency","nausea and vomiting"],"exam":["costovertebral angle tenderness","fever"],"labs":["pyuria","white blood cell casts","positive urine culture"],"imaging":["CT or ultrasound if there is no improvement after 48 to 72 hours, or obstruction is suspected"]},"diagnosis":{"confirmatory_tests":["urinalysis","urine culture before antibiotics"],"criteria":["flank pain or costovertebral angle tenderness with fever and pyuria"]},"management":{"first_line":["oral fluoroquinolone (ciprofloxacin) if local resistance is low and the patient is well","IV ceftriaxone if admitted"],"next_line":["tailor to culture results","imaging and drainage for obstruction or abscess"]},"complications":["sepsis","renal abscess","emphysematous pyelonephritis"]}'::jsonb),
  ('adenosine', 1, 'in_review', null, null, '{"kind":"drug","name":"Adenosine","aliases":["Adenocard"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"non-dihydropyridine-calcium-channel-blockers","how_to_tell_apart":"Both stop SVT by blocking the AV node, but adenosine works for only seconds and is the first choice, while verapamil and diltiazem act for hours and also slow the rate in atrial fibrillation."}],"pearls":["Warn the patient that a few seconds of feeling awful are expected.","Start with 6 mg, then give 12 mg if needed.","Heart transplant recipients are very sensitive to adenosine and need a lower dose."],"difficulty_tiers":{"MS1-2":["mechanism","pharmacokinetics[0]"],"MS3":["indications","adverse_effects"],"MS4":["interactions","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia"}],"class":"Adenosine receptor agonist (unclassified antiarrhythmic)","class_members":["adenosine"],"mechanism":"Activates A1 receptors in the AV node, opening potassium channels and hyperpolarizing the cells, which briefly blocks AV conduction.","pharmacokinetics":["half-life under 10 seconds","given as a rapid IV push with a saline flush, through a large vein close to the heart"],"indications":["stopping supraventricular tachycardia that uses the AV node","diagnosing atrial flutter or other atrial tachycardias by briefly slowing the ventricular rate","pharmacologic stress testing"],"adverse_effects":["flushing","chest discomfort","dyspnea or bronchospasm","a sense of impending doom","brief asystole or bradycardia"],"contraindications":["asthma with active bronchospasm","second- or third-degree AV block or sick sinus syndrome without a pacemaker","atrial fibrillation with Wolff-Parkinson-White syndrome"],"interactions":["theophylline and caffeine block its effect, so higher doses may be needed","dipyridamole and carbamazepine increase its effect, so lower doses are needed"],"monitoring":["continuous ECG during the dose"],"overdose":{"features":["brief asystole"],"treatment":["usually passes within seconds; aminophylline if needed"]}}'::jsonb),
  ('adrenal-insufficiency', 1, 'in_review', null, null, '{"kind":"disease","name":"Adrenal insufficiency","aliases":["Addison disease","adrenal crisis"],"systems":["endo"],"rotation":["IM"],"confused_with":[{"script_id":"septic-shock","how_to_tell_apart":"Septic shock also causes fluid-resistant hypotension with fever; adrenal crisis adds hyponatremia, hyperkalemia and hypoglycemia, and responds to hydrocortisone.","compare":[{"label":"Key lab","text":"Low morning cortisol","source_field":"key_findings.labs[2]"},{"label":"Clue","text":"Hyperpigmentation","source_field":"key_findings.exam[1]"},{"label":"Treat","text":"IV hydrocortisone","source_field":"management.first_line[0]"}]}],"pearls":["Hyperkalemia and hyperpigmentation point to primary disease; in secondary disease aldosterone is intact and ACTH is low."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1502236479001"},{"kind":"note","id":"1555720529080"},{"kind":"note","id":"1496623452372","rung":"recall"},{"kind":"note","id":"1502236802283","rung":"recall"},{"kind":"note","id":"1502560818022","rung":"recall"},{"kind":"note","id":"1532693062576","rung":"management"},{"kind":"note","id":"1552216700593","rung":"management"},{"kind":"note","id":"1555720467958","rung":"management"}],"sources":[{"title":"Diagnosis and Treatment of Primary Adrenal Insufficiency: An Endocrine Society Clinical Practice Guideline (2016)"}],"epidemiology":{"who":"Primary disease is usually autoimmune; secondary disease most often follows stopping long-term glucocorticoids","risk_factors":["autoimmune adrenalitis","abrupt withdrawal of long-term steroids","tuberculosis","adrenal hemorrhage","pituitary disease"]},"pathophysiology":"Primary disease destroys the adrenal cortex, losing cortisol and aldosterone; secondary disease lacks ACTH, losing cortisol only.","timeline":{"onset":"Insidious, or a sudden crisis during illness","course":"Needs lifelong replacement; a crisis is fatal without steroids"},"key_findings":{"history":["fatigue and weakness","weight loss","nausea, vomiting and abdominal pain","salt craving"],"exam":["hypotension","hyperpigmentation of skin and gums in primary disease"],"labs":["hyponatremia","hyperkalemia in primary disease","low morning cortisol","hypoglycemia"],"imaging":[]},"diagnosis":{"confirmatory_tests":["morning serum cortisol","ACTH stimulation test (cosyntropin)","plasma ACTH to separate primary from secondary disease"],"criteria":["a peak cortisol below 18 micrograms/dL after cosyntropin confirms adrenal insufficiency"]},"management":{"first_line":["adrenal crisis: IV hydrocortisone 100 mg and IV saline immediately","chronic: hydrocortisone replacement","fludrocortisone in primary disease"],"next_line":["double the steroid dose during illness (sick-day rules)","medical alert identification and an emergency injection kit"]},"complications":["adrenal crisis","shock","death"]}'::jsonb),
  ('alcohol-withdrawal', 1, 'in_review', null, null, '{"kind":"disease","name":"Alcohol withdrawal","aliases":["alcohol withdrawal syndrome","delirium tremens"],"systems":["psych","neuro"],"rotation":["IM","EM","psych"],"confused_with":[],"pearls":["Give thiamine before glucose in heavy drinkers to avoid precipitating Wernicke encephalopathy."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1485313510624"},{"kind":"note","id":"1505859856287"},{"kind":"note","id":"1557061576009"}],"sources":[{"title":"The ASAM Clinical Practice Guideline on Alcohol Withdrawal Management (2020)"}],"epidemiology":{"who":"People who drink heavily every day and stop or cut down, often on hospital admission","risk_factors":["heavy daily drinking","prior withdrawal seizures or delirium tremens","sudden abstinence","older age","acute medical illness"]},"pathophysiology":"Chronic alcohol enhances GABA and suppresses glutamate signalling; stopping leaves unopposed excitation.","timeline":{"onset":"Tremor from about 6 hours; seizures at 12 to 48 hours; delirium tremens at 48 to 96 hours","course":"Delirium tremens can be fatal"},"key_findings":{"history":["time of the last drink","tremor","anxiety","sweating","hallucinations"],"exam":["tremor","tachycardia","hypertension","diaphoresis","agitation or confusion in delirium tremens"],"labs":["hypokalemia","hypomagnesemia","hypophosphatemia","raised GGT","macrocytosis"],"imaging":[]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","CIWA-Ar score to grade severity"],"criteria":["withdrawal symptoms after stopping or reducing heavy, prolonged drinking"]},"management":{"first_line":["benzodiazepines such as lorazepam or chlordiazepoxide, symptom-triggered by CIWA-Ar","thiamine before glucose","correct magnesium and potassium"],"next_line":["phenobarbital for benzodiazepine-resistant withdrawal","ICU for delirium tremens"]},"complications":["withdrawal seizures","delirium tremens","Wernicke encephalopathy","death"]}'::jsonb),
  ('alpha-2-agonists', 1, 'in_review', null, null, '{"kind":"drug","name":"Clonidine and methyldopa","aliases":["central alpha-2 agonists","alpha-2 agonists"],"systems":["cardio","neuro"],"rotation":[],"confused_with":[],"pearls":["Stopping clonidine suddenly causes rebound hypertension, so taper it.","Methyldopa can cause a positive direct Coombs test, sometimes with hemolytic anemia.","Clonidine overdose looks like opioid toxicity: small pupils, sedation and slow breathing."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","adverse_effects"],"MS4":["pearls[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"}],"class":"Centrally acting alpha-2 adrenergic agonists","class_members":["clonidine","methyldopa","guanfacine","dexmedetomidine"],"mechanism":"Stimulate presynaptic alpha-2 receptors in the brainstem, cutting sympathetic outflow, so heart rate, vascular resistance and blood pressure fall.","pharmacokinetics":["methyldopa is a prodrug converted to alpha-methylnorepinephrine","clonidine comes as a tablet or a weekly patch","dexmedetomidine is given IV for sedation"],"indications":["hypertension (clonidine)","hypertension in pregnancy (methyldopa, an option alongside labetalol and nifedipine)","ADHD (clonidine, guanfacine)","opioid and alcohol withdrawal symptoms (clonidine)","ICU sedation (dexmedetomidine)"],"adverse_effects":["dry mouth","sedation","bradycardia","rebound hypertension if stopped suddenly (clonidine)","positive Coombs test and hemolytic anemia (methyldopa)"],"contraindications":["active liver disease (methyldopa)"],"interactions":["beta blockers worsen rebound hypertension when clonidine is stopped"],"monitoring":["blood pressure","heart rate"],"overdose":{"features":["bradycardia","hypotension","small pupils","slow breathing"],"treatment":["supportive care","naloxone sometimes helps"]}}'::jsonb),
  ('amiodarone', 1, 'in_review', null, null, '{"kind":"drug","name":"Amiodarone","aliases":["Cordarone","Pacerone"],"systems":["cardio"],"rotation":[],"confused_with":[],"pearls":["Check thyroid, liver and lung tests before starting amiodarone and during treatment.","Torsades de pointes is rare with amiodarone despite its long QT.","Lower the warfarin dose when starting amiodarone."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","monitoring"],"MS4":["interactions","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}],"class":"Class III antiarrhythmic (potassium channel blocker) with class I, II and IV effects","class_members":["amiodarone","dronedarone, a related drug without iodine"],"mechanism":"Blocks potassium channels, prolonging repolarization, the action potential and the QT interval. It also blocks sodium channels, beta receptors and calcium channels.","pharmacokinetics":["very lipophilic, with a half-life of weeks to months","contains iodine","metabolized by CYP3A4 and inhibits several CYP enzymes"],"indications":["ventricular tachycardia and fibrillation, including cardiac arrest that does not respond to shocks","atrial fibrillation: rhythm control, or rate control when other drugs fail, especially with heart failure"],"adverse_effects":["pulmonary fibrosis","hypothyroidism or hyperthyroidism","liver injury with raised transaminases","corneal deposits","blue-gray skin discoloration","photosensitivity","bradycardia and QT prolongation","optic neuropathy"],"contraindications":["sinus node disease or AV block without a pacemaker","cardiogenic shock"],"interactions":["raises the effect of warfarin","raises digoxin levels","raises statin levels and the risk of myopathy"],"monitoring":["thyroid function tests","liver function tests","chest X-ray and pulmonary function tests","eye exams"],"overdose":{"features":["bradycardia","hypotension","QT prolongation"],"treatment":["supportive care","pacing if needed"]}}'::jsonb),
  ('angiotensin-receptor-blockers', 1, 'in_review', null, null, '{"kind":"drug","name":"Angiotensin II receptor blockers","aliases":["ARBs","sartans"],"systems":["cardio","renal"],"rotation":[],"confused_with":[{"script_id":"ace-inhibitors","how_to_tell_apart":"ARBs block the angiotensin II receptor and do not raise bradykinin, so they rarely cause cough; ACE inhibitors block angiotensin II production and raise bradykinin, causing cough and more angioedema."}],"pearls":["Drugs ending in -sartan are ARBs; drugs ending in -pril are ACE inhibitors.","Losartan lowers uric acid slightly.","After angioedema on an ACE inhibitor, an ARB can usually be tried with caution."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","adverse_effects"],"MS4":["indications[3]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2025 AHA/ACC Guideline for the Prevention, Detection, Evaluation, and Management of High Blood Pressure in Adults"}],"class":"Angiotensin II receptor blockers (AT1 receptor antagonists)","class_members":["losartan","valsartan","candesartan","irbesartan","telmisartan","olmesartan"],"mechanism":"Block the AT1 receptor, so angiotensin II cannot constrict vessels or release aldosterone. Unlike ACE inhibitors, they do not raise bradykinin.","pharmacokinetics":["losartan is a prodrug with an active metabolite","most are dosed once daily"],"indications":["hypertension","heart failure with reduced ejection fraction, when an ARNI is not feasible and ACE inhibitors are not tolerated","diabetic kidney disease and chronic kidney disease with proteinuria","Marfan syndrome (losartan, to slow aortic dilation)"],"adverse_effects":["hyperkalemia","acute rise in creatinine","hypotension","teratogenic: fetal kidney damage","angioedema, much rarer than with ACE inhibitors"],"contraindications":["pregnancy","bilateral renal artery stenosis","combined use with an ACE inhibitor"],"interactions":["potassium-sparing diuretics and potassium supplements raise potassium","NSAIDs blunt the effect and add to kidney injury","raise lithium levels"],"monitoring":["potassium and creatinine 1 to 2 weeks after starting"],"overdose":{"features":["hypotension"],"treatment":["IV fluids"]}}'::jsonb),
  ('aortic-dissection', 1, 'in_review', null, null, '{"kind":"disease","name":"Aortic dissection","aliases":["dissecting aorta"],"systems":["cardio"],"rotation":["IM","EM","surgery"],"confused_with":[{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"ACS gives pressure-like pain with ECG changes and a troponin rise; dissection gives tearing pain to the back, unequal arm pressures and a widened mediastinum, and anticoagulation can be fatal.","compare":[{"label":"Pain","text":"Tearing, to the back","source_field":"key_findings.history[0]"},{"label":"Exam","text":"Arm BP gap over 20 mmHg","source_field":"key_findings.exam[0]"},{"label":"First drug","text":"IV beta-blocker","source_field":"management.first_line[0]"}]}],"pearls":["Give the beta-blocker before any vasodilator: lowering blood pressure alone causes reflex tachycardia that increases shear on the aorta."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1532186604247"},{"kind":"note","id":"1532189052771"},{"kind":"note","id":"1532189236664"},{"kind":"note","id":"1556206626632"},{"kind":"note","id":"1557012534276"}],"sources":[{"title":"2022 ACC/AHA Guideline for the Diagnosis and Management of Aortic Disease"}],"epidemiology":{"who":"Older adults with hypertension; younger patients with connective tissue disease","risk_factors":["hypertension","Marfan syndrome","bicuspid aortic valve","cocaine use","prior aortic surgery","pregnancy"]},"pathophysiology":"A tear in the aortic intima lets blood split the media, creating a false lumen that can extend, block branch arteries or rupture.","timeline":{"onset":"Sudden","course":"Type A (ascending aorta) is a surgical emergency with high early mortality"},"key_findings":{"history":["sudden severe tearing chest pain radiating to the back","syncope","stroke-like symptoms"],"exam":["blood pressure difference of more than 20 mmHg between arms","pulse deficit","new murmur of aortic regurgitation"],"labs":["D-dimer usually raised"],"imaging":["widened mediastinum on chest X-ray","CT angiography of the chest showing an intimal flap"]},"diagnosis":{"confirmatory_tests":["CT angiography of the chest","transesophageal echocardiogram if unstable"],"criteria":["Stanford type A involves the ascending aorta; type B does not"]},"management":{"first_line":["IV beta-blocker such as esmolol to lower heart rate and blood pressure","pain control","emergency surgery for type A"],"next_line":["add a vasodilator such as nicardipine after beta-blockade","medical management for uncomplicated type B","endovascular repair for complicated type B"]},"complications":["aortic rupture","cardiac tamponade","acute aortic regurgitation","stroke","mesenteric or limb ischemia"]}'::jsonb),
  ('aortic-regurgitation', 1, 'in_review', null, null, '{"kind":"disease","name":"Aortic regurgitation","aliases":["aortic insufficiency"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"aortic-stenosis","how_to_tell_apart":"Aortic regurgitation is an early diastolic decrescendo murmur with a wide pulse pressure and bounding pulses; aortic stenosis is a systolic crescendo-decrescendo murmur with a slow-rising pulse."},{"script_id":"mitral-stenosis","how_to_tell_apart":"Aortic regurgitation is an early diastolic decrescendo murmur at the left sternal border with a wide pulse pressure; mitral stenosis is a mid-diastolic rumble at the apex after an opening snap."}],"pearls":["Avoid slowing the heart with a beta blocker alone in severe aortic regurgitation; a longer diastole worsens the leak.","Acute aortic regurgitation lacks the wide pulse pressure and bounding pulses, because the ventricle has not dilated.","The Austin Flint murmur is a mid-diastolic rumble at the apex from the regurgitant jet hitting the mitral leaflet."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["epidemiology.risk_factors","management.first_line"],"MS4":["diagnosis.criteria","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease"},{"title":"2025 ESC/EACTS Guidelines for the management of valvular heart disease"}],"epidemiology":{"who":"Adults; chronic disease from a bicuspid valve or a dilated aortic root, acute disease from endocarditis or aortic dissection","risk_factors":["bicuspid aortic valve","aortic root dilation (Marfan syndrome, hypertension, aging)","rheumatic heart disease","infective endocarditis","aortic dissection","syphilitic aortitis","ankylosing spondylitis"]},"pathophysiology":"Blood leaks back from the aorta into the left ventricle in diastole. In chronic disease the ventricle dilates and hypertrophies eccentrically, stroke volume rises and the pulse pressure widens. Acute regurgitation floods a ventricle that has not adapted, causing pulmonary edema and shock.","timeline":{"onset":"Acute (dissection, endocarditis) or chronic over years","course":"Chronic disease is silent for years until the ventricle fails"},"key_findings":{"history":["exertional dyspnea","palpitations","pounding heartbeat when lying down","sudden pulmonary edema in acute disease"],"exam":["early diastolic decrescendo murmur at the left sternal border, louder sitting forward in expiration","wide pulse pressure","water-hammer (Corrigan) pulse","head bobbing (de Musset sign)","Austin Flint murmur","other signs: Quincke pulsations in the nail beds, Duroziez murmur over the femoral artery, Traube pistol-shot sounds, Hill sign (leg pressure far above arm pressure)"],"labs":[],"imaging":["echocardiogram showing the regurgitant jet, its cause and the size of the left ventricle","CT or MRI of the aorta when the root is dilated"]},"diagnosis":{"confirmatory_tests":["transthoracic echocardiogram"],"criteria":["severe chronic regurgitation with symptoms, an ejection fraction of 55% or less, or a left ventricular end-systolic dimension above 50 mm is an indication for valve replacement"]},"management":{"first_line":["aortic valve replacement for severe regurgitation with symptoms, or with left ventricular dysfunction or dilation","vasodilators (ACE inhibitors, ARBs, dihydropyridines) to control blood pressure"],"next_line":["urgent surgery for acute regurgitation","treat the cause: dissection repair, antibiotics for endocarditis"]},"complications":["heart failure","acute pulmonary edema in acute disease","sudden death"]}'::jsonb),
  ('aortic-stenosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Aortic stenosis","aliases":["calcific aortic stenosis","aortic valve stenosis"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"hypertrophic-cardiomyopathy","how_to_tell_apart":"Both cause a systolic ejection murmur, but the murmur of aortic stenosis radiates to the carotids and gets softer with Valsalva, while the murmur of hypertrophic cardiomyopathy gets louder with Valsalva or standing. Aortic stenosis is a disease of older adults; hypertrophic cardiomyopathy is inherited and shows up in the young.","compare":[{"label":"Murmur","text":"RUSB, radiates to carotids","source_field":"key_findings.exam[0]"},{"label":"Valsalva","text":"Softer","source_field":"pearls[0]"},{"label":"Who","text":"Older adults, calcified valve","source_field":"epidemiology.who"}]},{"script_id":"mitral-regurgitation","how_to_tell_apart":"Aortic stenosis is a crescendo-decrescendo murmur at the right upper sternal border radiating to the carotids; mitral regurgitation is a holosystolic blowing murmur at the apex radiating to the axilla.","compare":[{"label":"Murmur","text":"Crescendo-decrescendo, RUSB","source_field":"key_findings.exam[0]"},{"label":"Radiates","text":"To the carotids","source_field":"key_findings.exam[0]"}]},{"script_id":"aortic-regurgitation","how_to_tell_apart":"Aortic stenosis is a systolic crescendo-decrescendo murmur with a slow-rising pulse; aortic regurgitation is an early diastolic decrescendo murmur with a wide pulse pressure and bounding pulses."}],"pearls":["The murmur of aortic stenosis gets softer with Valsalva and standing, because less blood fills the ventricle.","The classic symptoms of severe aortic stenosis are syncope, angina and dyspnea from heart failure.","Severe aortic stenosis with GI bleeding from angiodysplasia is Heyde syndrome."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease"},{"title":"2025 ESC/EACTS Guidelines for the management of valvular heart disease"}],"epidemiology":{"who":"Older adults with age-related calcification of a normal valve, and younger adults with a bicuspid valve","risk_factors":["older age","bicuspid aortic valve","rheumatic heart disease","chronic kidney disease","atherosclerotic risk factors"]},"pathophysiology":"The aortic valve calcifies and narrows, obstructing left ventricular outflow. The ventricle hypertrophies concentrically to keep up its output and eventually fails. Coronary flow cannot meet the thick wall''s oxygen demand, which causes angina.","timeline":{"onset":"Silent for decades; symptoms appear once the stenosis is severe","course":"Once symptoms start, survival without valve replacement is short"},"key_findings":{"history":["exertional dyspnea","angina","syncope on exertion","heart failure symptoms"],"exam":["harsh crescendo-decrescendo systolic murmur at the right upper sternal border radiating to the carotids","slow-rising, weak carotid pulse (pulsus parvus et tardus)","soft or absent second heart sound","sustained apex beat"],"labs":["BNP rises as the ventricle fails"],"imaging":["echocardiogram showing a calcified valve, a small valve area and a high gradient","ECG with left ventricular hypertrophy"]},"diagnosis":{"confirmatory_tests":["transthoracic echocardiogram"],"criteria":["Severe aortic stenosis: mean gradient 40 mmHg or more, peak velocity 4 m/s or more, or a valve area of 1 square centimeter or less"]},"management":{"first_line":["aortic valve replacement for severe stenosis with symptoms or an ejection fraction below 50%: transcatheter (TAVR) or surgical (SAVR)","TAVR is preferred for older patients and those at high surgical risk","serial echocardiograms while asymptomatic; earlier replacement is increasingly offered for severe disease"],"next_line":["balloon valvuloplasty as a bridge in unstable patients","cautious diuresis; avoid strong vasodilators, which can drop blood pressure"]},"complications":["heart failure","sudden cardiac death","GI bleeding from angiodysplasia (Heyde syndrome)","infective endocarditis"]}'::jsonb),
  ('asthma-exacerbation', 1, 'in_review', null, null, '{"kind":"disease","name":"Asthma exacerbation","aliases":["acute asthma","asthma attack"],"systems":["pulm"],"rotation":["IM","EM","peds"],"confused_with":[{"script_id":"copd-exacerbation","how_to_tell_apart":"COPD affects older smokers, and its airflow limitation persists between exacerbations; in asthma it is largely reversible.","compare":[{"label":"Who","text":"Any age, with asthma","source_field":"epidemiology.who"},{"label":"Clue","text":"Cough worse at night","source_field":"key_findings.history[3]"},{"label":"Oxygen target","text":"93 to 95%","source_field":"management.first_line[2]"}]}],"pearls":["A normal or rising PaCO2 during an asthma attack means the patient is tiring and may need intubation."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1473536778562"},{"kind":"note","id":"1474580971787"},{"kind":"note","id":"1495911001468"},{"kind":"note","id":"1539204159804"},{"kind":"note","id":"1550662680256"},{"kind":"note","id":"1495894152946","rung":"recall"},{"kind":"note","id":"1537631653103","rung":"recall"},{"kind":"note","id":"1550662682692","rung":"recall"}],"sources":[{"title":"Global Strategy for Asthma Management and Prevention (GINA 2024)"}],"epidemiology":{"who":"Children and adults with asthma, especially with poor control or prior severe attacks","risk_factors":["viral respiratory infection","allergen exposure","poor adherence to inhaled steroids","smoke exposure","exercise","cold air"]},"pathophysiology":"Airway inflammation, bronchospasm and mucus plugging cause reversible airflow obstruction and air trapping.","timeline":{"onset":"Over hours to days","course":"Usually responds to treatment; severe attacks can progress to respiratory failure"},"key_findings":{"history":["dyspnea","wheeze","chest tightness","cough, often worse at night"],"exam":["expiratory wheeze","tachypnea","accessory muscle use","silent chest in life-threatening attacks"],"labs":["peak expiratory flow below 50% of predicted in a severe attack","a normal or rising PaCO2 is a warning sign of fatigue"],"imaging":["chest X-ray only if pneumothorax or pneumonia is suspected"]},"diagnosis":{"confirmatory_tests":["peak expiratory flow","pulse oximetry","arterial blood gas in severe attacks"],"criteria":["acute worsening of symptoms and lung function from the patient''s usual status"]},"management":{"first_line":["inhaled short-acting beta-agonist (albuterol), repeated","systemic corticosteroids","oxygen to keep saturation 93 to 95%","ipratropium in severe attacks"],"next_line":["IV magnesium sulfate for severe attacks","ICU and intubation for respiratory failure"]},"complications":["respiratory failure","pneumothorax","death"]}'::jsonb),
  ('atherosclerosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Atherosclerosis","aliases":["atherosclerotic disease","atheroma"],"systems":["cardio"],"rotation":["IM"],"confused_with":[],"pearls":["The most common sites, in order, are the abdominal aorta, the coronary arteries, the popliteal arteries and the carotid arteries.","Foam cells, lipid-laden macrophages, are the first sign of atherosclerosis, in the fatty streak.","Plaques with a thin fibrous cap and a large lipid core are the ones that rupture."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[1]"],"MS3":["epidemiology.risk_factors","management.first_line"],"MS4":["diagnosis.criteria","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Robbins and Cotran Pathologic Basis of Disease"},{"title":"2019 ACC/AHA Guideline on the Primary Prevention of Cardiovascular Disease"},{"title":"Development and Validation of the American Heart Association''s PREVENT Equations (Circulation, 2024)"}],"epidemiology":{"who":"Adults, rising with age; the underlying cause of most heart attacks, ischemic strokes and peripheral artery disease","risk_factors":["smoking","high LDL cholesterol","hypertension","diabetes","older age","male sex","family history of premature cardiovascular disease","obesity"]},"pathophysiology":"Endothelial injury lets LDL into the arterial intima, where it is oxidized. Monocytes follow, become macrophages and take up the lipid to become foam cells, forming a fatty streak. Smooth muscle cells migrate in and lay down collagen, forming a fibrous cap over a lipid core. A plaque with a thin cap can rupture and trigger thrombosis.","timeline":{"onset":"Fatty streaks begin in childhood; plaques grow silently for decades","course":"Stable plaques narrow arteries and cause ischemia on exertion; ruptured plaques cause acute coronary syndrome or stroke"},"key_findings":{"history":["often silent until a plaque narrows or ruptures","exertional chest pain","claudication","transient neurologic symptoms"],"exam":["weak peripheral pulses","arterial bruits","xanthelasma"],"labs":["raised LDL cholesterol","raised HbA1c in diabetes","raised high-sensitivity CRP"],"imaging":["coronary artery calcium score on CT","carotid ultrasound showing plaque","angiography showing stenosis"]},"diagnosis":{"confirmatory_tests":["imaging of the affected arteries: coronary CT angiography, carotid ultrasound or the ankle-brachial index"],"criteria":["the AHA PREVENT equations estimate 10-year cardiovascular risk to guide prevention"]},"management":{"first_line":["stop smoking","statin","blood pressure and diabetes control","exercise and a Mediterranean-style diet"],"next_line":["aspirin for established disease","revascularization for critical stenosis"]},"complications":["myocardial infarction","ischemic stroke","peripheral artery disease","abdominal aortic aneurysm","mesenteric ischemia"]}'::jsonb),
  ('atrial-fibrillation', 1, 'in_review', null, null, '{"kind":"disease","name":"Atrial fibrillation","aliases":["AF","AFib"],"systems":["cardio"],"rotation":["IM","EM","FM"],"confused_with":[{"script_id":"atrial-flutter","how_to_tell_apart":"Atrial fibrillation is irregularly irregular with no organized P waves; atrial flutter is regular, with sawtooth waves and a ventricular rate often near 150."}],"pearls":["Direct oral anticoagulants are preferred over warfarin, except with a mechanical heart valve or moderate to severe mitral stenosis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[{"kind":"note","id":"1578765152246"},{"kind":"note","id":"1472147549163","rung":"recall"},{"kind":"note","id":"1550409526747","rung":"recall"},{"kind":"note","id":"1557341643876","rung":"recall"},{"kind":"note","id":"1497748713929","rung":"management"},{"kind":"note","id":"1532380404222","rung":"management"},{"kind":"note","id":"1555275580254","rung":"management"}],"sources":[{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}],"epidemiology":{"who":"Mostly older adults; prevalence rises sharply with age","risk_factors":["older age","hypertension","heart failure","valvular heart disease","obesity","obstructive sleep apnea","alcohol","hyperthyroidism"]},"pathophysiology":"Disorganized atrial electrical activity, often triggered from the pulmonary veins, causes loss of atrial contraction and an irregular ventricular response; stasis in the left atrial appendage lets clot form and embolize.","timeline":{"onset":"Sudden or unnoticed","course":"Often starts paroxysmal and becomes persistent or permanent over time"},"key_findings":{"history":["palpitations","dyspnea","fatigue","lightheadedness","sometimes no symptoms"],"exam":["irregularly irregular pulse","variable intensity of S1"],"labs":["TSH to look for hyperthyroidism"],"imaging":["echocardiogram for chamber size, valves and ejection fraction"]},"diagnosis":{"confirmatory_tests":["12-lead ECG"],"criteria":["ECG: irregularly irregular rhythm with no discernible P waves"]},"management":{"first_line":["rate control with a beta-blocker or a nondihydropyridine calcium channel blocker","anticoagulation based on stroke risk (CHA2DS2-VASc)","synchronized cardioversion if hemodynamically unstable"],"next_line":["rhythm control with cardioversion, antiarrhythmic drugs or catheter ablation","if AF has lasted 48 hours or more or the duration is unknown, anticoagulate for 3 weeks before elective cardioversion or exclude clot with a transesophageal echocardiogram"]},"complications":["ischemic stroke","systemic embolism","tachycardia-induced cardiomyopathy","heart failure"]}'::jsonb),
  ('atrial-flutter', 1, 'in_review', null, null, '{"kind":"disease","name":"Atrial flutter","aliases":["typical atrial flutter"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"atrial-fibrillation","how_to_tell_apart":"Atrial flutter is regular, with sawtooth waves and a ventricular rate often near 150; atrial fibrillation is irregularly irregular with no organized P waves."}],"pearls":["A regular narrow-complex tachycardia at exactly 150 beats per minute should make you think of flutter with 2:1 block.","Adenosine briefly slows the ventricular rate and unmasks flutter waves, but does not stop flutter.","Ablation of the cavotricuspid isthmus cures typical flutter more reliably than ablation cures atrial fibrillation."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.imaging[0]"],"MS3":["management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia"},{"title":"2019 ESC Guidelines for the management of patients with supraventricular tachycardia"},{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}],"epidemiology":{"who":"Older adults, often with heart or lung disease","risk_factors":["structural heart disease","COPD","heart failure","prior cardiac surgery","hyperthyroidism","alcohol"]},"pathophysiology":"A macroreentrant circuit loops around the right atrium through the cavotricuspid isthmus at about 300 beats per minute. The AV node usually conducts every second beat, giving a ventricular rate of about 150.","timeline":{"onset":"Sudden palpitations","course":"Often alternates with atrial fibrillation"},"key_findings":{"history":["palpitations","dyspnea","fatigue","dizziness"],"exam":["regular tachycardia, often about 150 beats per minute"],"labs":["thyroid function tests"],"imaging":["ECG with sawtooth flutter waves, best seen in II, III and aVF, often with 2:1 block","echocardiogram for structural disease"]},"diagnosis":{"confirmatory_tests":["ECG"],"criteria":[]},"management":{"first_line":["rate control with beta blockers or calcium channel blockers","anticoagulation by the same stroke-risk rules as atrial fibrillation","electrical cardioversion if unstable","catheter ablation of the cavotricuspid isthmus for recurrent typical flutter, which cures it"],"next_line":["antiarrhythmic drugs if ablation is not chosen"]},"complications":["stroke","tachycardia-induced cardiomyopathy","1:1 conduction with very fast rates"]}'::jsonb),
  ('atrial-septal-defect', 1, 'in_review', null, null, '{"kind":"disease","name":"Atrial septal defect","aliases":["ASD","secundum ASD"],"systems":["cardio"],"rotation":["peds","IM"],"confused_with":[{"script_id":"ventricular-septal-defect","how_to_tell_apart":"An ASD gives wide fixed splitting of S2 and a soft pulmonary flow murmur, often found in adults; a VSD gives a harsh holosystolic murmur at the left lower sternal border in infancy."}],"pearls":["Fixed splitting of S2 is the hallmark: the split does not change with breathing.","The murmur comes from extra flow across the pulmonary valve, not from blood crossing the defect.","Ostium primum defects are part of the atrioventricular canal defects seen in Down syndrome."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[1]","management.next_line[1]"]},"anki_refs":[],"sources":[{"title":"Moss & Adams'' Heart Disease in Infants, Children, and Adolescents"},{"title":"2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"}],"epidemiology":{"who":"Children and adults, more often female; often first found in adulthood","risk_factors":["trisomy 21","Holt-Oram syndrome","fetal alcohol syndrome"]},"pathophysiology":"A hole in the atrial septum, most often ostium secundum, lets blood shunt left to right. The right heart and lungs carry extra volume and the right ventricle enlarges. Rarely, pulmonary hypertension reverses the shunt (Eisenmenger syndrome).","timeline":{"onset":"Often silent in childhood","course":"Dyspnea and atrial arrhythmias often start in adulthood"},"key_findings":{"history":["often no symptoms","exertional dyspnea in adults","palpitations from atrial fibrillation or flutter","stroke from paradoxical embolism"],"exam":["wide, fixed splitting of S2","systolic ejection murmur at the left upper sternal border from extra pulmonary flow"],"labs":[],"imaging":["echocardiogram with a bubble study showing the defect and shunt","ECG with right axis deviation and incomplete right bundle branch block","transesophageal echo to size the defect"]},"diagnosis":{"confirmatory_tests":["transthoracic echocardiogram with Doppler, plus a bubble study if needed","transesophageal echocardiogram"],"criteria":[]},"management":{"first_line":["closure, by catheter device for secundum defects or by surgery, when the right heart is enlarged"],"next_line":["observation of small defects without right heart enlargement","closure is contraindicated once severe pulmonary hypertension has reversed the shunt"]},"complications":["right heart failure","atrial fibrillation","paradoxical embolism","Eisenmenger syndrome"]}'::jsonb),
  ('atrioventricular-block', 1, 'in_review', null, null, '{"kind":"disease","name":"Atrioventricular block","aliases":["heart block","AV block"],"systems":["cardio"],"rotation":["IM"],"confused_with":[],"pearls":["Mobitz I (Wenckebach): the PR interval lengthens beat by beat until a QRS drops.","Mobitz II rarely responds to atropine, because the block is below the AV node.","Lyme carditis causes reversible heart block that usually resolves with antibiotics."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.imaging[0]"],"MS3":["management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2018 ACC/AHA/HRS Guideline on the Evaluation and Management of Patients With Bradycardia and Cardiac Conduction Delay"}],"epidemiology":{"who":"Older adults most often; any age with drugs, infection or congenital disease","risk_factors":["degenerative fibrosis of the conduction system with age","inferior myocardial infarction","AV nodal blocking drugs: beta blockers, calcium channel blockers, digoxin","hyperkalemia","Lyme carditis","high vagal tone in athletes","neonatal lupus from maternal anti-Ro antibodies","sarcoidosis"]},"pathophysiology":"Conduction from atria to ventricles is delayed or blocked in the AV node or below it, in the His-Purkinje system. Block in the AV node (first-degree, Mobitz I) is usually benign; Mobitz II and most acquired third-degree block are below the node (infranodal) and unstable, while congenital block and block after an inferior MI are often nodal with a junctional escape rhythm.","timeline":{"onset":"Sudden or gradual","course":"First-degree and Mobitz I are usually benign; Mobitz II and third-degree block can cause syncope and death"},"key_findings":{"history":["often no symptoms","fatigue","dizziness","syncope (Stokes-Adams attacks)"],"exam":["bradycardia","cannon A waves in the neck in complete heart block","varying loudness of S1 in complete heart block"],"labs":["electrolytes, especially potassium","Lyme serology where relevant","digoxin level if taking it"],"imaging":["ECG: first-degree, PR over 200 ms; Mobitz I, PR lengthens until a beat drops; Mobitz II, a sudden dropped beat with a constant PR; third-degree, P waves and QRS complexes independent"]},"diagnosis":{"confirmatory_tests":["12-lead ECG","ambulatory ECG monitoring for intermittent block"],"criteria":[]},"management":{"first_line":["treat reversible causes: stop AV nodal blockers, treat Lyme disease","atropine for symptomatic bradycardia","a beta-agonist infusion such as dopamine, epinephrine or isoproterenol if atropine fails","transcutaneous or transvenous pacing if unstable"],"next_line":["permanent pacemaker for Mobitz II, high-grade AV block, third-degree block, or symptomatic block without a reversible cause"]},"complications":["syncope","sudden cardiac death","heart failure"]}'::jsonb),
  ('bacterial-meningitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Bacterial meningitis","aliases":["meningitis"],"systems":["neuro"],"rotation":["IM","EM","peds","neuro"],"confused_with":[],"pearls":["Never delay antibiotics for a CT or lumbar puncture: take blood cultures and treat immediately."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1515891636007"},{"kind":"note","id":"1517169728142"},{"kind":"note","id":"1537556677772","rung":"recall"},{"kind":"note","id":"1550409495760","rung":"recall"},{"kind":"note","id":"1575344364515","rung":"recall"},{"kind":"note","id":"1537557489214","rung":"management"},{"kind":"note","id":"1555451147551","rung":"management"},{"kind":"note","id":"1556473561662","rung":"management"}],"sources":[{"title":"2016 ESCMID guideline: diagnosis and treatment of acute bacterial meningitis"},{"title":"IDSA Practice Guidelines for the Management of Bacterial Meningitis (2004)"}],"epidemiology":{"who":"Infants, older adults and the immunocompromised; outbreaks in college dormitories","risk_factors":["age over 50","immunosuppression","asplenia","cochlear implant","CSF leak","crowded living such as dormitories"]},"pathophysiology":"Bacteria, most often Streptococcus pneumoniae or Neisseria meningitidis in adults, invade the subarachnoid space and inflame the meninges.","timeline":{"onset":"Hours to a day","course":"Fatal without prompt antibiotics; survivors may have hearing loss or neurologic deficits"},"key_findings":{"history":["fever","headache","neck stiffness","confusion"],"exam":["nuchal rigidity","altered mental status","petechial or purpuric rash in meningococcal disease","Kernig and Brudzinski signs, which are insensitive"],"labs":["CSF: high neutrophils, high protein, low glucose","CSF Gram stain and culture"],"imaging":["CT head before lumbar puncture only with focal deficits, papilledema, seizures, reduced consciousness or immunocompromise"]},"diagnosis":{"confirmatory_tests":["lumbar puncture with CSF analysis","blood cultures"],"criteria":["CSF neutrophilic pleocytosis with low glucose and high protein"]},"management":{"first_line":["empiric ceftriaxone plus vancomycin","add ampicillin if over 50 or immunocompromised (to cover Listeria)","dexamethasone before or with the first antibiotic dose"],"next_line":["droplet precautions and prophylaxis for close contacts in meningococcal disease","tailor antibiotics to culture"]},"complications":["hearing loss","seizures","cerebral edema","death"]}'::jsonb),
  ('beta-blockers', 1, 'in_review', null, null, '{"kind":"drug","name":"Beta blockers","aliases":["beta-blockers","beta-adrenergic blockers"],"systems":["cardio"],"rotation":[],"confused_with":[],"pearls":["Most beta-1 selective blockers start with A to M (atenolol, bisoprolol, esmolol, metoprolol), plus nebivolol; nonselective ones start with N to Z (nadolol, propranolol, timolol).","Stopping a beta blocker suddenly can cause rebound tachycardia and angina.","Glucagon reverses beta blocker overdose because it raises cAMP in heart cells without using beta receptors."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","contraindications"],"MS4":["overdose.treatment","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"class":"Beta-adrenergic receptor antagonists (class II antiarrhythmics)","class_members":["metoprolol","atenolol","bisoprolol","esmolol","nebivolol","propranolol","nadolol","carvedilol","labetalol"],"mechanism":"Block beta-1 receptors in the heart, lowering heart rate, contractility and renin release, and slowing conduction through the AV node. Nonselective agents also block beta-2 receptors in the airways and vessels. Carvedilol and labetalol also block alpha-1 receptors.","pharmacokinetics":["esmolol is very short-acting and given IV","atenolol is cleared by the kidneys; metoprolol and propranolol by the liver","propranolol is lipophilic and crosses into the brain"],"indications":["angina","after myocardial infarction","heart failure with reduced ejection fraction (carvedilol, metoprolol succinate, bisoprolol)","rate control in atrial fibrillation","hypertension","hypertrophic cardiomyopathy","thyrotoxicosis symptoms","migraine prevention and essential tremor (propranolol)","variceal bleeding prevention (nonselective agents)"],"adverse_effects":["bradycardia","hypotension","AV block","bronchospasm, mostly with nonselective agents","fatigue","erectile dysfunction","masked signs of hypoglycemia, such as tremor and palpitations","worsening of acute decompensated heart failure"],"contraindications":["asthma, for nonselective agents","second- or third-degree AV block or symptomatic bradycardia","acute decompensated heart failure","vasospastic angina"],"interactions":["verapamil or diltiazem add to bradycardia and AV block"],"monitoring":["heart rate","blood pressure"],"overdose":{"features":["bradycardia","hypotension","hypoglycemia"],"treatment":["IV glucagon","atropine","high-dose insulin with glucose"]}}'::jsonb),
  ('carbonic-anhydrase-inhibitors', 1, 'in_review', null, null, '{"kind":"drug","name":"Carbonic anhydrase inhibitors","aliases":["acetazolamide"],"systems":["renal","neuro"],"rotation":[],"confused_with":[{"script_id":"loop-diuretics","how_to_tell_apart":"Acetazolamide acts on the proximal tubule and causes a metabolic acidosis; loop diuretics act on the thick ascending limb and cause a metabolic alkalosis."}],"pearls":["Acetazolamide causes a normal anion gap (hyperchloremic) metabolic acidosis, like a proximal renal tubular acidosis.","In mountain sickness, the acidosis drives breathing and offsets the respiratory alkalosis of altitude.","Alkaline urine favors calcium phosphate stones but helps dissolve uric acid and cystine stones."],"difficulty_tiers":{"MS1-2":["mechanism","adverse_effects"],"MS3":["indications"],"MS4":["pearls[1]","contraindications[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"}],"class":"Carbonic anhydrase inhibitors","class_members":["acetazolamide","methazolamide","dorzolamide and brinzolamide, as eye drops"],"mechanism":"Inhibit carbonic anhydrase in the proximal tubule, so less bicarbonate is reabsorbed. Bicarbonate, sodium and water are lost in the urine, causing a mild diuresis and a hyperchloremic metabolic acidosis.","pharmacokinetics":["the effect fades within days as plasma bicarbonate falls","dorzolamide and brinzolamide are used as eye drops"],"indications":["glaucoma","acute mountain sickness prevention","idiopathic intracranial hypertension","metabolic alkalosis","urinary alkalinization for uric acid or cystine stones"],"adverse_effects":["hyperchloremic metabolic acidosis (normal anion gap)","hypokalemia","paresthesias","calcium phosphate kidney stones","sulfonamide allergy reactions"],"contraindications":["cirrhosis, because alkaline urine raises ammonia absorption","severe hypokalemia or acidosis"],"interactions":["raise the risk of salicylate toxicity"],"monitoring":["electrolytes and bicarbonate"],"overdose":{"features":["metabolic acidosis","hypokalemia"],"treatment":["supportive care"]}}'::jsonb),
  ('cardiac-tamponade', 1, 'in_review', null, null, '{"kind":"disease","name":"Cardiac tamponade","aliases":["pericardial tamponade"],"systems":["cardio"],"rotation":["IM","EM","surgery"],"confused_with":[{"script_id":"constrictive-pericarditis","how_to_tell_apart":"Tamponade is fluid under pressure with pulsus paradoxus that can develop in minutes; constrictive pericarditis is a rigid pericardium with a knock and Kussmaul sign that develops over months."}],"pearls":["Avoid positive-pressure ventilation and diuretics, which reduce filling further.","Pulsus paradoxus is a fall in systolic pressure of more than 10 mmHg on inspiration.","Electrical alternans comes from the heart swinging in the fluid."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]","management.next_line"]},"anki_refs":[],"sources":[{"title":"2015 ESC Guidelines for the diagnosis and management of pericardial diseases"},{"title":"Tintinalli''s Emergency Medicine: A Comprehensive Study Guide"}],"epidemiology":{"who":"Patients with a pericardial effusion from cancer, infection, uremia, surgery or trauma","risk_factors":["malignancy","pericarditis","uremia","chest trauma","cardiac surgery or procedures","aortic dissection into the pericardium"]},"pathophysiology":"Fluid in the pericardial sac raises the pressure around the heart until the chambers cannot fill. Stroke volume and blood pressure fall. Fluid that collects quickly causes tamponade even in small volumes.","timeline":{"onset":"Minutes (trauma, rupture) to weeks (a slowly growing effusion)","course":"Fatal without drainage"},"key_findings":{"history":["dyspnea","chest pain or pressure","light-headedness or syncope"],"exam":["Beck triad: hypotension, raised jugular venous pressure and muffled heart sounds","pulsus paradoxus","tachycardia","clear lungs"],"labs":[],"imaging":["echocardiogram showing an effusion with right atrial collapse in late diastole and systole, or right ventricular collapse in diastole","ECG with low voltage and electrical alternans","chest X-ray with a large, water-bottle-shaped heart"]},"diagnosis":{"confirmatory_tests":["bedside echocardiogram"],"criteria":["a clinical diagnosis, supported by echo signs of chamber collapse"]},"management":{"first_line":["urgent pericardiocentesis","IV fluids to support filling while preparing"],"next_line":["surgical pericardial window for recurrent or loculated effusions","emergency thoracotomy for traumatic tamponade with arrest"]},"complications":["obstructive shock","cardiac arrest with pulseless electrical activity"]}'::jsonb),
  ('cardiogenic-shock', 1, 'in_review', null, null, '{"kind":"disease","name":"Cardiogenic shock","aliases":["cardiac shock"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"septic-shock","how_to_tell_apart":"Cardiogenic shock is cold and wet: low cardiac output, a high wedge pressure and high systemic resistance; septic shock is usually warm, with a normal or high cardiac output, low systemic resistance and a low wedge pressure."}],"pearls":["Cardiogenic shock is cold and wet: cold extremities and congested lungs.","The SHOCK trial showed early revascularization improves survival in MI-related cardiogenic shock.","Norepinephrine is the preferred first vasopressor; dopamine causes more arrhythmias."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.imaging[2]","management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Patients With Acute Coronary Syndromes"},{"title":"SCAI SHOCK Stage Classification Expert Consensus Update: A Review and Incorporation of Validation Studies (2022)"}],"epidemiology":{"who":"Patients with acute myocardial infarction, most often a large anterior MI, or with decompensated heart failure","risk_factors":["large acute myocardial infarction","mechanical complications of MI: papillary muscle rupture, ventricular septal rupture, free wall rupture","acute decompensated heart failure","myocarditis","arrhythmias","severe valve disease"]},"pathophysiology":"The heart pumps too little to perfuse the organs despite adequate filling: low cardiac output, high filling pressures (a high wedge pressure) and high systemic vascular resistance as the body clamps down.","timeline":{"onset":"Hours, often within 24 hours of an MI","course":"Mortality around 40%; early revascularization improves survival"},"key_findings":{"history":["chest pain","dyspnea","confusion"],"exam":["systolic pressure below 90","cold, clammy, mottled skin","raised JVP","pulmonary crackles","low urine output"],"labs":["raised lactate","raised troponin","raised creatinine and liver enzymes"],"imaging":["ECG for ST elevation","echocardiogram for ventricular function and mechanical complications","pulmonary artery catheter: low cardiac index, high wedge pressure, high systemic vascular resistance"]},"diagnosis":{"confirmatory_tests":["clinical hypoperfusion with hypotension","echocardiogram","pulmonary artery catheter in selected patients"],"criteria":["systolic pressure below 90 mmHg with signs of hypoperfusion, caused by cardiac failure"]},"management":{"first_line":["emergency revascularization (PCI) of the culprit artery in MI-related shock","norepinephrine for blood pressure","dobutamine or milrinone for low output"],"next_line":["mechanical circulatory support such as Impella or ECMO in selected patients","surgery for mechanical complications"]},"complications":["multiorgan failure","death","arrhythmias"]}'::jsonb),
  ('cellulitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Cellulitis","aliases":[],"systems":["derm"],"rotation":["IM","EM","FM"],"confused_with":[{"script_id":"deep-vein-thrombosis","how_to_tell_apart":"DVT causes swelling and calf pain without spreading redness or fever, and compression ultrasound shows a clot.","compare":[{"label":"Leg","text":"Warm, red, poorly defined","source_field":"key_findings.exam[0]"},{"label":"Test","text":"Clinical diagnosis","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"Cephalexin","source_field":"management.first_line[0]"}]}],"pearls":["Redness of both legs is rarely cellulitis; think of stasis dermatitis first."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1517003863108"},{"kind":"note","id":"1517003902640"},{"kind":"note","id":"1517087494979"},{"kind":"note","id":"1517087779618"},{"kind":"note","id":"1578854051059"}],"sources":[{"title":"Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections: 2014 Update by the IDSA"}],"epidemiology":{"who":"Adults with breaks in the skin barrier, leg edema or obesity","risk_factors":["skin breaks such as cuts or tinea pedis","lymphedema","obesity","venous insufficiency","prior cellulitis","diabetes"]},"pathophysiology":"Bacterial infection of the dermis and subcutaneous tissue, most often from beta-hemolytic streptococci and less often from Staphylococcus aureus.","timeline":{"onset":"Over 1 to 3 days","course":"Improves within 48 to 72 hours of antibiotics"},"key_findings":{"history":["spreading redness","pain","fever in some"],"exam":["warm, red, tender skin with poorly defined borders","usually one leg","no fluctuance unless there is an abscess"],"labs":["blood cultures only if systemically unwell"],"imaging":["ultrasound if an abscess is suspected"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis"],"criteria":["acute spreading erythema, warmth and tenderness, usually on one side"]},"management":{"first_line":["oral cephalexin for nonpurulent cellulitis","elevate the limb","treat tinea pedis or other entry points"],"next_line":["add MRSA coverage (trimethoprim-sulfamethoxazole or doxycycline) for purulent infection","IV cefazolin if systemically ill","incision and drainage for an abscess"]},"complications":["abscess","bacteremia","necrotizing fasciitis","recurrence"]}'::jsonb),
  ('cholesterol-synthesis', 1, 'in_review', null, null, '{"kind":"pathway","name":"Cholesterol synthesis","aliases":["mevalonate pathway"],"systems":["cardio","general"],"rotation":[],"confused_with":[],"pearls":["HMG-CoA is also made in mitochondria for ketone bodies; cholesterol synthesis uses HMG-CoA made in the cytosol.","The liver makes most of its cholesterol at night, so short-acting statins are taken in the evening.","Steroid hormones start when cholesterol is cleaved to pregnenolone."],"difficulty_tiers":{"MS1-2":["steps","rate_limiting_enzyme","regulation"],"MS3":["drug_targets"],"MS4":["deficiencies[0]","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Lippincott Illustrated Reviews: Biochemistry"},{"title":"Harper''s Illustrated Biochemistry"}],"location":"Cytosol and smooth endoplasmic reticulum, mostly in liver cells","purpose":"Makes cholesterol from acetyl-CoA, for cell membranes, bile acids, steroid hormones and vitamin D.","steps":["acetyl-CoA to HMG-CoA by HMG-CoA synthase","HMG-CoA to mevalonate by HMG-CoA reductase","mevalonate to isoprene units (isopentenyl pyrophosphate)","isoprene units join to make squalene","squalene to lanosterol by squalene epoxidase and cyclase, then to cholesterol"],"rate_limiting_enzyme":"HMG-CoA reductase","regulation":["insulin activates HMG-CoA reductase","glucagon inhibits HMG-CoA reductase","low cell cholesterol turns on synthesis through SREBP","high cell cholesterol speeds the breakdown of HMG-CoA reductase"],"cofactors":["NADPH, from the pentose phosphate pathway"],"deficiencies":["Smith-Lemli-Opitz syndrome: 7-dehydrocholesterol reductase deficiency at the last step, with low cholesterol, high 7-dehydrocholesterol, intellectual disability and fused second and third toes"],"drug_targets":["statins inhibit HMG-CoA reductase","terbinafine inhibits squalene epoxidase in the fungal version of the pathway, which makes ergosterol"],"treatment":["Smith-Lemli-Opitz syndrome: dietary cholesterol supplementation"]}'::jsonb),
  ('class-ia-antiarrhythmics', 1, 'in_review', null, null, '{"kind":"drug","name":"Class IA antiarrhythmics","aliases":["class IA"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"class-ib-antiarrhythmics","how_to_tell_apart":"Class IA drugs block sodium and potassium channels and prolong the QT interval; class IB drugs block sodium weakly, shorten the action potential and act mainly on ischemic ventricles."}],"pearls":["Class IA drugs: quinidine, procainamide and disopyramide.","Procainamide is a classic choice for atrial fibrillation with Wolff-Parkinson-White syndrome, because it slows the accessory pathway.","Procainamide and hydralazine both cause drug-induced lupus, more often in slow acetylators."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["adverse_effects","indications"],"MS4":["pharmacokinetics[0]","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2017 AHA/ACC/HRS Guideline for Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death"}],"class":"Class IA antiarrhythmics (sodium channel blockers that also block potassium channels)","class_members":["quinidine","procainamide","disopyramide"],"mechanism":"Block fast sodium channels moderately, slowing phase 0 depolarization, and block potassium channels, prolonging the action potential, the refractory period and the QT interval.","pharmacokinetics":["procainamide is acetylated to NAPA, an active metabolite with class III effects; slow acetylators accumulate the parent drug","quinidine inhibits CYP2D6"],"indications":["atrial and ventricular arrhythmias, now rarely","procainamide for stable wide-complex tachycardia and for atrial fibrillation with Wolff-Parkinson-White syndrome"],"adverse_effects":["QT prolongation and torsades de pointes","cinchonism with quinidine: tinnitus, headache, hearing loss","drug-induced lupus with procainamide","anticholinergic effects and heart failure with disopyramide","diarrhea and thrombocytopenia with quinidine"],"contraindications":["long QT","heart failure (disopyramide)"],"interactions":["quinidine raises digoxin levels","other QT-prolonging drugs add to the risk of torsades"],"monitoring":["QT interval","ANA, and procainamide levels with NAPA"],"overdose":{"features":["QT prolongation","torsades de pointes","wide QRS"],"treatment":["IV magnesium for torsades","sodium bicarbonate for a wide QRS","overdrive pacing"]}}'::jsonb),
  ('class-ib-antiarrhythmics', 1, 'in_review', null, null, '{"kind":"drug","name":"Class IB antiarrhythmics","aliases":["class IB"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"class-ia-antiarrhythmics","how_to_tell_apart":"Class IB drugs block sodium weakly, shorten the action potential and act mainly on ischemic ventricles; class IA drugs block sodium and potassium channels and prolong the QT interval."},{"script_id":"class-ic-antiarrhythmics","how_to_tell_apart":"Class IB drugs block sodium weakly and target ischemic ventricular tissue; class IC drugs block sodium strongly, widen the QRS and raise mortality after a myocardial infarction."}],"pearls":["Class IB drugs target ischemic, depolarized ventricular tissue; unlike class IC, they are not linked to excess mortality after MI, though lidocaine is not given routinely to prevent arrhythmias.","Lidocaine toxicity often starts with perioral numbness and ends in seizures.","Phenytoin, an antiseizure drug, is also a class IB antiarrhythmic."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","adverse_effects"],"MS4":["overdose.treatment","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2017 AHA/ACC/HRS Guideline for Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death"}],"class":"Class IB antiarrhythmics (weak sodium channel blockers)","class_members":["lidocaine","mexiletine","phenytoin"],"mechanism":"Block sodium channels with fast on-off kinetics, preferring depolarized (ischemic) tissue, and shorten the action potential. They act mainly on the ventricles and barely change the QT interval.","pharmacokinetics":["lidocaine has high first-pass metabolism, so it is given IV","mexiletine is the oral analogue"],"indications":["ventricular arrhythmias, especially with ischemia or after myocardial infarction","ventricular fibrillation or pulseless VT that persists after shocks (lidocaine, as an alternative to amiodarone)","ventricular arrhythmias from digoxin toxicity"],"adverse_effects":["neurologic toxicity: perioral numbness, tremor, confusion and seizures","bradycardia and hypotension at high levels"],"contraindications":["severe heart block without a pacemaker"],"interactions":["beta blockers and cimetidine slow lidocaine clearance"],"monitoring":["neurologic symptoms","lidocaine levels during long infusions"],"overdose":{"features":["seizures","perioral numbness","bradycardia"],"treatment":["benzodiazepines for seizures","IV lipid emulsion for severe toxicity"]}}'::jsonb),
  ('class-ic-antiarrhythmics', 1, 'in_review', null, null, '{"kind":"drug","name":"Class IC antiarrhythmics","aliases":["class IC"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"class-ib-antiarrhythmics","how_to_tell_apart":"Class IC drugs block sodium strongly, widen the QRS and raise mortality after a myocardial infarction; class IB drugs block sodium weakly and target ischemic ventricular tissue."}],"pearls":["The CAST trial showed flecainide and encainide raised mortality after myocardial infarction.","Pill in the pocket: a single dose of flecainide or propafenone at the onset of atrial fibrillation, with a beta blocker or calcium channel blocker.","Class IC drugs show use-dependence: QRS widening is worse at faster heart rates."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","contraindications"],"MS4":["pearls[0]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}],"class":"Class IC antiarrhythmics (strong sodium channel blockers)","class_members":["flecainide","propafenone"],"mechanism":"Block sodium channels strongly and dissociate slowly, markedly slowing conduction and widening the QRS, with little effect on the length of the action potential. Propafenone also blocks beta receptors.","pharmacokinetics":["both are metabolized by CYP2D6"],"indications":["atrial fibrillation in a structurally normal heart, including the pill-in-the-pocket approach","supraventricular tachycardias"],"adverse_effects":["proarrhythmia, especially ventricular tachycardia","atrial flutter with fast 1:1 conduction","QRS widening","dizziness and blurred vision"],"contraindications":["structural heart disease: prior myocardial infarction, heart failure or marked left ventricular hypertrophy","coronary artery disease"],"interactions":["CYP2D6 inhibitors raise levels","given with an AV nodal blocker to prevent 1:1 flutter conduction"],"monitoring":["QRS width on the ECG, especially at higher doses or faster heart rates"],"overdose":{"features":["wide QRS","ventricular arrhythmias","hypotension"],"treatment":["sodium bicarbonate","supportive care"]}}'::jsonb),
  ('clostridioides-difficile-infection', 1, 'in_review', null, null, '{"kind":"disease","name":"Clostridioides difficile infection","aliases":["C. diff","CDI"],"systems":["gi"],"rotation":["IM"],"confused_with":[],"pearls":["Alcohol hand rubs do not kill C. difficile spores; wash with soap and water."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1578670876178"},{"kind":"note","id":"1543274938312","rung":"recall"},{"kind":"note","id":"1555757715051","rung":"recall"},{"kind":"note","id":"1581107333267","rung":"recall"},{"kind":"note","id":"1495753784346","rung":"management"},{"kind":"note","id":"1523551767770","rung":"management"},{"kind":"note","id":"1543275630756","rung":"management"}],"sources":[{"title":"Clinical Practice Guideline by IDSA and SHEA: 2021 Focused Update Guidelines on Management of Clostridioides difficile Infection in Adults"}],"epidemiology":{"who":"Hospitalized and older adults, especially after antibiotics","risk_factors":["recent antibiotics","hospitalization","older age","proton pump inhibitors","immunosuppression"]},"pathophysiology":"Antibiotics disrupt the gut flora, letting toxin-producing C. difficile colonize the colon and cause colitis.","timeline":{"onset":"Days to weeks after antibiotics","course":"About 1 in 5 recur after treatment"},"key_findings":{"history":["three or more watery stools in 24 hours","abdominal cramping","recent antibiotics, especially clindamycin, fluoroquinolones or cephalosporins"],"exam":["abdominal tenderness","fever"],"labs":["leukocytosis, sometimes very high","raised creatinine in severe disease"],"imaging":["CT for suspected fulminant colitis or toxic megacolon"]},"diagnosis":{"confirmatory_tests":["stool test for C. difficile toxin or toxin gene (PCR)"],"criteria":["test only unformed stool, from patients with 3 or more unexplained loose stools in 24 hours","severe: white count of 15,000 or more, or creatinine above 1.5 mg/dL"]},"management":{"first_line":["oral fidaxomicin or oral vancomycin","stop the inciting antibiotic if possible","contact precautions and soap-and-water hand hygiene"],"next_line":["fulminant disease: oral vancomycin plus IV metronidazole, and a surgical consult","recurrence: fidaxomicin, bezlotoxumab or fecal microbiota transplant"]},"complications":["toxic megacolon","colonic perforation","recurrence","death"]}'::jsonb),
  ('coarctation-of-the-aorta', 1, 'in_review', null, null, '{"kind":"disease","name":"Coarctation of the aorta","aliases":["aortic coarctation"],"systems":["cardio"],"rotation":["peds","IM"],"confused_with":[{"script_id":"essential-hypertension","how_to_tell_apart":"Coarctation is a secondary cause of hypertension, with high arm pressure, low leg pressure and weak, delayed femoral pulses; in essential hypertension arm and leg pressures match and the pulses are normal."}],"pearls":["Always feel the femoral pulses in a young person with hypertension.","Rib notching takes years to appear, so it is a sign in older children and adults, not newborns.","Coarctation is linked with bicuspid aortic valve and Turner syndrome."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam"],"MS3":["key_findings.imaging[0]","management.first_line"],"MS4":["pearls[1]"]},"anki_refs":[],"sources":[{"title":"Moss & Adams'' Heart Disease in Infants, Children, and Adolescents"},{"title":"2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"}],"epidemiology":{"who":"Infants and children, more often boys, and girls with Turner syndrome","risk_factors":["Turner syndrome","bicuspid aortic valve","male sex"]},"pathophysiology":"A narrowing of the aorta, usually just beyond the left subclavian artery near the ductus. Pressure is high above the narrowing and low below it; collateral arteries, including the intercostals, enlarge to bypass it.","timeline":{"onset":"Severe coarctation presents in newborns when the duct closes; milder disease presents later with hypertension","course":"Untreated, it leads to heart failure, aortic dissection and stroke"},"key_findings":{"history":["headaches and nosebleeds","leg claudication","shock in a newborn when the duct closes"],"exam":["high blood pressure in the arms with low pressure in the legs","weak or delayed femoral pulses (brachiofemoral delay)","systolic murmur heard over the back"],"labs":[],"imaging":["chest X-ray with rib notching from enlarged intercostal arteries and a figure-3 sign","echocardiogram","CT or MRI angiography"]},"diagnosis":{"confirmatory_tests":["echocardiogram","CT or MRI angiography"],"criteria":[]},"management":{"first_line":["prostaglandin E1 for a newborn with duct-dependent coarctation","surgical repair, or balloon angioplasty with stenting"],"next_line":["lifelong follow-up for re-narrowing, hypertension and aneurysm"]},"complications":["hypertension","heart failure","aortic dissection","intracranial berry aneurysm rupture","infective endarteritis"]}'::jsonb),
  ('community-acquired-pneumonia', 1, 'in_review', null, null, '{"kind":"disease","name":"Community-acquired pneumonia","aliases":["CAP"],"systems":["pulm"],"rotation":["IM","EM","FM"],"confused_with":[{"script_id":"pulmonary-embolism","how_to_tell_apart":"Pulmonary embolism also causes pleuritic pain, dyspnea and tachycardia, but usually has clear lungs and a near-normal chest X-ray despite hypoxemia; suspect it when there are risk factors for clots.","compare":[{"label":"Lungs","text":"Focal crackles","source_field":"key_findings.exam[0]"},{"label":"Imaging","text":"New focal infiltrate","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Antibiotics","source_field":"management.first_line[0]"}]},{"script_id":"heart-failure-exacerbation","how_to_tell_apart":"Heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP, with bilateral interstitial edema and effusions on X-ray rather than a focal consolidation, and usually no fever.","compare":[{"label":"Lungs","text":"Focal crackles","source_field":"key_findings.exam[0]"},{"label":"Key lab","text":"Leukocytosis","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"Antibiotics","source_field":"management.first_line[0]"}]},{"script_id":"copd-exacerbation","how_to_tell_apart":"A COPD exacerbation brings more dyspnea and sputum in a known smoker, without a new consolidation on chest X-ray.","compare":[{"label":"Exam","text":"Focal crackles","source_field":"key_findings.exam[0]"},{"label":"Chest X-ray","text":"New focal infiltrate","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Antibiotics","source_field":"management.first_line[0]"}]}],"pearls":["CURB-65 (confusion, urea over 19 mg/dL, respiratory rate 30 or more, low blood pressure, age 65 or older) is a quick bedside guide to admission; the ATS/IDSA guideline prefers the Pneumonia Severity Index."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[{"kind":"note","id":"1539882094287"},{"kind":"note","id":"1556196826608"},{"kind":"note","id":"1556924270114"},{"kind":"note","id":"1569457354070"},{"kind":"note","id":"1569458111557"},{"kind":"note","id":"1474503849368","rung":"recall"},{"kind":"note","id":"1504659390894","rung":"recall"},{"kind":"note","id":"1550712326734","rung":"recall"},{"kind":"note","id":"1495908532054","rung":"management"},{"kind":"note","id":"1496497550431","rung":"management"},{"kind":"note","id":"1496498154874","rung":"management"}],"sources":[{"title":"Diagnosis and Treatment of Adults with Community-acquired Pneumonia: An Official Clinical Practice Guideline of the ATS and IDSA (2019)"}],"epidemiology":{"who":"Adults living in the community; risk rises with age and chronic lung disease","risk_factors":["age 65 or older","smoking","COPD","alcohol use disorder","immunosuppression"]},"pathophysiology":"Infection of the lung parenchyma, usually after aspiration of upper airway organisms. Streptococcus pneumoniae is the most common cause; others include Haemophilus influenzae, Mycoplasma pneumoniae, respiratory viruses, Staphylococcus aureus and Legionella.","timeline":{"onset":"Acute, over a few days","course":"Most patients improve within 48 to 72 hours of appropriate antibiotics"},"key_findings":{"history":["fever","cough with sputum","pleuritic chest pain","dyspnea"],"exam":["focal crackles","bronchial breath sounds","dullness to percussion","tachypnea"],"labs":["leukocytosis","hypoxemia"],"imaging":["chest X-ray showing a new lobar or focal infiltrate"]},"diagnosis":{"confirmatory_tests":["chest X-ray"],"criteria":["compatible symptoms plus a new infiltrate on chest imaging"]},"management":{"first_line":["outpatient without comorbidities: amoxicillin or doxycycline (a macrolide only where pneumococcal macrolide resistance is below 25%)","outpatient with comorbidities: amoxicillin-clavulanate or a cephalosporin plus a macrolide or doxycycline, or a respiratory fluoroquinolone alone","inpatient, not severe: ceftriaxone plus azithromycin, or a respiratory fluoroquinolone alone"],"next_line":["add MRSA or Pseudomonas coverage only with prior isolation of those organisms or other validated risk factors","ICU admission for severe pneumonia"]},"complications":["parapneumonic effusion","empyema","sepsis","ARDS","lung abscess"]}'::jsonb),
  ('constrictive-pericarditis', 1, 'in_review', null, null, '{"kind":"disease","name":"Constrictive pericarditis","aliases":["pericardial constriction"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"restrictive-cardiomyopathy","how_to_tell_apart":"Both fill poorly and raise venous pressure, but constrictive pericarditis has a thick, often calcified pericardium, a pericardial knock and a lower BNP; restrictive cardiomyopathy has stiff heart muscle, a high BNP and a normal pericardium.","compare":[{"label":"Problem","text":"Rigid pericardium","source_field":"pathophysiology"},{"label":"BNP","text":"Lower than expected","source_field":"key_findings.labs[0]"}]},{"script_id":"cardiac-tamponade","how_to_tell_apart":"Both limit filling, but constrictive pericarditis is a rigid pericardium with a knock and Kussmaul sign that develops over months; tamponade is fluid under pressure with pulsus paradoxus that can develop in minutes."}],"pearls":["Kussmaul sign is typical of constrictive pericarditis and usually absent in tamponade, where pulsus paradoxus dominates.","A pericardial knock is an early diastolic sound made as filling stops abruptly.","Tuberculosis is the most common cause worldwide."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam"],"MS3":["diagnosis.confirmatory_tests","management.next_line"],"MS4":["pearls[0]","key_findings.imaging[2]"]},"anki_refs":[],"sources":[{"title":"2025 ESC Guidelines for the management of myocarditis and pericarditis"},{"title":"Braunwald''s Heart Disease: A Textbook of Cardiovascular Medicine"}],"epidemiology":{"who":"Adults after pericarditis, cardiac surgery, radiation or tuberculosis","risk_factors":["prior viral or idiopathic pericarditis","cardiac surgery","chest radiation","tuberculosis, the leading cause in low-income countries","connective tissue disease"]},"pathophysiology":"The pericardium thickens, scars and sometimes calcifies into a rigid shell. Early diastolic filling is rapid and then stops abruptly, so venous pressures rise and the two ventricles compete for space (interventricular dependence).","timeline":{"onset":"Months to years after the injury","course":"Progressive right-sided heart failure; cured by pericardiectomy"},"key_findings":{"history":["fatigue","leg swelling","abdominal swelling","exertional dyspnea"],"exam":["raised JVP that rises on inspiration (Kussmaul sign)","pericardial knock in early diastole","ascites and edema out of proportion to lung findings","hepatomegaly"],"labs":["BNP lower than expected for the degree of congestion"],"imaging":["CT or MRI showing a thickened pericardium","chest X-ray showing pericardial calcification","echocardiogram with septal bounce and respiratory variation in filling"]},"diagnosis":{"confirmatory_tests":["cardiac CT or MRI","echocardiogram","cardiac catheterization showing equalized diastolic pressures and interventricular dependence"],"criteria":[]},"management":{"first_line":["diuretics for symptoms","anti-inflammatory therapy if the constriction is new and still inflamed (transient constriction)"],"next_line":["surgical pericardiectomy for chronic constriction"]},"complications":["right heart failure","cardiac cirrhosis","protein-losing enteropathy"]}'::jsonb),
  ('copd-exacerbation', 1, 'in_review', null, null, '{"kind":"disease","name":"COPD exacerbation","aliases":["acute exacerbation of COPD","AECOPD"],"systems":["pulm"],"rotation":["IM","EM"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia adds fever and a new consolidation on chest X-ray; a COPD exacerbation has no new infiltrate.","compare":[{"label":"Exam","text":"Wheeze, long expiration","source_field":"key_findings.exam[0]"},{"label":"Chest X-ray","text":"To exclude pneumonia","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Albuterol with ipratropium","source_field":"management.first_line[0]"}]},{"script_id":"heart-failure-exacerbation","how_to_tell_apart":"Heart failure gives a raised JVP, leg edema, a high BNP and pulmonary edema on chest X-ray.","compare":[{"label":"Exam","text":"Wheeze, long expiration","source_field":"key_findings.exam[0]"},{"label":"Key test","text":"Blood gas: high CO2","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"Albuterol with ipratropium","source_field":"management.first_line[0]"}]},{"script_id":"asthma-exacerbation","how_to_tell_apart":"Asthma usually starts younger, often without a smoking history, and its airflow obstruction is largely reversible between attacks.","compare":[{"label":"Who","text":"Long smoking history","source_field":"epidemiology.who"},{"label":"Clue","text":"More purulent sputum","source_field":"key_findings.history[2]"},{"label":"Oxygen target","text":"88 to 92%","source_field":"management.first_line[3]"}]}],"pearls":["Target oxygen saturation 88 to 92% in COPD; high-flow oxygen can worsen hypercapnia."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1473623659476","rung":"recall"},{"kind":"note","id":"1496356970450","rung":"recall"},{"kind":"note","id":"1556994133668","rung":"recall"},{"kind":"note","id":"1545942903602","rung":"management"},{"kind":"note","id":"1550662680256","rung":"management"},{"kind":"note","id":"1555373219232","rung":"management"}],"sources":[{"title":"Global Strategy for the Diagnosis, Management, and Prevention of COPD (GOLD 2025 Report)"}],"epidemiology":{"who":"Adults with COPD, usually with a long smoking history","risk_factors":["viral respiratory infection","bacterial infection","air pollution","stopping inhalers"]},"pathophysiology":"Airway inflammation, usually triggered by infection, worsens airflow limitation and air trapping, raising the work of breathing and causing hypoxemia and sometimes hypercapnia.","timeline":{"onset":"Over days","course":"Most recover over 1 to 2 weeks; each exacerbation speeds the decline in lung function"},"key_findings":{"history":["worsening dyspnea","increased sputum volume","increased sputum purulence","cough"],"exam":["wheeze and prolonged expiration","accessory muscle use","pursed-lip breathing"],"labs":["arterial blood gas: hypercapnia and respiratory acidosis in severe cases"],"imaging":["chest X-ray to exclude pneumonia, pneumothorax or heart failure"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","arterial blood gas","chest X-ray"],"criteria":["acute worsening of dyspnea, cough or sputum beyond day-to-day variation"]},"management":{"first_line":["short-acting bronchodilators (albuterol with ipratropium)","systemic corticosteroids for 5 days","antibiotics when sputum purulence increases","controlled oxygen targeting saturation 88 to 92%"],"next_line":["noninvasive ventilation for hypercapnic respiratory acidosis","intubation if noninvasive ventilation fails"]},"complications":["hypercapnic respiratory failure","pneumothorax","death"]}'::jsonb),
  ('coxiella-burnetii', 1, 'in_review', null, null, '{"kind":"bug","name":"Coxiella burnetii","aliases":["Q fever organism"],"systems":["cardio","pulm"],"rotation":[],"confused_with":[{"script_id":"hacek-organisms","how_to_tell_apart":"Both cause culture-negative endocarditis, but Coxiella comes from farm animals and is diagnosed by serology, while HACEK organisms come from the mouth and eventually grow in blood cultures."}],"pearls":["Q fever is the classic cause of culture-negative endocarditis in a farmer or veterinarian.","Coxiella was once grouped with the rickettsiae, but it spreads by inhalation, not ticks, and causes no rash.","Phase II antibodies dominate in acute Q fever; phase I antibodies dominate in chronic infection."],"difficulty_tiers":{"MS1-2":["morphology","transmission"],"MS3":["diseases","diagnosis"],"MS4":["treatment[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"Diagnosis and Management of Q Fever — United States, 2013: Recommendations from CDC and the Q Fever Working Group"}],"morphology":"Small obligate intracellular gram-negative coccobacillus with a hardy spore-like form","lab_features":["does not grow in routine blood cultures","diagnosed by serology (phase I and phase II antibodies)"],"transmission":["inhaled dust or aerosols from infected cattle, sheep and goats, especially their birth products","no tick needed, unlike the rickettsiae"],"virulence_factors":["a spore-like small-cell variant that survives drying and heat","survives inside macrophage phagolysosomes"],"diseases":["acute Q fever with fever, pneumonia and hepatitis","chronic Q fever with culture-negative endocarditis","vascular graft infection"],"diagnosis":["serology: a high phase I IgG points to chronic infection","PCR","echocardiogram for endocarditis"],"treatment":["acute Q fever: doxycycline","endocarditis: doxycycline plus hydroxychloroquine for at least 18 months"],"prevention":["vaccine for high-risk workers in some countries","care with animal birth products"]}'::jsonb),
  ('decompensated-cirrhosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Decompensated cirrhosis","aliases":["cirrhosis","end-stage liver disease"],"systems":["gi"],"rotation":["IM"],"confused_with":[],"pearls":["Spontaneous bacterial peritonitis is diagnosed by an ascitic neutrophil count of 250 cells/mm3 or more."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1486522758122"},{"kind":"note","id":"1486522767302"},{"kind":"note","id":"1486591126064"},{"kind":"note","id":"1495561175263"},{"kind":"note","id":"1531956908372"},{"kind":"note","id":"1495497512091","rung":"recall"},{"kind":"note","id":"1567452654959","rung":"recall"},{"kind":"note","id":"1567452654960","rung":"recall"},{"kind":"note","id":"1557251726524","rung":"management"},{"kind":"note","id":"1580013594763","rung":"management"},{"kind":"note","id":"1580014252557","rung":"management"}],"sources":[{"title":"AASLD Practice Guidance: Diagnosis, Evaluation, and Management of Ascites, Spontaneous Bacterial Peritonitis and Hepatorenal Syndrome (2021)"},{"title":"Baveno VII: Renewing consensus in portal hypertension (2022)"}],"epidemiology":{"who":"Adults with chronic liver disease","risk_factors":["alcohol-related liver disease","chronic hepatitis C","chronic hepatitis B","metabolic dysfunction-associated steatotic liver disease"]},"pathophysiology":"Chronic liver injury causes fibrosis and portal hypertension, leading to ascites, varices and loss of the liver''s synthetic and detoxifying function.","timeline":{"onset":"Develops over years; decompensation can be sudden","course":"Decompensation marks a sharp fall in survival; transplant is the cure"},"key_findings":{"history":["abdominal swelling","jaundice","confusion","vomiting blood or black stools"],"exam":["ascites","jaundice","spider angiomas","palmar erythema","asterixis"],"labs":["low albumin","prolonged INR","raised bilirubin","low platelets"],"imaging":["ultrasound: nodular liver, splenomegaly, ascites"]},"diagnosis":{"confirmatory_tests":["diagnostic paracentesis for new ascites or any admission with ascites","serum-ascites albumin gradient"],"criteria":["decompensation means ascites, variceal bleeding, hepatic encephalopathy or jaundice","a serum-ascites albumin gradient of 1.1 g/dL or more means portal hypertension"]},"management":{"first_line":["sodium restriction and diuretics (spironolactone with furosemide) for ascites","lactulose for hepatic encephalopathy","nonselective beta-blocker such as carvedilol to prevent variceal bleeding"],"next_line":["large-volume paracentesis with albumin for tense ascites","add rifaximin to lactulose","refer for liver transplant evaluation"]},"complications":["spontaneous bacterial peritonitis","hepatorenal syndrome","variceal bleeding","hepatic encephalopathy","hepatocellular carcinoma"]}'::jsonb),
  ('deep-vein-thrombosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Deep vein thrombosis","aliases":["DVT"],"systems":["heme_onc","cardio"],"rotation":["IM","EM","surgery"],"confused_with":[{"script_id":"cellulitis","how_to_tell_apart":"Cellulitis gives warm, red, tender skin with a spreading edge and often fever; DVT gives swelling and calf pain, and ultrasound shows a noncompressible vein.","compare":[{"label":"Leg","text":"Pitting edema","source_field":"key_findings.exam[1]"},{"label":"Test","text":"Compression ultrasound","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"DOAC for 3+ months","source_field":"management.first_line[0]"}]},{"script_id":"pulmonary-embolism","how_to_tell_apart":"PE adds dyspnea, pleuritic pain and hypoxemia; they are the same disease, so look for both.","compare":[{"label":"Symptom","text":"One swollen leg","source_field":"key_findings.history[0]"},{"label":"Test","text":"Compression ultrasound","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"DOAC for 3+ months","source_field":"management.first_line[0]"}]}],"pearls":["Virchow''s triad: venous stasis, endothelial injury and hypercoagulability."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1511025803136"},{"kind":"note","id":"1511025895605"},{"kind":"note","id":"1511025928050"},{"kind":"note","id":"1511028541153"},{"kind":"note","id":"1549586054765","rung":"recall"},{"kind":"note","id":"1550708813822","rung":"recall"},{"kind":"note","id":"1557843697920","rung":"recall"},{"kind":"note","id":"1474340749040","rung":"management"},{"kind":"note","id":"1511028698049","rung":"management"},{"kind":"note","id":"1532736174421","rung":"management"}],"sources":[{"title":"Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline and Expert Panel Report (2021)"}],"epidemiology":{"who":"Adults with risk factors for venous thromboembolism","risk_factors":["recent surgery","immobilization","active cancer","prior VTE","estrogen use or pregnancy","inherited thrombophilia"]},"pathophysiology":"Venous stasis, endothelial injury and hypercoagulability (Virchow''s triad) lead to thrombus in the deep veins, usually of the leg.","timeline":{"onset":"Over days","course":"Can embolize to the lungs; may leave post-thrombotic syndrome"},"key_findings":{"history":["unilateral leg swelling","calf pain"],"exam":["calf swelling more than 3 cm compared with the other leg","pitting edema of one leg","tenderness along the deep veins"],"labs":["raised D-dimer, useful to rule out DVT when pretest probability is low"],"imaging":["compression ultrasound showing a noncompressible vein"]},"diagnosis":{"confirmatory_tests":["compression ultrasound","D-dimer to rule out DVT when the Wells score is low"],"criteria":["the Wells score estimates pretest probability"]},"management":{"first_line":["anticoagulation with a direct oral anticoagulant such as apixaban or rivaroxaban for at least 3 months"],"next_line":["low-molecular-weight heparin in pregnancy","IVC filter only if anticoagulation is contraindicated"]},"complications":["pulmonary embolism","post-thrombotic syndrome","phlegmasia cerulea dolens"]}'::jsonb),
  ('diabetic-ketoacidosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Diabetic ketoacidosis","aliases":["DKA"],"systems":["endo"],"rotation":["IM","EM"],"confused_with":[{"script_id":"acute-pancreatitis","how_to_tell_apart":"DKA causes abdominal pain and can raise lipase, but the labs show an anion gap acidosis with high ketones, and the pain eases as the acidosis is corrected; in pancreatitis the pain persists and imaging shows an inflamed pancreas.","compare":[{"label":"Key lab","text":"Anion gap acidosis","source_field":"key_findings.labs[1]"},{"label":"Exam","text":"Kussmaul breathing","source_field":"key_findings.exam[0]"},{"label":"Treat","text":"IV insulin infusion","source_field":"management.first_line[1]"}]},{"script_id":"hyperosmolar-hyperglycemic-state","how_to_tell_apart":"HHS has much higher glucose and osmolality with little or no ketosis or acidosis, and develops over days rather than hours.","compare":[{"label":"Glucose","text":"Usually over 250 mg/dL","source_field":"key_findings.labs[0]"},{"label":"Acidosis","text":"Anion gap acidosis","source_field":"key_findings.labs[1]"},{"label":"Ketones","text":"High beta-hydroxybutyrate","source_field":"key_findings.labs[2]"}]}],"pearls":["Check potassium before starting insulin: if it is below 3.5 mEq/L, replace it first and hold insulin, because insulin drives potassium into cells."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line","diagnosis.criteria"],"MS4":["pearls[0]","management.next_line"]},"anki_refs":[{"kind":"note","id":"1462327211125","rung":"recall"},{"kind":"note","id":"1502564341435","rung":"recall"},{"kind":"note","id":"1502845294644","rung":"recall"},{"kind":"note","id":"1462327382493","rung":"management"},{"kind":"note","id":"1552260881200","rung":"management"},{"kind":"note","id":"1568856424118","rung":"management"}],"sources":[{"title":"Hyperglycemic Crises in Adults With Diabetes: A Consensus Report (Diabetes Care, 2024)"}],"epidemiology":{"who":"Mostly people with type 1 diabetes, often as the first presentation; also type 2 diabetes under acute stress or on SGLT2 inhibitors","risk_factors":["infection","insulin omission","new-onset diabetes","SGLT2 inhibitors","myocardial infarction","pancreatitis"]},"pathophysiology":"Insulin deficiency plus excess counterregulatory hormones (glucagon, cortisol, catecholamines) drive lipolysis and hepatic ketogenesis, causing an anion gap metabolic acidosis. Hyperglycemia causes an osmotic diuresis with volume depletion and a total-body potassium deficit.","timeline":{"onset":"Develops over hours, usually less than 24 hours","course":"Resolves over about a day with fluids, insulin and potassium; can recur if the precipitant is not treated"},"key_findings":{"history":["polyuria and polydipsia","nausea and vomiting","abdominal pain"],"exam":["Kussmaul respirations (deep, rapid breathing)","fruity (acetone) breath","signs of volume depletion: tachycardia, dry mucous membranes"],"labs":["glucose usually above 250 mg/dL","anion gap metabolic acidosis","raised serum beta-hydroxybutyrate","serum potassium often normal or high despite a total-body deficit"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum beta-hydroxybutyrate","venous blood gas","basic metabolic panel with anion gap"],"criteria":["glucose of 200 mg/dL or more, or known diabetes","ketosis: beta-hydroxybutyrate of 3.0 mmol/L or more, or urine ketones 2+ or more","acidosis: pH below 7.3 and/or bicarbonate below 18 mEq/L"]},"management":{"first_line":["IV isotonic fluids","IV insulin infusion","potassium replacement"],"next_line":["add dextrose to the fluids when glucose falls below 250 mg/dL","bicarbonate only if pH is below 7.0","overlap subcutaneous basal insulin by 1 to 2 hours before stopping the infusion","treat the precipitant"]},"complications":["hypokalemia","hypoglycemia","cerebral edema, mainly in children","recurrence after stopping the infusion too early"]}'::jsonb),
  ('digoxin', 1, 'in_review', null, null, '{"kind":"drug","name":"Digoxin","aliases":["digitalis","Lanoxin"],"systems":["cardio"],"rotation":[],"confused_with":[],"pearls":["In acute digoxin poisoning, hyperkalemia predicts death and is an indication for antibody fragments.","Digoxin improves symptoms and cuts hospitalizations in heart failure but does not lower mortality.","Scooped ST segments (the Salvador Dali sag) on the ECG are a digoxin effect, not toxicity."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","interactions","monitoring"],"MS4":["overdose.treatment","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"class":"Cardiac glycoside","class_members":["digoxin"],"mechanism":"Inhibits the sodium-potassium ATPase (Na/K ATPase) in heart muscle. Intracellular sodium rises, so the sodium-calcium exchanger removes less calcium, and more calcium is available for contraction. It also raises vagal tone, slowing the AV node.","pharmacokinetics":["cleared by the kidneys, so the dose is cut in kidney disease","narrow therapeutic range","long half-life of about 36 to 48 hours"],"indications":["rate control in atrial fibrillation, especially with heart failure","symptom control in heart failure with reduced ejection fraction"],"adverse_effects":["nausea, vomiting and abdominal pain","yellow-green vision (xanthopsia) or blurred vision","confusion","arrhythmias of almost any kind, classically atrial tachycardia with block or bidirectional ventricular tachycardia","hyperkalemia in acute overdose"],"contraindications":["atrial fibrillation with Wolff-Parkinson-White syndrome","second- or third-degree AV block","hypertrophic obstructive cardiomyopathy"],"interactions":["hypokalemia, hypomagnesemia and hypercalcemia increase toxicity","amiodarone, verapamil and quinidine raise digoxin levels","loop and thiazide diuretics cause hypokalemia, which increases toxicity"],"monitoring":["digoxin level","potassium and kidney function"],"overdose":{"features":["nausea and vomiting","visual changes","arrhythmias","hyperkalemia"],"treatment":["digoxin-specific antibody fragments (DigiFab)","correct potassium and magnesium"]}}'::jsonb),
  ('dihydropyridine-calcium-channel-blockers', 1, 'in_review', null, null, '{"kind":"drug","name":"Dihydropyridine calcium channel blockers","aliases":["dihydropyridines","DHP calcium channel blockers"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"non-dihydropyridine-calcium-channel-blockers","how_to_tell_apart":"Dihydropyridines act mainly on arteries and lower blood pressure without slowing the heart; verapamil and diltiazem act mainly on the heart, slowing the rate and AV conduction.","compare":[{"label":"Acts on","text":"Arteries","source_field":"mechanism"},{"label":"Heart rate","text":"Little effect","source_field":"mechanism"}]}],"pearls":["Ankle edema from dihydropyridines comes from arteriolar dilation, not fluid retention, so diuretics barely help; adding an ACE inhibitor or ARB does.","Drugs ending in -dipine are dihydropyridines.","Nimodipine improves outcomes after subarachnoid hemorrhage."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","contraindications"],"MS4":["overdose.treatment","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2025 AHA/ACC Guideline for the Prevention, Detection, Evaluation, and Management of High Blood Pressure in Adults"}],"class":"Dihydropyridine calcium channel blockers","class_members":["amlodipine","nifedipine","felodipine","nicardipine","clevidipine","nimodipine"],"mechanism":"Block L-type calcium channels mainly in vascular smooth muscle, dilating arteries and lowering blood pressure. At usual doses they have little effect on heart rate or contractility.","pharmacokinetics":["amlodipine has a long half-life and is taken once daily","nicardipine and clevidipine are given IV and titrated quickly"],"indications":["hypertension","stable angina","vasospastic angina","Raynaud phenomenon","hypertensive emergency (IV nicardipine or clevidipine)","subarachnoid hemorrhage, to reduce injury from vasospasm (nimodipine)"],"adverse_effects":["peripheral edema","headache","flushing","reflex tachycardia","gingival hyperplasia"],"contraindications":["short-acting nifedipine in acute coronary syndrome","heart failure with reduced ejection fraction, except amlodipine and felodipine, which are neutral"],"interactions":["CYP3A4 inhibitors raise levels","combined with beta blockers, which offset the reflex tachycardia"],"monitoring":["blood pressure","ankle swelling"],"overdose":{"features":["hypotension","reflex tachycardia, or bradycardia in severe overdose"],"treatment":["IV calcium","high-dose insulin with glucose","vasopressors"]}}'::jsonb),
  ('dilated-cardiomyopathy', 1, 'in_review', null, null, '{"kind":"disease","name":"Dilated cardiomyopathy","aliases":["DCM","congestive cardiomyopathy"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"hypertrophic-cardiomyopathy","how_to_tell_apart":"Dilated cardiomyopathy has a big, thin-walled ventricle that pumps weakly, with a low ejection fraction; hypertrophic cardiomyopathy has a thick, stiff ventricle that pumps normally or too well."}],"pearls":["Dilated cardiomyopathy shows eccentric hypertrophy; hypertrophic cardiomyopathy shows concentric, often asymmetric, hypertrophy.","Peripartum cardiomyopathy appears in the last month of pregnancy or up to 5 months after delivery.","Doxorubicin cardiotoxicity is dose-dependent and largely irreversible; dexrazoxane helps prevent it."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.risk_factors"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2023 ESC Guidelines for the management of cardiomyopathies"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"epidemiology":{"who":"Adults of any age; the most common cardiomyopathy","risk_factors":["genetic variants, often in titin","heavy alcohol use","myocarditis, often viral","doxorubicin and other anthracyclines","the peripartum period","cocaine use","Chagas disease","hemochromatosis","thyroid disease"]},"pathophysiology":"The ventricles dilate and contract weakly, causing heart failure with a reduced ejection fraction. The heart shows eccentric hypertrophy, with sarcomeres added in series.","timeline":{"onset":"Usually gradual heart failure symptoms","course":"Progressive; ventricular arrhythmias and sudden death are risks"},"key_findings":{"history":["exertional dyspnea","orthopnea","fatigue","leg swelling"],"exam":["S3","displaced apex beat","raised jugular venous pressure","murmur of functional mitral regurgitation"],"labs":["raised BNP","iron studies, thyroid tests and HIV testing to look for causes"],"imaging":["echocardiogram showing a dilated left ventricle with a low ejection fraction","cardiac MRI to look for myocarditis or infiltration","chest X-ray with a large, globular heart"]},"diagnosis":{"confirmatory_tests":["echocardiogram"],"criteria":["a dilated left ventricle with reduced systolic function, not explained by coronary disease or abnormal loading conditions"]},"management":{"first_line":["guideline-directed therapy for heart failure with reduced ejection fraction","treat the cause: stop alcohol or the toxic drug"],"next_line":["ICD for an ejection fraction of 35% or less despite therapy","heart transplant in end-stage disease"]},"complications":["heart failure","ventricular arrhythmias and sudden death","thromboembolism from a mural thrombus","functional mitral regurgitation"]}'::jsonb),
  ('enterococcus', 1, 'in_review', null, null, '{"kind":"bug","name":"Enterococcus","aliases":["enterococci","Enterococcus faecalis","Enterococcus faecium"],"systems":["cardio","renal"],"rotation":[],"confused_with":[{"script_id":"viridans-streptococci","how_to_tell_apart":"Both cause subacute endocarditis. Enterococci grow in 6.5% salt, come from the gut and urinary tract and follow GI or urinary procedures; viridans streptococci are alpha-hemolytic, come from the mouth and follow dental work.","compare":[{"label":"Gram stain","text":"Cocci in pairs, short chains","source_field":"morphology"},{"label":"Source","text":"Gut flora","source_field":"transmission[0]"},{"label":"Key test","text":"Grows in 6.5% NaCl","source_field":"lab_features[1]"}]},{"script_id":"staphylococcus-aureus","how_to_tell_apart":"Enterococci grow in pairs and short chains, are catalase-negative and grow in 6.5% salt; S. aureus grows in clusters and is catalase- and coagulase-positive.","compare":[{"label":"Gram stain","text":"Cocci in pairs, short chains","source_field":"morphology"},{"label":"Course","text":"Subacute endocarditis","source_field":"diseases[1]"},{"label":"Key test","text":"Grows in 6.5% NaCl","source_field":"lab_features[1]"}]},{"script_id":"streptococcus-gallolyticus","how_to_tell_apart":"Both are group D and hydrolyze bile esculin, but enterococci grow in 6.5% salt and resist cephalosporins; S. gallolyticus does not grow in 6.5% salt and is penicillin-susceptible."}],"pearls":["Enterococci are naturally resistant to all cephalosporins, so ceftriaxone alone never covers them.","Enterococcal endocarditis needs two drugs; ampicillin plus ceftriaxone works without the kidney toxicity of gentamicin.","VRE is most often Enterococcus faecium; E. faecalis is usually ampicillin-susceptible."],"difficulty_tiers":{"MS1-2":["morphology","lab_features"],"MS3":["diseases","treatment[0]"],"MS4":["treatment[1]","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"}],"morphology":"Gram-positive cocci in pairs and short chains","lab_features":["catalase-negative","grows in 6.5% NaCl","hydrolyzes bile esculin","usually gamma-hemolytic (no hemolysis)","Lancefield group D"],"transmission":["normal flora of the gut","spreads in hospitals on hands and equipment","enters through the urinary tract, the bowel or catheters"],"virulence_factors":["intrinsic resistance to cephalosporins","acquired vancomycin resistance (VRE), mostly in E. faecium","biofilm on catheters and devices"],"diseases":["urinary tract infections, often catheter-related","subacute endocarditis, often in older adults after GI or urinary procedures","biliary and intra-abdominal infections","bacteremia from intravenous lines"],"diagnosis":["blood and urine cultures","growth in 6.5% NaCl and bile esculin hydrolysis in the lab","susceptibility testing for ampicillin and vancomycin"],"treatment":["ampicillin for susceptible strains","endocarditis: ampicillin plus ceftriaxone, or ampicillin plus gentamicin","VRE: linezolid or daptomycin","vancomycin for ampicillin-resistant, vancomycin-susceptible strains"],"prevention":["hand hygiene and contact precautions for VRE","removing catheters early"]}'::jsonb),
  ('eosinophilic-granulomatosis-with-polyangiitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Eosinophilic granulomatosis with polyangiitis","aliases":["EGPA","Churg-Strauss syndrome"],"systems":["cardio","pulm"],"rotation":["IM"],"confused_with":[{"script_id":"granulomatosis-with-polyangiitis","how_to_tell_apart":"EGPA comes with asthma and marked eosinophilia and is p-ANCA positive in some; granulomatosis with polyangiitis has destructive sinus and nose disease without asthma or eosinophilia and is usually c-ANCA."}],"pearls":["Heart involvement is the most common cause of death in EGPA.","Asthma plus eosinophilia plus vasculitis: think EGPA.","Leukotriene receptor antagonists such as montelukast may unmask EGPA as steroids are tapered."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.labs","management.first_line"],"MS4":["pearls[2]","management.next_line"]},"anki_refs":[],"sources":[{"title":"2021 American College of Rheumatology/Vasculitis Foundation Guideline for the Management of Antineutrophil Cytoplasmic Antibody-Associated Vasculitis"},{"title":"Robbins and Cotran Pathologic Basis of Disease"}],"epidemiology":{"who":"Adults with late-onset asthma, often aged 30 to 50","risk_factors":["asthma","allergic rhinitis","nasal polyps"]},"pathophysiology":"A necrotizing small-vessel vasculitis with eosinophil-rich granulomas in people with asthma and eosinophilia. About 40% have MPO-ANCA (p-ANCA).","timeline":{"onset":"Phases over years: allergic (asthma, rhinitis), then eosinophilic (eosinophilia, lung infiltrates), then vasculitic","course":"Relapsing; asthma often persists"},"key_findings":{"history":["adult-onset asthma","chronic sinusitis and nasal polyps","numbness or weakness from mononeuritis multiplex","chest pain or heart failure from cardiac involvement"],"exam":["palpable purpura","foot or wrist drop","nasal polyps"],"labs":["eosinophilia, often over 10% of white cells","raised IgE","MPO-ANCA (p-ANCA) in about 40%"],"imaging":["chest imaging with migratory pulmonary infiltrates","echocardiogram or cardiac MRI for heart involvement"]},"diagnosis":{"confirmatory_tests":["blood eosinophil count","biopsy showing eosinophilic granulomatous vasculitis"],"criteria":[]},"management":{"first_line":["glucocorticoids","mepolizumab or benralizumab (anti-IL-5 pathway) for non-severe or relapsing disease"],"next_line":["cyclophosphamide or rituximab for severe, organ-threatening disease"]},"complications":["eosinophilic myocarditis and heart failure, the main cause of death","mononeuritis multiplex","glomerulonephritis"]}'::jsonb),
  ('essential-hypertension', 1, 'in_review', null, null, '{"kind":"disease","name":"Essential hypertension","aliases":["primary hypertension","high blood pressure"],"systems":["cardio"],"rotation":["IM","FM"],"confused_with":[{"script_id":"hypertensive-emergency","how_to_tell_apart":"Essential hypertension is chronic, silent and treated with oral drugs; a hypertensive emergency is severe hypertension with acute organ damage, needing IV drugs in the ICU."},{"script_id":"coarctation-of-the-aorta","how_to_tell_apart":"In essential hypertension arm and leg pressures match and the pulses are normal; coarctation causes high arm pressure, low leg pressure and weak, delayed femoral pulses."}],"pearls":["Never combine an ACE inhibitor with an ARB.","Resistant hypertension is blood pressure above goal despite three drugs, one of them a diuretic.","Hypertension in a young person, or with a low potassium, should prompt a search for a secondary cause such as primary hyperaldosteronism."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.who"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2025 AHA/ACC Guideline for the Prevention, Detection, Evaluation, and Management of High Blood Pressure in Adults"},{"title":"2024 ESC Guidelines for the management of elevated blood pressure and hypertension"}],"epidemiology":{"who":"Adults, more often with age; about 90% of hypertension has no single identifiable cause","risk_factors":["older age","family history","obesity","high sodium intake","physical inactivity","excess alcohol","Black ancestry"]},"pathophysiology":"Blood pressure rises from a mix of genetic and environmental factors: more sympathetic tone, renin-angiotensin-aldosterone activity, sodium retention and stiffer arteries. Over years it damages the heart, kidneys, brain and eyes.","timeline":{"onset":"Silent; usually found on screening","course":"Lifelong; untreated, it raises the risk of stroke, heart attack, heart failure and kidney disease"},"key_findings":{"history":["usually no symptoms","headache only when blood pressure is very high"],"exam":["blood pressure of 130/80 mmHg or higher on repeated readings","hypertensive retinopathy: arteriovenous nicking and cotton wool spots","left ventricular heave in long-standing disease"],"labs":["basic metabolic panel with creatinine and potassium","urinalysis and urine albumin","fasting glucose or HbA1c and a lipid panel"],"imaging":["ECG to look for left ventricular hypertrophy"]},"diagnosis":{"confirmatory_tests":["repeated office readings confirmed with ambulatory or home blood pressure monitoring"],"criteria":["AHA/ACC 2025: stage 1 hypertension is 130 to 139 systolic or 80 to 89 diastolic","AHA/ACC 2025: stage 2 hypertension is 140 systolic or 90 diastolic and above"]},"management":{"first_line":["lifestyle: weight loss, DASH diet, less salt, exercise and less alcohol","first-line drug classes: thiazide diuretic, ACE inhibitor, ARB or dihydropyridine calcium channel blocker","ACE inhibitor or ARB when there is diabetes with albuminuria or chronic kidney disease","a target under 130/80 for most adults"],"next_line":["stage 2: start two first-line classes, ideally as a single-pill combination","add spironolactone for resistant hypertension","look for a secondary cause when hypertension is resistant or starts young"]},"complications":["stroke","coronary artery disease","heart failure","chronic kidney disease","aortic dissection","hypertensive retinopathy"]}'::jsonb),
  ('ezetimibe', 1, 'in_review', null, null, '{"kind":"drug","name":"Ezetimibe","aliases":["Zetia"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"statins","how_to_tell_apart":"Ezetimibe blocks cholesterol absorption in the gut and lowers LDL by about 20%; statins block cholesterol synthesis in the liver and lower LDL by 30 to 50% or more."},{"script_id":"pcsk9-inhibitors","how_to_tell_apart":"Ezetimibe is a pill that lowers LDL by about 20%; PCSK9 inhibitors are injected and lower LDL by about 50 to 60%."}],"pearls":["The IMPROVE-IT trial showed ezetimibe added to a statin after acute coronary syndrome lowered cardiovascular events.","Ezetimibe lowers LDL by about 20%; a statin lowers it by 30 to 50% or more.","It is the usual next step after the highest tolerated statin."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications"],"MS4":["pearls[0]","interactions[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"title":"2022 ACC Expert Consensus Decision Pathway on the Role of Nonstatin Therapies for LDL-Cholesterol Lowering in the Management of Atherosclerotic Cardiovascular Disease Risk"}],"class":"Cholesterol absorption inhibitor","class_members":["ezetimibe"],"mechanism":"Blocks the NPC1L1 transporter on the brush border of the small intestine, reducing absorption of dietary and biliary cholesterol. LDL falls by about 20%.","pharmacokinetics":["glucuronidated in the gut and liver, with enterohepatic recycling","taken once daily"],"indications":["primary hyperlipidemia (high LDL)","added to a statin when LDL stays above goal","in place of a statin when statins are not tolerated","sitosterolemia"],"adverse_effects":["diarrhea","raised liver enzymes when combined with a statin","muscle aches, uncommon"],"contraindications":["active liver disease when combined with a statin"],"interactions":["bile acid sequestrants reduce absorption, so give ezetimibe 2 hours before or 4 hours after","cyclosporine raises levels"],"monitoring":["lipid panel"],"overdose":{"features":[],"treatment":[]}}'::jsonb),
  ('familial-hypercholesterolemia', 1, 'in_review', null, null, '{"kind":"disease","name":"Familial hypercholesterolemia","aliases":["FH"],"systems":["cardio"],"rotation":["IM","peds"],"confused_with":[],"pearls":["Tendon xanthomas are nearly diagnostic of FH.","Cascade screening: test the first-degree relatives of everyone with FH.","Corneal arcus before age 45 suggests FH."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.risk_factors"],"MS3":["key_findings.exam","management.first_line"],"MS4":["management.next_line","diagnosis.criteria"]},"anki_refs":[],"sources":[{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"title":"2023 Update on European Atherosclerosis Society Consensus Statement on Homozygous Familial Hypercholesterolaemia: new treatments and clinical guidance"}],"epidemiology":{"who":"About 1 in 250 people have heterozygous FH; homozygous FH is very rare","risk_factors":["family history of very high LDL or early heart disease","an LDL receptor variant, the most common cause","APOB or gain-of-function PCSK9 variants"]},"pathophysiology":"Autosomal dominant defects in LDL clearance (LDLR, APOB or gain-of-function PCSK9) raise LDL from birth and cause early atherosclerosis. Homozygotes have extreme LDL levels and can have heart attacks in childhood.","timeline":{"onset":"High LDL from birth","course":"Untreated heterozygous men often have coronary disease by their 50s"},"key_findings":{"history":["premature coronary disease in the patient or relatives","family history of high cholesterol"],"exam":["tendon xanthomas, especially of the Achilles tendons and the extensor tendons of the hands","xanthelasma","corneal arcus before age 45"],"labs":["LDL above 190 mg/dL in adults, or above 160 in children","normal triglycerides"],"imaging":[]},"diagnosis":{"confirmatory_tests":["lipid panel","genetic testing"],"criteria":["the Dutch Lipid Clinic Network or Simon Broome criteria combine LDL, family history, signs and genetics"]},"management":{"first_line":["high-intensity statin","add ezetimibe, then a PCSK9 inhibitor, to reach LDL goals","cascade screening of first-degree relatives","statins started in childhood, around age 8 to 10"],"next_line":["LDL apheresis, evinacumab or lomitapide for homozygous FH","lifestyle measures alongside drugs"]},"complications":["premature coronary artery disease","aortic stenosis in homozygous FH"]}'::jsonb),
  ('fibrates', 1, 'in_review', null, null, '{"kind":"drug","name":"Fibrates","aliases":["fibric acid derivatives"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"statins","how_to_tell_apart":"Fibrates mainly lower triglycerides by activating PPAR-alpha; statins mainly lower LDL by inhibiting HMG-CoA reductase."},{"script_id":"niacin","how_to_tell_apart":"Fibrates mainly lower triglycerides by activating PPAR-alpha; niacin raises HDL the most and works by inhibiting lipolysis in fat."}],"pearls":["Fibrates increase cholesterol in bile, which causes cholesterol gallstones.","When a fibrate must be combined with a statin, choose fenofibrate, not gemfibrozil.","With triglycerides above 500 mg/dL, and especially above 1000, treating them to prevent pancreatitis is reasonable once secondary causes are addressed and a very-low-fat diet started."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","adverse_effects"],"MS4":["interactions","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}],"class":"Fibric acid derivatives (PPAR-alpha agonists)","class_members":["fenofibrate","fenofibric acid","gemfibrozil","bezafibrate"],"mechanism":"Activate PPAR-alpha, which increases lipoprotein lipase activity and fatty acid oxidation. Triglycerides fall sharply, by up to 50%; HDL rises a little and LDL changes little.","pharmacokinetics":["fenofibrate is cleared by the kidneys, so the dose is reduced in kidney disease","gemfibrozil inhibits statin glucuronidation and CYP2C8"],"indications":["severe hypertriglyceridemia, to prevent pancreatitis","mixed dyslipidemia with high triglycerides"],"adverse_effects":["myopathy, especially gemfibrozil with a statin","gallstones","raised liver enzymes","rise in creatinine (fenofibrate)"],"contraindications":["gallbladder disease","severe kidney disease","severe liver disease","gemfibrozil with a statin"],"interactions":["gemfibrozil raises statin levels and the risk of rhabdomyolysis","fibrates enhance the effect of warfarin"],"monitoring":["lipid panel","liver enzymes","creatinine"],"overdose":{"features":[],"treatment":[]}}'::jsonb),
  ('giant-cell-arteritis', 1, 'in_review', null, null, '{"kind":"disease","name":"Giant cell arteritis","aliases":["temporal arteritis","GCA"],"systems":["cardio","msk"],"rotation":["IM"],"confused_with":[{"script_id":"takayasu-arteritis","how_to_tell_apart":"Giant cell arteritis affects people over 50 and favors the temporal and other cranial arteries; Takayasu arteritis affects women under 40 and narrows the aorta and its branches, causing weak arm pulses."}],"pearls":["Start steroids before the biopsy; the biopsy stays positive for at least 1 to 2 weeks.","A biopsy can be falsely negative because the inflammation leaves gaps (skip lesions).","About half of patients with giant cell arteritis also have polymyalgia rheumatica."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.history"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2021 American College of Rheumatology/Vasculitis Foundation Guideline for the Management of Giant Cell Arteritis and Takayasu Arteritis"},{"title":"Robbins and Cotran Pathologic Basis of Disease"}],"epidemiology":{"who":"Adults over 50, more often women","risk_factors":["age over 50","female sex","polymyalgia rheumatica","northern European ancestry"]},"pathophysiology":"Granulomatous inflammation of large and medium arteries, especially branches of the external carotid artery. The wall thickens, with giant cells, and the lumen narrows, causing ischemia.","timeline":{"onset":"Weeks of headache and systemic symptoms","course":"Treatment lasts 1 to 2 years; vision loss can be sudden and permanent"},"key_findings":{"history":["new headache, often temporal","jaw claudication","scalp tenderness","visual loss or diplopia","shoulder and hip girdle stiffness from polymyalgia rheumatica","fever, weight loss and fatigue"],"exam":["tender, thickened or pulseless temporal artery","reduced vision"],"labs":["raised ESR","raised CRP","normocytic anemia","raised platelet count"],"imaging":["temporal artery ultrasound showing a halo sign","PET or CT angiography for large-vessel involvement"]},"diagnosis":{"confirmatory_tests":["temporal artery biopsy","temporal artery ultrasound"],"criteria":[]},"management":{"first_line":["high-dose glucocorticoids started right away, without waiting for the biopsy","IV methylprednisolone if vision is affected"],"next_line":["tocilizumab to spare glucocorticoids","methotrexate as an alternative steroid-sparing drug"]},"complications":["permanent vision loss from anterior ischemic optic neuropathy","stroke","thoracic aortic aneurysm","glucocorticoid side effects"]}'::jsonb),
  ('granulomatosis-with-polyangiitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Granulomatosis with polyangiitis","aliases":["GPA","Wegener granulomatosis"],"systems":["cardio","pulm","renal"],"rotation":["IM"],"confused_with":[{"script_id":"microscopic-polyangiitis","how_to_tell_apart":"Granulomatosis with polyangiitis involves the sinuses and nose, has granulomas and is usually PR3-ANCA; microscopic polyangiitis has no granulomas or upper airway disease and is usually MPO-ANCA."},{"script_id":"eosinophilic-granulomatosis-with-polyangiitis","how_to_tell_apart":"Granulomatosis with polyangiitis has destructive sinus and nose disease without asthma or eosinophilia and is usually c-ANCA; EGPA comes with asthma and marked eosinophilia and is p-ANCA positive in some."}],"pearls":["Upper airway disease separates granulomatosis with polyangiitis from microscopic polyangiitis, which has no granulomas and is usually MPO-ANCA (p-ANCA).","c-ANCA is aimed at proteinase 3.","The classic triad is upper airway, lung and kidney involvement."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[1]"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2021 American College of Rheumatology/Vasculitis Foundation Guideline for the Management of Antineutrophil Cytoplasmic Antibody-Associated Vasculitis"},{"title":"Robbins and Cotran Pathologic Basis of Disease"}],"epidemiology":{"who":"Adults, usually aged 40 to 65","risk_factors":["age 40 to 65","white ancestry","nasal carriage of Staphylococcus aureus, linked to relapse"]},"pathophysiology":"A small-vessel vasculitis with necrotizing granulomas, linked to ANCA against proteinase 3 (PR3-ANCA, c-ANCA). It classically affects the upper airway, the lungs and the kidneys.","timeline":{"onset":"Weeks to months of sinus and systemic symptoms","course":"Fatal untreated; treatment brings remission, but relapses are common"},"key_findings":{"history":["chronic sinusitis or nosebleeds","hemoptysis","hematuria","fever, weight loss and joint pain"],"exam":["saddle nose deformity","nasal crusting or ulcers","palpable purpura"],"labs":["positive PR3-ANCA (c-ANCA)","hematuria with red cell casts","rising creatinine","raised ESR or CRP"],"imaging":["chest CT with lung nodules, often cavitating"]},"diagnosis":{"confirmatory_tests":["PR3-ANCA (c-ANCA)","biopsy of an affected organ showing necrotizing granulomatous vasculitis"],"criteria":[]},"management":{"first_line":["induction with high-dose glucocorticoids plus rituximab or cyclophosphamide"],"next_line":["maintenance with rituximab or azathioprine","plasma exchange only in selected cases, such as severe kidney disease","trimethoprim-sulfamethoxazole to prevent Pneumocystis pneumonia during treatment"]},"complications":["rapidly progressive glomerulonephritis","pulmonary hemorrhage","saddle nose deformity","subglottic stenosis"]}'::jsonb),
  ('hacek-organisms', 1, 'in_review', null, null, '{"kind":"bug","name":"HACEK organisms","aliases":["HACEK group"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"viridans-streptococci","how_to_tell_apart":"Both cause subacute endocarditis from the mouth, but HACEK organisms are fastidious gram-negative rods that grow slowly, while viridans streptococci are gram-positive cocci in chains that grow readily."},{"script_id":"coxiella-burnetii","how_to_tell_apart":"Both cause culture-negative endocarditis, but HACEK organisms come from the mouth and eventually grow in blood cultures, while Coxiella comes from farm animals and is diagnosed by serology."}],"pearls":["HACEK stands for Haemophilus, Aggregatibacter, Cardiobacterium, Eikenella and Kingella.","Kingella kingae is a common cause of septic arthritis in young children.","Eikenella corrodens infects human bite wounds and clenched-fist injuries."],"difficulty_tiers":{"MS1-2":["morphology","pearls[0]"],"MS3":["diseases","treatment"],"MS4":["pearls[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"}],"morphology":"Fastidious gram-negative bacilli and coccobacilli of the mouth","lab_features":["slow-growing in standard blood cultures","some need extra carbon dioxide to grow","modern automated blood cultures detect most within 5 days"],"transmission":["normal flora of the mouth and upper airway","enter the blood with dental disease or procedures"],"virulence_factors":["adherence to damaged valves","some make beta-lactamase"],"diseases":["subacute endocarditis, often culture-negative at first, with large vegetations and emboli","periodontal infections","bite-wound infections (Eikenella after human bites)"],"diagnosis":["blood cultures, with the lab told to look for them","echocardiogram","PCR or MALDI-TOF identification"],"treatment":["ceftriaxone","ampicillin-sulbactam or a fluoroquinolone as alternatives"],"prevention":["good dental hygiene"]}'::jsonb),
  ('heart-failure-exacerbation', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute decompensated heart failure","aliases":["heart failure exacerbation","ADHF","CHF exacerbation"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough and a focal consolidation; heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP.","compare":[{"label":"Lungs","text":"Bibasilar crackles","source_field":"key_findings.exam[1]"},{"label":"Key lab","text":"Raised BNP","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"IV loop diuretic","source_field":"management.first_line[0]"}]},{"script_id":"copd-exacerbation","how_to_tell_apart":"A COPD exacerbation gives wheeze and more sputum in a smoker, without a raised JVP, leg edema or a high BNP.","compare":[{"label":"Exam","text":"Raised JVP","source_field":"key_findings.exam[0]"},{"label":"Key test","text":"Raised BNP","source_field":"key_findings.labs[0]"},{"label":"Treat","text":"IV loop diuretic","source_field":"management.first_line[0]"}]}],"pearls":["The first IV loop diuretic dose should equal or exceed the patient''s total daily oral dose."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[{"kind":"note","id":"1557777121517"},{"kind":"note","id":"1570070676637"},{"kind":"note","id":"1471547618307","rung":"recall"},{"kind":"note","id":"1497722931967","rung":"recall"},{"kind":"note","id":"1539463025075","rung":"recall"},{"kind":"note","id":"1497308773697","rung":"workup"},{"kind":"note","id":"1550690801047","rung":"workup"},{"kind":"note","id":"1579476253074","rung":"workup"},{"kind":"note","id":"1477447145086","rung":"management"},{"kind":"note","id":"1497732761695","rung":"management"},{"kind":"note","id":"1555286309380","rung":"management"}],"sources":[{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"epidemiology":{"who":"Adults with known chronic heart failure, with reduced or preserved ejection fraction","risk_factors":["high salt intake","medication nonadherence","myocardial ischemia","atrial fibrillation","uncontrolled hypertension","infection","NSAIDs"]},"pathophysiology":"Worsening cardiac function or a precipitant raises left-sided filling pressures, causing pulmonary congestion, while sodium and water retention cause systemic venous congestion.","timeline":{"onset":"Usually over days, sometimes hours","course":"Most improve with diuresis over several days; each admission marks a worse long-term prognosis"},"key_findings":{"history":["worsening dyspnea","orthopnea","paroxysmal nocturnal dyspnea","weight gain","leg swelling"],"exam":["raised JVP","bibasilar crackles","S3 gallop","pitting edema"],"labs":["raised BNP or NT-proBNP","troponin may be mildly raised"],"imaging":["chest X-ray: pulmonary vascular congestion, interstitial edema, Kerley B lines, pleural effusions","echocardiogram to assess ejection fraction"]},"diagnosis":{"confirmatory_tests":["BNP or NT-proBNP","echocardiogram","chest X-ray"],"criteria":["clinical diagnosis: symptoms and signs of congestion, supported by a raised natriuretic peptide"]},"management":{"first_line":["IV loop diuretics such as furosemide","supplemental oxygen if hypoxemic","treat the precipitant"],"next_line":["add a thiazide-type diuretic such as metolazone if diuresis is inadequate","noninvasive ventilation for respiratory distress","vasodilators such as nitroglycerin if hypertensive","inotropes for low output with hypoperfusion"]},"complications":["cardiogenic shock","acute kidney injury","arrhythmias","hypokalemia from diuresis"]}'::jsonb),
  ('heart-failure', 1, 'in_review', null, null, '{"kind":"disease","name":"Chronic heart failure","aliases":["heart failure","congestive heart failure"],"systems":["cardio"],"rotation":["IM"],"confused_with":[],"pearls":["The beta blockers proven to lower mortality in HFrEF are carvedilol, metoprolol succinate and bisoprolol.","An S3 gallop signals volume overload; an S4 signals a stiff ventricle.","SGLT2 inhibitors cut heart failure hospitalizations whether or not the patient has diabetes."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"},{"title":"2023 Focused Update of the 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure"}],"epidemiology":{"who":"Older adults, most often after coronary disease or long-standing hypertension","risk_factors":["coronary artery disease","hypertension","diabetes","obesity","valvular heart disease","heavy alcohol use","cardiotoxic chemotherapy"]},"pathophysiology":"The heart cannot pump enough blood at normal filling pressures. In heart failure with reduced ejection fraction (HFrEF) the ventricle dilates and contracts poorly; in heart failure with preserved ejection fraction (HFpEF) it is stiff and fills poorly. Activation of the renin-angiotensin-aldosterone system and the sympathetic nervous system drives sodium retention and remodeling.","timeline":{"onset":"Gradual, over months to years","course":"Progressive, with acute decompensations; guideline-directed therapy lowers mortality in HFrEF"},"key_findings":{"history":["exertional dyspnea","orthopnea","paroxysmal nocturnal dyspnea","ankle swelling","fatigue"],"exam":["raised jugular venous pressure","S3 gallop","bibasilar crackles","pitting edema","displaced apex beat"],"labs":["raised BNP or NT-proBNP","hyponatremia in advanced disease"],"imaging":["echocardiogram showing the ejection fraction and wall motion","chest X-ray with cardiomegaly, upper lobe venous diversion and Kerley B lines"]},"diagnosis":{"confirmatory_tests":["echocardiogram","BNP or NT-proBNP"],"criteria":["HFrEF: ejection fraction 40% or less","HFmrEF: ejection fraction 41 to 49%","HFpEF: ejection fraction 50% or more"]},"management":{"first_line":["HFrEF: four drug classes, an ARNI (sacubitril-valsartan) or ACE inhibitor or ARB, an evidence-based beta blocker, a mineralocorticoid receptor antagonist and an SGLT2 inhibitor","loop diuretics for congestion","exercise, vaccination and avoiding excess salt"],"next_line":["ICD for an ejection fraction of 35% or less despite three months of therapy","cardiac resynchronization therapy for an ejection fraction of 35% or less with left bundle branch block and a wide QRS","hydralazine with isosorbide dinitrate, especially for Black patients","LVAD or heart transplant in advanced disease"]},"complications":["acute decompensation","ventricular arrhythmias and sudden death","atrial fibrillation","cardiorenal syndrome","thromboembolism"]}'::jsonb),
  ('hydralazine', 1, 'in_review', null, null, '{"kind":"drug","name":"Hydralazine","aliases":["Apresoline"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"nitrates","how_to_tell_apart":"Hydralazine dilates arterioles and lowers afterload; nitrates dilate veins and lower preload. Together, as isosorbide dinitrate with hydralazine, they treat heart failure."}],"pearls":["Drug-induced lupus from hydralazine has anti-histone antibodies and usually spares the kidneys and brain.","Hydralazine is a standard choice for severe hypertension in pregnancy, along with labetalol and nifedipine.","The A-HeFT trial showed hydralazine with isosorbide dinitrate lowered mortality in Black patients with heart failure."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications"],"MS4":["pharmacokinetics","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"},{"title":"ACOG Practice Bulletin No. 222: Gestational Hypertension and Preeclampsia"}],"class":"Direct arteriolar vasodilator","class_members":["hydralazine"],"mechanism":"Relaxes arteriolar smooth muscle, probably by raising cGMP, lowering afterload. It dilates arterioles much more than veins.","pharmacokinetics":["metabolized by acetylation; slow acetylators have higher levels and more lupus-like reactions"],"indications":["heart failure with reduced ejection fraction, with isosorbide dinitrate, especially in Black patients","severe hypertension in pregnancy","resistant hypertension"],"adverse_effects":["reflex tachycardia","headache","flushing","fluid retention","drug-induced lupus"],"contraindications":["angina without a beta blocker, because reflex tachycardia can provoke ischemia"],"interactions":["often given with a beta blocker and a diuretic to offset reflex tachycardia and fluid retention"],"monitoring":["blood pressure","heart rate","ANA if lupus symptoms appear"],"overdose":{"features":["hypotension","tachycardia"],"treatment":["IV fluids","supportive care"]}}'::jsonb),
  ('hyperkalemia', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyperkalemia","aliases":["high potassium"],"systems":["renal"],"rotation":["IM","EM"],"confused_with":[],"pearls":["Calcium protects the heart within minutes but does not lower potassium; you still need to shift and remove it."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1495911001468"},{"kind":"note","id":"1496783778319"},{"kind":"note","id":"1496795383464"},{"kind":"note","id":"1535225879303"},{"kind":"note","id":"1555494970633"}],"sources":[{"title":"Clinical Practice Guidelines: Treatment of Acute Hyperkalaemia in Adults (UK Kidney Association, 2023)"}],"epidemiology":{"who":"People with kidney disease or diabetes, or on drugs that raise potassium","risk_factors":["acute kidney injury","chronic kidney disease","ACE inhibitors or ARBs","potassium-sparing diuretics","rhabdomyolysis","adrenal insufficiency"]},"pathophysiology":"Reduced potassium excretion or a shift out of cells raises serum potassium, which depolarizes heart and muscle cells and slows cardiac conduction.","timeline":{"onset":"Acute or chronic","course":"Can cause fatal arrhythmias once ECG changes appear"},"key_findings":{"history":["often no symptoms","muscle weakness","palpitations"],"exam":["weakness","bradycardia"],"labs":["serum potassium above 5.5 mEq/L","pseudohyperkalemia from a hemolyzed sample","ECG: peaked T waves, then PR prolongation and a wide QRS, progressing to a sine wave"],"imaging":[]},"diagnosis":{"confirmatory_tests":["repeat serum potassium","12-lead ECG"],"criteria":["serum potassium above 5.5 mEq/L; severe at 6.5 mEq/L or above, or with ECG changes"]},"management":{"first_line":["IV calcium gluconate to stabilize the heart","insulin with glucose to shift potassium into cells","beta-2 agonist such as nebulized albuterol"],"next_line":["remove potassium: loop diuretics, potassium binders or dialysis","stop potassium-raising drugs"]},"complications":["ventricular fibrillation","asystole","bradyarrhythmias"]}'::jsonb),
  ('hyperosmolar-hyperglycemic-state', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyperosmolar hyperglycemic state","aliases":["HHS"],"systems":["endo"],"rotation":["IM","EM"],"confused_with":[{"script_id":"diabetic-ketoacidosis","how_to_tell_apart":"DKA has ketones and an anion gap acidosis and develops over hours; HHS has much higher glucose and osmolality, little or no ketosis, and develops over days.","compare":[{"label":"Glucose","text":"Usually over 600 mg/dL","source_field":"key_findings.labs[0]"},{"label":"Acidosis","text":"pH 7.3 or higher","source_field":"key_findings.labs[2]"},{"label":"Ketones","text":"Little or none","source_field":"key_findings.labs[3]"}]}],"pearls":["In HHS, fluids come first: insulin before adequate fluid replacement shifts water into cells and can worsen hypotension."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1502845294644"},{"kind":"note","id":"1502846424371"},{"kind":"note","id":"1550626495694"},{"kind":"note","id":"1555720980431"},{"kind":"note","id":"1585334906873"}],"sources":[{"title":"Hyperglycemic Crises in Adults With Diabetes: A Consensus Report (Diabetes Care, 2024)"}],"epidemiology":{"who":"Older adults with type 2 diabetes, often with limited access to water","risk_factors":["infection","insufficient insulin or missed medications","myocardial infarction","stroke","glucocorticoids","thiazide diuretics"]},"pathophysiology":"Relative insulin deficiency, with enough insulin to prevent ketogenesis, causes severe hyperglycemia, an osmotic diuresis, profound dehydration and hyperosmolality.","timeline":{"onset":"Develops over days to weeks","course":"Slower to correct than DKA, with a higher mortality"},"key_findings":{"history":["polyuria and polydipsia over days to weeks","weakness","confusion or drowsiness"],"exam":["severe dehydration","altered mental status, from lethargy to coma","focal neurologic signs or seizures in some"],"labs":["glucose usually above 600 mg/dL","effective serum osmolality above 300 mOsm/kg","pH 7.3 or higher and bicarbonate 15 mEq/L or higher","little or no ketonemia"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum glucose","calculated effective serum osmolality","serum beta-hydroxybutyrate to exclude significant ketosis"],"criteria":["glucose of 600 mg/dL or more","effective serum osmolality above 300 mOsm/kg (or total above 320)","pH 7.3 or higher, bicarbonate 15 mEq/L or higher, and no significant ketonemia"]},"management":{"first_line":["aggressive IV isotonic fluids","IV insulin infusion once fluids are running and potassium is at least 3.5 mEq/L","potassium replacement"],"next_line":["lower glucose, sodium and osmolality gradually to avoid cerebral edema","treat the precipitant","VTE prophylaxis"]},"complications":["cerebral edema from overly rapid correction","venous thromboembolism","rhabdomyolysis","acute kidney injury"]}'::jsonb),
  ('hypertensive-emergency', 1, 'in_review', null, null, '{"kind":"disease","name":"Hypertensive emergency","aliases":["hypertensive crisis","malignant hypertension"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"essential-hypertension","how_to_tell_apart":"A hypertensive emergency is severe hypertension with acute organ damage, needing IV drugs in the ICU; essential hypertension is chronic, silent and treated with oral drugs."}],"pearls":["Lowering blood pressure too fast can cause stroke or kidney injury, because autoregulation has shifted upward.","Aortic dissection is the exception: lower the pressure fast, with a beta blocker before any vasodilator.","In a cocaine-induced hypertensive crisis, give benzodiazepines first and avoid a beta blocker alone."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2025 AHA/ACC Guideline for the Prevention, Detection, Evaluation, and Management of High Blood Pressure in Adults"},{"title":"Tintinalli''s Emergency Medicine: A Comprehensive Study Guide"}],"epidemiology":{"who":"Adults with poorly controlled or untreated hypertension","risk_factors":["nonadherence to antihypertensives","cocaine or amphetamine use","preeclampsia","renal artery stenosis","pheochromocytoma","abrupt clonidine withdrawal"]},"pathophysiology":"Severely raised blood pressure, usually above 180/120, causes acute damage to the brain, heart, aorta, kidneys and eyes. Without acute organ damage it is called hypertensive urgency.","timeline":{"onset":"Hours to days","course":"Life-threatening without prompt, controlled lowering"},"key_findings":{"history":["headache","confusion or seizures (hypertensive encephalopathy)","chest pain","dyspnea","visual changes"],"exam":["blood pressure usually above 180/120","papilledema, retinal hemorrhages and exudates","focal neurologic signs"],"labs":["creatinine and urinalysis for acute kidney injury","troponin","blood smear for schistocytes (thrombotic microangiopathy)"],"imaging":["head CT for stroke or bleeding","chest X-ray for pulmonary edema","CT angiography if aortic dissection is suspected"]},"diagnosis":{"confirmatory_tests":["severely raised blood pressure with evidence of acute organ damage"],"criteria":["emergency: severe hypertension with acute organ damage; urgency: severe hypertension without it"]},"management":{"first_line":["ICU admission and an IV titratable drug such as nicardipine, clevidipine, labetalol, esmolol or nitroprusside","lower blood pressure by no more than 25% in the first hour, then toward 160/100 over the next 2 to 6 hours"],"next_line":["aortic dissection: lower systolic pressure below 120 within 20 minutes, with a beta blocker first","hypertensive urgency: oral drugs and close outpatient follow-up, not rapid IV lowering"]},"complications":["stroke","hypertensive encephalopathy","acute heart failure with pulmonary edema","myocardial infarction","aortic dissection","acute kidney injury"]}'::jsonb),
  ('hyperthyroidism', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyperthyroidism","aliases":["thyrotoxicosis","Graves disease"],"systems":["endo"],"rotation":["IM","FM"],"confused_with":[],"pearls":["Methimazole and propylthiouracil can cause agranulocytosis: stop the drug and check a white count if fever or a sore throat develops."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1502847845332"},{"kind":"note","id":"1547916081745"},{"kind":"note","id":"1548274605064"},{"kind":"note","id":"1557341643876"},{"kind":"note","id":"1580516060026"},{"kind":"note","id":"1552147637583","rung":"recall"},{"kind":"note","id":"1552158235283","rung":"recall"},{"kind":"note","id":"1585078817088","rung":"recall"},{"kind":"note","id":"1493675300258","rung":"management"},{"kind":"note","id":"1502563194507","rung":"management"},{"kind":"note","id":"1502929712391","rung":"management"}],"sources":[{"title":"2016 American Thyroid Association Guidelines for Diagnosis and Management of Hyperthyroidism and Other Causes of Thyrotoxicosis"}],"epidemiology":{"who":"Most often young to middle-aged women with Graves disease","risk_factors":["Graves disease","toxic multinodular goiter","toxic adenoma","thyroiditis","excess thyroid hormone intake","amiodarone"]},"pathophysiology":"Excess thyroid hormone, most often from TSH-receptor antibodies stimulating the gland in Graves disease, speeds metabolism and sympathetic activity.","timeline":{"onset":"Weeks to months","course":"Graves disease may remit after 12 to 18 months of antithyroid drugs"},"key_findings":{"history":["weight loss despite a good appetite","heat intolerance","palpitations","anxiety and tremor","frequent stools"],"exam":["tachycardia or atrial fibrillation","fine tremor","goiter","exophthalmos and pretibial myxedema in Graves disease"],"labs":["low TSH","high free T4 or T3","TSH-receptor antibodies in Graves disease"],"imaging":["radioactive iodine uptake scan: diffuse high uptake in Graves disease, low uptake in thyroiditis"]},"diagnosis":{"confirmatory_tests":["TSH","free T4","TSH-receptor antibodies or a radioactive iodine uptake scan to find the cause"],"criteria":["suppressed TSH with raised free T4 or T3"]},"management":{"first_line":["beta-blocker such as propranolol for symptoms","methimazole"],"next_line":["propylthiouracil in the first trimester of pregnancy and in thyroid storm","radioactive iodine ablation","thyroidectomy"]},"complications":["atrial fibrillation","thyroid storm","osteoporosis","agranulocytosis from antithyroid drugs"]}'::jsonb),
  ('hypertrophic-cardiomyopathy', 1, 'in_review', null, null, '{"kind":"disease","name":"Hypertrophic cardiomyopathy","aliases":["HCM","hypertrophic obstructive cardiomyopathy","HOCM"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"aortic-stenosis","how_to_tell_apart":"Hypertrophic cardiomyopathy causes a systolic murmur at the left lower sternal border that gets louder with Valsalva or standing; the murmur of aortic stenosis radiates to the carotids and gets softer. Hypertrophic cardiomyopathy is inherited and shows up in the young; aortic stenosis is a disease of older adults.","compare":[{"label":"Murmur","text":"Left lower sternal border","source_field":"key_findings.exam[0]"},{"label":"Valsalva","text":"Louder","source_field":"key_findings.exam[0]"},{"label":"Who","text":"Young, inherited","source_field":"epidemiology.who"}]},{"script_id":"dilated-cardiomyopathy","how_to_tell_apart":"Hypertrophic cardiomyopathy has a thick, stiff ventricle that pumps normally or too well; dilated cardiomyopathy has a big, thin-walled ventricle that pumps weakly, with a low ejection fraction."}],"pearls":["Anything that shrinks the ventricle (Valsalva, standing, dehydration) makes the obstruction and murmur worse; squatting and handgrip make them softer.","Hypertrophic cardiomyopathy is inherited in an autosomal dominant pattern.","Systolic anterior motion of the mitral valve also causes mitral regurgitation."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[1]"],"MS3":["key_findings.exam[0]","management.first_line"],"MS4":["management.next_line"]},"anki_refs":[],"sources":[{"title":"2024 AHA/ACC/AMSSM/HRS/PACES/SCMR Guideline for the Management of Hypertrophic Cardiomyopathy"},{"title":"2023 ESC Guidelines for the management of cardiomyopathies"}],"epidemiology":{"who":"Any age, often first found in adolescents and young adults; the most common inherited heart disease (about 1 in 500) and a leading cause of sudden death in young athletes","risk_factors":["family history of hypertrophic cardiomyopathy or sudden death","a sarcomere gene variant, most often in beta-myosin heavy chain or myosin-binding protein C"]},"pathophysiology":"A variant in a sarcomere protein causes asymmetric hypertrophy of the left ventricle, usually of the septum, with disorganized myocytes (myocyte disarray). The stiff ventricle fills poorly. In the obstructive form, the anterior mitral leaflet is pulled toward the septum in systole (systolic anterior motion), obstructing outflow and causing mitral regurgitation.","timeline":{"onset":"Often appears in adolescence or early adulthood","course":"Variable: many live normal lives, but some develop sudden death, heart failure or atrial fibrillation"},"key_findings":{"history":["exertional dyspnea","chest pain","syncope or presyncope on exertion","palpitations","sudden death may be the first sign"],"exam":["systolic ejection murmur at the left lower sternal border that gets louder with Valsalva or standing and softer with squatting or handgrip","S4","bifid carotid pulse"],"labs":["genetic testing for sarcomere variants"],"imaging":["echocardiogram showing a septum 15 mm or thicker, often with systolic anterior motion of the mitral valve","cardiac MRI showing hypertrophy and fibrosis","ECG with left ventricular hypertrophy and deep Q waves"]},"diagnosis":{"confirmatory_tests":["echocardiogram","cardiac MRI"],"criteria":["Left ventricular wall thickness of 15 mm or more (13 mm or more with a family history), not explained by another cause"]},"management":{"first_line":["beta blocker for symptoms","avoid dehydration and vasodilators","ICD for patients at high risk of sudden death","screen first-degree relatives with ECG and echocardiogram"],"next_line":["verapamil or diltiazem if beta blockers fail","mavacamten, a cardiac myosin inhibitor, for obstructive symptoms","septal reduction: surgical myectomy or alcohol septal ablation"]},"complications":["sudden cardiac death from ventricular arrhythmia","atrial fibrillation","heart failure","mitral regurgitation"]}'::jsonb),
  ('hyponatremia', 1, 'in_review', null, null, '{"kind":"disease","name":"Hyponatremia","aliases":["low sodium"],"systems":["renal","endo"],"rotation":["IM"],"confused_with":[],"pearls":["Correcting chronic hyponatremia too fast causes osmotic demyelination syndrome; limit the rise to 8 mEq/L in 24 hours."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1496783896138"},{"kind":"note","id":"1497567515289"},{"kind":"note","id":"1535224314327"},{"kind":"note","id":"1550658787885"},{"kind":"note","id":"1555494262417"}],"sources":[{"title":"Clinical practice guideline on diagnosis and treatment of hyponatraemia (ESE, ERA-EDTA and ESICM, 2014)"}],"epidemiology":{"who":"Older adults, hospitalized patients, and people on thiazides or SSRIs","risk_factors":["thiazide diuretics","SIADH","heart failure","cirrhosis","SSRIs","excess water intake"]},"pathophysiology":"Too much water relative to sodium, usually from ADH-driven water retention. After confirming low serum osmolality, it is classified by volume status.","timeline":{"onset":"Acute (under 48 hours) or chronic","course":"Chronic hyponatremia must be corrected slowly"},"key_findings":{"history":["nausea","headache","confusion","falls"],"exam":["assess volume status: dry, euvolemic or edematous","seizures or reduced consciousness when severe"],"labs":["serum sodium below 135 mEq/L","low serum osmolality in true (hypotonic) hyponatremia","urine osmolality above 100 mOsm/kg and urine sodium above 30 mEq/L in SIADH"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum osmolality","urine osmolality","urine sodium","volume status assessment"],"criteria":["serum sodium below 135 mEq/L; severe below 120 mEq/L"]},"management":{"first_line":["hypertonic 3% saline bolus for severe symptoms such as seizures","fluid restriction for SIADH","isotonic saline for hypovolemic hyponatremia","stop the offending drug"],"next_line":["limit correction to 8 mEq/L in 24 hours in chronic hyponatremia","urea or vaptans for refractory SIADH","treat heart failure or cirrhosis in hypervolemic hyponatremia"]},"complications":["seizures","cerebral edema","osmotic demyelination syndrome from overly rapid correction","falls and fractures"]}'::jsonb),
  ('iga-vasculitis', 1, 'in_review', null, null, '{"kind":"disease","name":"IgA vasculitis","aliases":["Henoch-Schönlein purpura","HSP"],"systems":["cardio","renal","derm"],"rotation":["peds"],"confused_with":[{"script_id":"kawasaki-disease","how_to_tell_apart":"IgA vasculitis gives palpable purpura on the legs, joint pain, belly pain and hematuria; Kawasaki disease gives prolonged fever, conjunctivitis, oral changes and coronary aneurysms."}],"pearls":["Palpable purpura with a normal platelet count separates it from thrombocytopenic purpura.","Intussusception in IgA vasculitis is usually ileoileal, unlike the ileocolic type in idiopathic intussusception.","Monitor the urine for months, because kidney disease can appear after the rash has faded."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["pearls[1]","management.next_line"]},"anki_refs":[],"sources":[{"title":"EULAR/PRINTO/PRES criteria for Henoch-Schönlein purpura, childhood polyarteritis nodosa, childhood Wegener granulomatosis and childhood Takayasu arteritis: Ankara 2008. Part II: Final classification criteria"},{"title":"Nelson Textbook of Pediatrics"}],"epidemiology":{"who":"Children aged 3 to 15, often after an upper respiratory infection; the most common vasculitis of childhood","risk_factors":["recent upper respiratory infection","childhood","autumn and winter"]},"pathophysiology":"IgA immune complexes deposit in small vessels of the skin, gut, joints and kidneys, causing a leukocytoclastic vasculitis.","timeline":{"onset":"Days to weeks after a respiratory infection","course":"Usually settles in about 4 weeks; kidney disease can persist, more often in adults"},"key_findings":{"history":["rash on the buttocks and legs","joint pain, often in the knees and ankles","colicky abdominal pain","recent upper respiratory infection"],"exam":["palpable purpura on the buttocks and lower legs with a normal platelet count","arthritis","swelling of the hands, feet or scrotum"],"labs":["normal platelet count and clotting","urinalysis with hematuria or proteinuria","raised serum IgA in some"],"imaging":["abdominal ultrasound for intussusception if pain is severe"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","skin or kidney biopsy showing IgA deposits"],"criteria":["palpable purpura, mainly on the legs, plus at least one of abdominal pain, arthritis or arthralgia, kidney involvement, or IgA deposits on biopsy"]},"management":{"first_line":["supportive care: rest, fluids, and acetaminophen or NSAIDs for joint pain (avoid NSAIDs with kidney involvement)","monitor the urine and blood pressure for 6 to 12 months"],"next_line":["glucocorticoids for severe abdominal pain","immunosuppression for significant nephritis"]},"complications":["intussusception, usually ileoileal","glomerulonephritis like IgA nephropathy","chronic kidney disease, rarely"]}'::jsonb),
  ('infective-endocarditis', 1, 'in_review', null, null, '{"kind":"disease","name":"Infective endocarditis","aliases":["endocarditis"],"systems":["cardio"],"rotation":["IM"],"confused_with":[],"pearls":["Endocarditis in people who inject drugs often affects the tricuspid valve and causes septic pulmonary emboli."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1497045640067"},{"kind":"note","id":"1550787795139"},{"kind":"note","id":"1551617026447"},{"kind":"note","id":"1579382616920"},{"kind":"note","id":"1579382907963"},{"kind":"note","id":"1504743646378","rung":"recall"},{"kind":"note","id":"1539379437968","rung":"recall"},{"kind":"note","id":"1553162828660","rung":"recall"},{"kind":"note","id":"1550694289942","rung":"management"},{"kind":"note","id":"1555458022589","rung":"management"},{"kind":"note","id":"1590016185294","rung":"management"}],"sources":[{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis"}],"epidemiology":{"who":"People who inject drugs, and those with prosthetic valves, prior endocarditis or structural heart disease","risk_factors":["injection drug use","prosthetic heart valve","prior endocarditis","structural or congenital heart disease","indwelling intravascular devices","hemodialysis"]},"pathophysiology":"Bacteria, most often Staphylococcus aureus, seed a heart valve and form vegetations that destroy the valve and shed septic emboli.","timeline":{"onset":"Acute over days (S. aureus) or subacute over weeks (viridans streptococci)","course":"Fatal without treatment; many patients need surgery"},"key_findings":{"history":["fever","fatigue and weight loss in subacute disease","new heart failure symptoms"],"exam":["new regurgitant murmur","splinter hemorrhages","painless Janeway lesions on the palms and soles","painful Osler nodes on the fingers","Roth spots"],"labs":["persistently positive blood cultures","raised inflammatory markers","hematuria from glomerulonephritis"],"imaging":["echocardiogram showing a vegetation: transthoracic first, transesophageal if negative or with a prosthetic valve"]},"diagnosis":{"confirmatory_tests":["three sets of blood cultures before antibiotics","echocardiogram"],"criteria":["Duke criteria: typical organisms in blood cultures and evidence of endocardial involvement are the major criteria"]},"management":{"first_line":["empiric IV vancomycin after blood cultures","prolonged IV antibiotics (4 to 6 weeks) guided by culture results"],"next_line":["surgery for heart failure, uncontrolled infection, abscess, or large vegetations with embolism"]},"complications":["heart failure from valve destruction","septic emboli to the brain, lungs, spleen or kidneys","perivalvular abscess","glomerulonephritis"]}'::jsonb),
  ('iron-deficiency-anemia', 1, 'in_review', null, null, '{"kind":"disease","name":"Iron deficiency anemia","aliases":["IDA"],"systems":["heme_onc"],"rotation":["IM","FM","peds"],"confused_with":[],"pearls":["Iron deficiency in a man or a postmenopausal woman is GI cancer until proven otherwise: scope both ends."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1482959756657","rung":"recall"},{"kind":"note","id":"1482959769125","rung":"recall"},{"kind":"note","id":"1539943644042","rung":"recall"},{"kind":"note","id":"1495729518859","rung":"management"},{"kind":"note","id":"1554630354556","rung":"management"},{"kind":"note","id":"1578616580406","rung":"management"}],"sources":[{"title":"AGA Clinical Practice Guidelines on the Gastrointestinal Evaluation of Iron Deficiency Anemia (2020)"}],"epidemiology":{"who":"Menstruating and pregnant women, infants, and older adults with GI blood loss","risk_factors":["heavy menstrual bleeding","gastrointestinal blood loss","pregnancy","low dietary iron","celiac disease","bariatric surgery"]},"pathophysiology":"Blood loss or poor absorption depletes iron stores, limiting hemoglobin synthesis and producing small, pale red cells.","timeline":{"onset":"Weeks to months","course":"Hemoglobin rises about 1 to 2 g/dL over 2 to 3 weeks of replacement"},"key_findings":{"history":["fatigue","exertional dyspnea","pica, especially craving ice","restless legs"],"exam":["pallor","koilonychia (spoon nails)","angular cheilitis"],"labs":["microcytic anemia (low MCV)","low ferritin","high RDW","low transferrin saturation","high total iron-binding capacity"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum ferritin","complete blood count"],"criteria":["ferritin below 30 ng/mL confirms iron deficiency in most adults"]},"management":{"first_line":["oral iron, once daily or on alternate days","find and treat the cause of blood loss"],"next_line":["IV iron if oral iron fails or isn''t tolerated","colonoscopy and upper endoscopy in men and postmenopausal women"]},"complications":["heart failure from severe anemia","poor pregnancy outcomes"]}'::jsonb),
  ('kawasaki-disease', 1, 'in_review', null, null, '{"kind":"disease","name":"Kawasaki disease","aliases":["Kawasaki syndrome","mucocutaneous lymph node syndrome"],"systems":["cardio"],"rotation":["peds"],"confused_with":[{"script_id":"iga-vasculitis","how_to_tell_apart":"Kawasaki disease gives prolonged fever, conjunctivitis, oral changes and coronary aneurysms; IgA vasculitis gives palpable purpura on the legs, joint pain, belly pain and hematuria."}],"pearls":["Kawasaki disease is one of the few reasons to give aspirin to a child despite the risk of Reye syndrome.","The features spell CRASH and burn: conjunctivitis, rash, adenopathy, strawberry tongue, hands and feet, with fever (burn) for 5 days.","Kawasaki disease is the leading cause of acquired heart disease in children in high-income countries."],"difficulty_tiers":{"MS1-2":["pathophysiology","diagnosis.criteria"],"MS3":["management.first_line","key_findings.imaging"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Diagnosis, Treatment, and Long-Term Management of Kawasaki Disease: A Scientific Statement for Health Professionals From the American Heart Association (2017)"},{"title":"Nelson Textbook of Pediatrics"}],"epidemiology":{"who":"Children under 5, especially of East Asian descent","risk_factors":["age under 5","East Asian ancestry, especially Japanese or Korean","male sex"]},"pathophysiology":"An acute medium-vessel vasculitis of unknown cause, possibly an immune response to an infectious trigger in genetically susceptible children. It favors the coronary arteries, where it can cause aneurysms.","timeline":{"onset":"Fever lasting 5 days or more","course":"Settles over weeks, but about 25% of untreated children develop coronary aneurysms"},"key_findings":{"history":["fever for 5 days or more","irritability","red eyes without discharge"],"exam":["bilateral nonexudative conjunctivitis","oral changes: strawberry tongue, red cracked lips","polymorphous rash","extremity changes: red, swollen hands and feet that later peel","cervical lymphadenopathy, usually one node over 1.5 cm"],"labs":["raised ESR or CRP","thrombocytosis in the second week","sterile pyuria","raised ALT"],"imaging":["echocardiogram for coronary aneurysms at diagnosis, then 1 to 2 weeks and 4 to 6 weeks after treatment"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","echocardiogram"],"criteria":["fever for 5 days or more plus at least 4 of 5 features: conjunctivitis, oral changes, rash, extremity changes, cervical lymphadenopathy"]},"management":{"first_line":["IV immunoglobulin (IVIG), ideally within 10 days of fever onset","aspirin"],"next_line":["a second dose of IVIG, or glucocorticoids, for fever that persists","long-term antiplatelet or anticoagulant therapy for large aneurysms"]},"complications":["coronary artery aneurysms","myocardial infarction","myocarditis","sudden death"]}'::jsonb),
  ('lipoprotein-metabolism', 1, 'in_review', null, null, '{"kind":"pathway","name":"Lipoprotein metabolism","aliases":["lipid transport"],"systems":["cardio","general"],"rotation":[],"confused_with":[],"pearls":["Chylomicrons carry apoB-48; VLDL, IDL and LDL carry apoB-100.","Triglycerides above 1000 mg/dL make the plasma milky and raise the risk of acute pancreatitis.","Tendon xanthomas, especially of the Achilles tendon, suggest familial hypercholesterolemia."],"difficulty_tiers":{"MS1-2":["steps","regulation","deficiencies"],"MS3":["drug_targets","pearls[1]"],"MS4":["treatment","deficiencies[3]"]},"anki_refs":[],"sources":[{"title":"Lippincott Illustrated Reviews: Biochemistry"},{"title":"Harper''s Illustrated Biochemistry"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}],"location":"Intestine, blood and liver","purpose":"Carries triglycerides and cholesterol, which do not dissolve in water, through the blood in lipoproteins: from the gut (the exogenous pathway), from the liver (the endogenous pathway) and back to the liver (reverse cholesterol transport).","steps":["the intestine packages dietary fat into chylomicrons, which carry apoB-48","lipoprotein lipase in capillaries releases fatty acids from chylomicrons and VLDL","the liver takes up chylomicron remnants through apoE","the liver secretes VLDL, which carries apoB-100 and becomes IDL and then LDL","LDL delivers cholesterol to tissues through LDL receptors, which bind apoB-100","HDL collects cholesterol from tissues and returns it to the liver (reverse cholesterol transport)"],"regulation":["insulin activates lipoprotein lipase","apoC-II activates lipoprotein lipase","LCAT, activated by apoA-I, esterifies cholesterol in HDL","cholesteryl ester transfer protein (CETP) moves cholesteryl esters from HDL to VLDL and LDL"],"cofactors":["apoC-II for lipoprotein lipase","apoE for remnant uptake","apoB-100 for binding the LDL receptor"],"deficiencies":["familial chylomicronemia (type I): lipoprotein lipase or apoC-II deficiency, with very high triglycerides, pancreatitis and eruptive xanthomas","familial hypercholesterolemia (type IIa): a defective LDL receptor, with very high LDL, tendon xanthomas and early heart attacks","dysbetalipoproteinemia (type III): apoE2 variant, with palmar xanthomas","abetalipoproteinemia: MTP deficiency, with no apoB lipoproteins, fat malabsorption, acanthocytes and vitamin E deficiency"],"drug_targets":["statins raise the number of LDL receptors","PCSK9 inhibitors stop LDL receptors from being broken down","fibrates activate PPAR-alpha and lipoprotein lipase, lowering triglycerides","ezetimibe blocks cholesterol absorption in the intestine"],"treatment":["familial hypercholesterolemia: high-intensity statin, then ezetimibe and PCSK9 inhibitors","familial chylomicronemia: a very low-fat diet","abetalipoproteinemia: fat-soluble vitamins, especially vitamin E, and a low-fat diet"]}'::jsonb),
  ('long-qt-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Long QT syndrome","aliases":["LQTS","long QT"],"systems":["cardio"],"rotation":["IM","peds"],"confused_with":[{"script_id":"ventricular-tachycardia","how_to_tell_apart":"Long QT syndrome causes polymorphic VT (torsades de pointes) with a long QT between episodes, treated with magnesium; scar-related VT is usually monomorphic, with structural heart disease."}],"pearls":["Typical triggers by type: exercise or swimming in type 1, a sudden noise in type 2, sleep in type 3.","Romano-Ward syndrome is autosomal dominant; Jervell and Lange-Nielsen syndrome is autosomal recessive with deafness.","Check the QTc before starting drugs such as methadone, haloperidol or ondansetron in high-risk patients."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[1]"],"MS3":["epidemiology.risk_factors","management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2017 AHA/ACC/HRS Guideline for Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death"},{"title":"2022 ESC Guidelines for the management of patients with ventricular arrhythmias and the prevention of sudden cardiac death"}],"epidemiology":{"who":"Congenital forms in children and young adults; acquired forms, more common, in adults on QT-prolonging drugs","risk_factors":["congenital ion channel variants (KCNQ1, KCNH2, SCN5A)","QT-prolonging drugs: antiarrhythmics, macrolides, fluoroquinolones, antipsychotics, methadone, ondansetron","hypokalemia","hypomagnesemia","hypocalcemia","bradycardia","female sex"]},"pathophysiology":"Delayed ventricular repolarization lengthens the QT interval. Early afterdepolarizations can trigger torsades de pointes, a polymorphic ventricular tachycardia that can degenerate into ventricular fibrillation.","timeline":{"onset":"Congenital: syncope or arrest in childhood or youth, often with a trigger; acquired: after a new drug or electrolyte loss","course":"Torsades can cause sudden death"},"key_findings":{"history":["syncope with exercise, swimming, a sudden loud noise or emotion","palpitations","family history of sudden death","congenital deafness (Jervell and Lange-Nielsen syndrome)"],"exam":["often normal"],"labs":["potassium, magnesium and calcium"],"imaging":["ECG with a prolonged QTc: 480 ms or more, or 460 ms or more with unexplained syncope, supports the diagnosis"]},"diagnosis":{"confirmatory_tests":["12-lead ECG with the corrected QT (QTc)","genetic testing for congenital forms"],"criteria":["a QTc of 500 ms or more carries a high risk of torsades"]},"management":{"first_line":["stop QT-prolonging drugs","correct potassium and magnesium","beta blockers (nadolol or propranolol) for congenital long QT"],"next_line":["IV magnesium for torsades de pointes","overdrive pacing, or isoproterenol for acquired pause-dependent torsades (not in congenital long QT)","ICD for survivors of cardiac arrest"]},"complications":["torsades de pointes","ventricular fibrillation","sudden cardiac death"]}'::jsonb),
  ('loop-diuretics', 1, 'in_review', null, null, '{"kind":"drug","name":"Loop diuretics","aliases":["loop diuretic"],"systems":["cardio","renal"],"rotation":[],"confused_with":[{"script_id":"thiazide-diuretics","how_to_tell_apart":"Loop diuretics act on the thick ascending limb, are stronger and lose calcium; thiazides act on the distal convoluted tubule and keep calcium.","compare":[{"label":"Site","text":"Thick ascending limb","source_field":"mechanism"},{"label":"Calcium","text":"Lost: hypocalcemia","source_field":"adverse_effects[2]"}]},{"script_id":"mineralocorticoid-receptor-antagonists","how_to_tell_apart":"Loop diuretics such as furosemide waste potassium and cause hypokalemia; spironolactone keeps potassium and can cause hyperkalemia, which is why the two are often combined.","compare":[{"label":"Potassium","text":"Lost: hypokalemia","source_field":"adverse_effects[0]"},{"label":"Site","text":"Thick ascending limb","source_field":"mechanism"}]},{"script_id":"carbonic-anhydrase-inhibitors","how_to_tell_apart":"Loop diuretics act on the thick ascending limb and cause a metabolic alkalosis; acetazolamide acts on the proximal tubule and causes a metabolic acidosis."}],"pearls":["Loops lose calcium, thiazides keep it: loop diuretics cause hypocalcemia, thiazides cause hypercalcemia.","Ethacrynic acid is the loop diuretic without a sulfonamide group, used when a sulfa reaction is a concern.","Loop diuretics cause a hypokalemic metabolic alkalosis, also called contraction alkalosis."],"difficulty_tiers":{"MS1-2":["mechanism","adverse_effects"],"MS3":["indications","monitoring"],"MS4":["pharmacokinetics[1]","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"class":"Loop diuretics","class_members":["furosemide","bumetanide","torsemide","ethacrynic acid"],"mechanism":"Block the Na-K-2Cl cotransporter (NKCC2) in the thick ascending limb of the loop of Henle. Sodium and water loss is strong, and more calcium and magnesium are lost in the urine.","pharmacokinetics":["work within minutes when given IV","oral furosemide is absorbed variably; bumetanide and torsemide are absorbed more reliably","all are sulfonamides except ethacrynic acid"],"indications":["fluid overload in heart failure","acute pulmonary edema","edema from cirrhosis or nephrotic syndrome","hyperkalemia"],"adverse_effects":["hypokalemia","hypomagnesemia","hypocalcemia","volume depletion and prerenal kidney injury","ototoxicity","metabolic alkalosis","hyperuricemia and gout"],"contraindications":["anuria","severe volume depletion"],"interactions":["aminoglycosides add to ototoxicity","raise lithium levels","digoxin toxicity is more likely with low potassium or magnesium"],"monitoring":["potassium, magnesium and creatinine","daily weight and fluid balance"],"overdose":{"features":["dehydration","hypotension","electrolyte loss"],"treatment":["IV fluids and electrolyte replacement"]}}'::jsonb),
  ('microscopic-polyangiitis', 1, 'in_review', null, null, '{"kind":"disease","name":"Microscopic polyangiitis","aliases":["MPA"],"systems":["cardio","renal","pulm"],"rotation":["IM"],"confused_with":[{"script_id":"granulomatosis-with-polyangiitis","how_to_tell_apart":"Microscopic polyangiitis has no granulomas and no upper airway disease and is usually MPO-ANCA; granulomatosis with polyangiitis involves the sinuses and nose, has granulomas and is usually PR3-ANCA."},{"script_id":"polyarteritis-nodosa","how_to_tell_apart":"Microscopic polyangiitis inflames small vessels, causes glomerulonephritis and lung hemorrhage and is usually MPO-ANCA positive; polyarteritis nodosa inflames medium arteries, spares the lungs and glomeruli and is ANCA-negative."}],"pearls":["Pauci-immune means few or no immune deposits on immunofluorescence, unlike lupus nephritis or anti-GBM disease.","No granulomas and no upper airway disease separate it from granulomatosis with polyangiitis.","Hydralazine and propylthiouracil can cause drug-induced MPO-ANCA vasculitis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2021 American College of Rheumatology/Vasculitis Foundation Guideline for the Management of Antineutrophil Cytoplasmic Antibody-Associated Vasculitis"},{"title":"Robbins and Cotran Pathologic Basis of Disease"}],"epidemiology":{"who":"Adults, usually aged 50 to 70","risk_factors":["older age","silica exposure","drugs such as hydralazine and propylthiouracil (drug-induced ANCA vasculitis)"]},"pathophysiology":"A necrotizing small-vessel vasculitis without granulomas, usually with MPO-ANCA (p-ANCA). It mainly affects the kidneys, as a pauci-immune glomerulonephritis, and the lungs, with capillaritis and hemorrhage.","timeline":{"onset":"Weeks to months","course":"Fatal untreated; relapses are less common than in granulomatosis with polyangiitis"},"key_findings":{"history":["fever, weight loss and muscle pain","hemoptysis","dark urine","numbness or weakness from mononeuritis multiplex"],"exam":["palpable purpura","no upper airway or sinus disease"],"labs":["positive MPO-ANCA (p-ANCA)","hematuria with red cell casts","rising creatinine"],"imaging":["chest CT with diffuse alveolar hemorrhage or fibrosis"]},"diagnosis":{"confirmatory_tests":["MPO-ANCA","kidney biopsy showing pauci-immune necrotizing crescentic glomerulonephritis"],"criteria":[]},"management":{"first_line":["induction with glucocorticoids plus rituximab or cyclophosphamide"],"next_line":["maintenance with rituximab or azathioprine","trimethoprim-sulfamethoxazole to prevent Pneumocystis pneumonia"]},"complications":["rapidly progressive glomerulonephritis","diffuse alveolar hemorrhage","end-stage kidney disease"]}'::jsonb),
  ('mineralocorticoid-receptor-antagonists', 1, 'in_review', null, null, '{"kind":"drug","name":"Spironolactone and eplerenone","aliases":["mineralocorticoid receptor antagonists","MRAs","aldosterone antagonists"],"systems":["cardio","renal","endo"],"rotation":[],"confused_with":[{"script_id":"loop-diuretics","how_to_tell_apart":"Spironolactone keeps potassium and can cause hyperkalemia; loop diuretics such as furosemide waste potassium and cause hypokalemia, which is why the two are often combined.","compare":[{"label":"Potassium","text":"Kept: hyperkalemia","source_field":"adverse_effects[0]"},{"label":"Site","text":"Collecting duct","source_field":"mechanism"}]}],"pearls":["Spironolactone also blocks androgen receptors, causing gynecomastia; eplerenone rarely does.","In cirrhotic ascites, spironolactone is combined with furosemide in a 100 to 40 ratio.","Spironolactone is the treatment of choice for bilateral adrenal hyperplasia causing primary hyperaldosteronism."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","adverse_effects","monitoring"],"MS4":["pearls[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"class":"Mineralocorticoid receptor antagonists (potassium-sparing diuretics)","class_members":["spironolactone","eplerenone","finerenone"],"mechanism":"Block the aldosterone (mineralocorticoid) receptor in the collecting duct, so less sodium is reabsorbed and less potassium and hydrogen are excreted. They also block aldosterone''s fibrosis-promoting effects on the heart.","pharmacokinetics":["spironolactone has active metabolites and takes days to reach full effect","eplerenone is more selective and metabolized by CYP3A4"],"indications":["heart failure with reduced ejection fraction","primary hyperaldosteronism","resistant hypertension","ascites from cirrhosis","diabetic kidney disease (finerenone)","acne and hirsutism (spironolactone)"],"adverse_effects":["hyperkalemia","gynecomastia with spironolactone","menstrual irregularity","metabolic acidosis","rise in creatinine"],"contraindications":["potassium above 5.0","eGFR below 30, for heart failure use"],"interactions":["ACE inhibitors, ARBs and potassium supplements raise potassium further","strong CYP3A4 inhibitors raise eplerenone levels"],"monitoring":["potassium and creatinine at 3 days, 1 week, then monthly for 3 months"],"overdose":{"features":["hyperkalemia"],"treatment":["stop the drug and treat hyperkalemia"]}}'::jsonb),
  ('mitral-regurgitation', 1, 'in_review', null, null, '{"kind":"disease","name":"Mitral regurgitation","aliases":["mitral insufficiency","mitral valve regurgitation"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"aortic-stenosis","how_to_tell_apart":"Mitral regurgitation is a holosystolic blowing murmur at the apex radiating to the axilla; aortic stenosis is a crescendo-decrescendo murmur at the right upper sternal border radiating to the carotids.","compare":[{"label":"Murmur","text":"Holosystolic, at the apex","source_field":"key_findings.exam[0]"},{"label":"Radiates","text":"To the axilla","source_field":"key_findings.exam[0]"}]},{"script_id":"mitral-valve-prolapse","how_to_tell_apart":"Established mitral regurgitation gives a holosystolic murmur from S1 that radiates to the axilla; mitral valve prolapse gives a midsystolic click with a late systolic murmur."}],"pearls":["Papillary muscle rupture, usually 3 to 5 days after an inferior MI, causes acute mitral regurgitation and flash pulmonary edema.","Repair is preferred to replacement whenever the valve can be repaired.","The murmur gets louder with handgrip, which raises afterload."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["epidemiology.risk_factors","management.first_line"],"MS4":["diagnosis.criteria","management.next_line"]},"anki_refs":[],"sources":[{"title":"2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease"},{"title":"2025 ESC/EACTS Guidelines for the management of valvular heart disease"}],"epidemiology":{"who":"Adults; primary disease from a damaged valve such as mitral valve prolapse, secondary disease from a dilated left ventricle","risk_factors":["mitral valve prolapse","myocardial infarction with papillary muscle rupture","dilated cardiomyopathy","rheumatic heart disease","infective endocarditis"]},"pathophysiology":"Blood leaks back from the left ventricle into the left atrium in systole. In chronic disease the atrium and ventricle dilate to cope with the extra volume. Acute regurgitation, such as papillary muscle rupture after an MI, floods a normal-sized atrium and causes pulmonary edema.","timeline":{"onset":"Acute (hours, after an MI or endocarditis) or chronic (years)","course":"Chronic disease is tolerated for years before the ventricle fails"},"key_findings":{"history":["exertional dyspnea","fatigue","palpitations from atrial fibrillation","sudden pulmonary edema in acute disease"],"exam":["holosystolic blowing murmur at the apex radiating to the axilla","soft S1","S3 from volume overload","displaced apex beat"],"labs":["raised BNP as the ventricle fails"],"imaging":["echocardiogram showing the regurgitant jet and its cause","chest X-ray with an enlarged left atrium"]},"diagnosis":{"confirmatory_tests":["transthoracic echocardiogram","transesophageal echocardiogram to plan repair"],"criteria":["severe primary regurgitation with symptoms, or with a left ventricular ejection fraction of 60% or less, is an indication for intervention"]},"management":{"first_line":["surgical mitral valve repair, preferred over replacement, for severe primary regurgitation with symptoms or ventricular dysfunction","guideline-directed heart failure therapy for secondary regurgitation"],"next_line":["transcatheter edge-to-edge repair (MitraClip) when surgical risk is high","urgent surgery for acute regurgitation from papillary muscle rupture"]},"complications":["atrial fibrillation","heart failure","pulmonary hypertension","infective endocarditis"]}'::jsonb),
  ('mitral-stenosis', 1, 'in_review', null, null, '{"kind":"disease","name":"Mitral stenosis","aliases":["mitral valve stenosis"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"aortic-regurgitation","how_to_tell_apart":"Mitral stenosis is a mid-diastolic rumble at the apex after an opening snap; aortic regurgitation is an early diastolic decrescendo murmur at the left sternal border with a wide pulse pressure."}],"pearls":["A shorter interval between S2 and the opening snap means more severe stenosis.","In rheumatic mitral stenosis with atrial fibrillation, warfarin is used rather than a direct oral anticoagulant.","Pregnancy often unmasks mitral stenosis, because blood volume and heart rate rise."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["pearls[0]","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease"},{"title":"2025 ESC/EACTS Guidelines for the management of valvular heart disease"}],"epidemiology":{"who":"Women more than men, decades after rheumatic fever; common where rheumatic heart disease persists","risk_factors":["rheumatic heart disease","mitral annular calcification in older adults","congenital mitral stenosis, rarely"]},"pathophysiology":"Rheumatic scarring fuses the commissures and thickens the leaflets, narrowing the mitral orifice. Left atrial pressure rises, the atrium enlarges, and pressure backs up into the lungs, causing pulmonary hypertension.","timeline":{"onset":"Symptoms 20 to 40 years after rheumatic fever","course":"Slowly progressive; pregnancy, atrial fibrillation or exercise can unmask it"},"key_findings":{"history":["exertional dyspnea","orthopnea","hemoptysis","palpitations from atrial fibrillation","hoarseness from left atrial pressure on the recurrent laryngeal nerve (Ortner syndrome)","stroke from embolism"],"exam":["opening snap after S2","mid-diastolic rumble at the apex, heard best with the bell in the left lateral position","loud S1","malar flush"],"labs":[],"imaging":["echocardiogram showing fused commissures, thickened leaflets and a small valve area","chest X-ray with an enlarged left atrium","ECG with left atrial enlargement or atrial fibrillation"]},"diagnosis":{"confirmatory_tests":["transthoracic echocardiogram"],"criteria":["severe mitral stenosis: a valve area of 1.5 square centimeters or less"]},"management":{"first_line":["percutaneous balloon mitral commissurotomy for severe symptomatic stenosis with favorable valve anatomy","beta blockers or other rate control to lengthen diastole","warfarin for atrial fibrillation or prior embolism"],"next_line":["surgical mitral valve replacement when balloon commissurotomy is unsuitable","diuretics for congestion"]},"complications":["atrial fibrillation","left atrial thrombus","stroke","pulmonary hypertension","right heart failure","hemoptysis"]}'::jsonb),
  ('mitral-valve-prolapse', 1, 'in_review', null, null, '{"kind":"disease","name":"Mitral valve prolapse","aliases":["MVP","floppy mitral valve","Barlow syndrome"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"mitral-regurgitation","how_to_tell_apart":"Mitral valve prolapse gives a midsystolic click with a late systolic murmur; established mitral regurgitation gives a holosystolic murmur from S1 that radiates to the axilla."}],"pearls":["Maneuvers that shrink the ventricle, such as Valsalva or standing, make the click come earlier.","Mitral valve prolapse is the most common cause of primary mitral regurgitation needing surgery in high-income countries.","Routine endocarditis prophylaxis is not recommended for mitral valve prolapse."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["pearls[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2020 ACC/AHA Guideline for the Management of Patients With Valvular Heart Disease"},{"title":"2025 ESC/EACTS Guidelines for the management of valvular heart disease"}],"epidemiology":{"who":"About 2 to 3% of people, more often in people with connective tissue disorders","risk_factors":["Marfan syndrome","Ehlers-Danlos syndrome","autosomal dominant polycystic kidney disease","family history"]},"pathophysiology":"Myxomatous degeneration thickens and lengthens the mitral leaflets and chordae, so one or both leaflets bulge back into the left atrium in systole. Some develop mitral regurgitation.","timeline":{"onset":"Usually found incidentally","course":"Mostly benign; a minority progress to significant mitral regurgitation or chordal rupture"},"key_findings":{"history":["usually no symptoms","palpitations","atypical chest pain"],"exam":["midsystolic click followed by a late systolic murmur","the click moves earlier with Valsalva or standing and later with squatting or handgrip"],"labs":[],"imaging":["echocardiogram showing a leaflet displaced more than 2 mm into the left atrium"]},"diagnosis":{"confirmatory_tests":["transthoracic echocardiogram"],"criteria":["systolic displacement of a mitral leaflet more than 2 mm above the annulus"]},"management":{"first_line":["reassurance and periodic echocardiography","beta blockers for palpitations"],"next_line":["mitral valve repair for severe regurgitation"]},"complications":["mitral regurgitation","chordal rupture with acute regurgitation","arrhythmias","infective endocarditis","sudden death, rarely"]}'::jsonb),
  ('myocarditis', 1, 'in_review', null, null, '{"kind":"disease","name":"Myocarditis","aliases":["viral myocarditis"],"systems":["cardio"],"rotation":["IM","peds"],"confused_with":[{"script_id":"acute-pericarditis","how_to_tell_apart":"Myocarditis inflames the heart muscle, raising troponin and weakening contraction; pericarditis inflames the pericardium, causing pleuritic pain, a rub and PR depression, with troponin normal unless the muscle is involved."}],"pearls":["Coxsackievirus B is the classic cause.","Athletes should avoid competitive sport for 3 to 6 months after myocarditis, because of the risk of sudden death.","Giant cell myocarditis progresses fast, causes heart block and ventricular tachycardia, and needs immunosuppression."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[0]"],"MS3":["diagnosis","management.first_line"],"MS4":["management.next_line","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2025 ESC Guidelines for the management of myocarditis and pericarditis"},{"title":"2024 ACC Expert Consensus Decision Pathway on Strategies and Criteria for the Diagnosis and Management of Myocarditis"}],"epidemiology":{"who":"Children and young adults, more often males","risk_factors":["viral infection, such as coxsackievirus B, parvovirus B19, adenovirus or SARS-CoV-2","mRNA COVID-19 vaccination, rarely, mostly in young men","immune checkpoint inhibitors","Chagas disease","autoimmune disease, as in giant cell myocarditis","hypersensitivity to drugs"]},"pathophysiology":"Inflammation of the heart muscle, usually from a viral infection and the immune response to it, injures myocytes and can lead to heart failure, arrhythmias or dilated cardiomyopathy.","timeline":{"onset":"Days to weeks after a viral illness","course":"Most recover; some develop dilated cardiomyopathy; fulminant cases need mechanical support"},"key_findings":{"history":["recent flu-like or gastrointestinal illness","chest pain","dyspnea and fatigue","palpitations or syncope"],"exam":["tachycardia out of proportion to fever","signs of heart failure","S3"],"labs":["raised troponin","raised CRP or ESR","raised BNP"],"imaging":["ECG with ST changes, arrhythmias or heart block","echocardiogram with reduced function and wall motion abnormalities","cardiac MRI with late gadolinium enhancement in a nonischemic, subepicardial pattern","coronary angiography to exclude a heart attack"]},"diagnosis":{"confirmatory_tests":["cardiac MRI","endomyocardial biopsy for severe or unexplained cases"],"criteria":["raised troponin with typical MRI findings and no significant coronary disease"]},"management":{"first_line":["supportive care and guideline-directed heart failure therapy","no competitive sport for 3 to 6 months"],"next_line":["mechanical circulatory support for fulminant myocarditis","immunosuppression for giant cell or eosinophilic myocarditis","high-dose glucocorticoids for checkpoint inhibitor myocarditis"]},"complications":["dilated cardiomyopathy","heart failure","ventricular arrhythmias and sudden death","heart block"]}'::jsonb),
  ('nephritic-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Nephritic syndrome","aliases":["acute glomerulonephritis"],"systems":["renal"],"rotation":["IM","peds"],"confused_with":[{"script_id":"nephrotic-syndrome","how_to_tell_apart":"Nephrotic syndrome has heavy proteinuria above 3.5 g/day, low albumin and a bland urine sediment; nephritic syndrome has red blood cell casts, hypertension and a rising creatinine.","compare":[{"label":"Urine","text":"Hematuria, RBC casts","source_field":"key_findings.labs[0]"},{"label":"Protein","text":"Under 3.5 g/day","source_field":"key_findings.labs[2]"},{"label":"Classic","text":"Post-strep GN","source_field":"epidemiology.risk_factors[0]"}]}],"pearls":["IgA nephropathy causes hematuria within a few days of an upper respiratory infection, while post-streptococcal glomerulonephritis appears 1 to 3 weeks after a sore throat."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.labs[0]","epidemiology.risk_factors","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[{"kind":"note","id":"1471806675606"},{"kind":"note","id":"1471806688179"},{"kind":"note","id":"1475376633607"},{"kind":"note","id":"1555536173966"},{"kind":"note","id":"1582854828887"}],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}],"epidemiology":{"who":"Children and adults; post-infectious glomerulonephritis is common in children, and IgA nephropathy is the most common glomerulonephritis worldwide","risk_factors":["post-streptococcal glomerulonephritis","IgA nephropathy","lupus nephritis","ANCA-associated vasculitis","anti-GBM disease","infective endocarditis"]},"pathophysiology":"Immune-mediated inflammation of the glomeruli damages the capillary walls, letting red cells into the urine and lowering filtration, which causes salt and water retention, hypertension and a rising creatinine.","timeline":{"onset":"Days to weeks","course":"Post-streptococcal disease usually resolves in children; rapidly progressive forms can cause kidney failure within weeks"},"key_findings":{"history":["cola-colored urine","reduced urine output","recent sore throat or skin infection"],"exam":["hypertension","periorbital or leg edema"],"labs":["hematuria with red blood cell casts and dysmorphic red cells","rising creatinine","proteinuria usually below 3.5 g/day","low complement C3 in post-streptococcal glomerulonephritis and lupus nephritis"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urinalysis with microscopy for red blood cell casts","complement levels (C3 and C4)","serologies: ANCA, anti-GBM, ANA, ASO","kidney biopsy"],"criteria":["hematuria with red cell casts, hypertension, edema and reduced kidney function"]},"management":{"first_line":["supportive care","blood pressure control","loop diuretics and salt restriction for fluid overload","treat the underlying cause"],"next_line":["immunosuppression (steroids with cyclophosphamide or rituximab) for rapidly progressive disease such as ANCA vasculitis","plasma exchange for anti-GBM disease","dialysis for refractory fluid overload, hyperkalemia or uremia"]},"complications":["acute kidney injury","hypertensive emergency","pulmonary edema","progression to chronic kidney disease"]}'::jsonb),
  ('nephrotic-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Nephrotic syndrome","aliases":[],"systems":["renal"],"rotation":["IM","peds"],"confused_with":[{"script_id":"nephritic-syndrome","how_to_tell_apart":"Nephritic syndrome has hematuria with red blood cell casts, hypertension and a rising creatinine, with proteinuria usually below 3.5 g/day; nephrotic syndrome has heavy proteinuria above 3.5 g/day with a bland sediment.","compare":[{"label":"Urine","text":"Fatty casts","source_field":"key_findings.labs[3]"},{"label":"Protein","text":"Over 3.5 g/day","source_field":"key_findings.labs[0]"},{"label":"Classic","text":"Minimal change","source_field":"epidemiology.who"}]}],"pearls":["Urinary loss of antithrombin III makes nephrotic patients hypercoagulable; renal vein thrombosis is classic with membranous nephropathy."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","epidemiology.risk_factors","management.first_line[0]"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1475363774930"},{"kind":"note","id":"1475364023607"},{"kind":"note","id":"1497562168496"},{"kind":"note","id":"1539282631413"},{"kind":"note","id":"1555542582278"}],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}],"epidemiology":{"who":"Children, usually from minimal change disease, and adults, most often from membranous nephropathy, FSGS or diabetic kidney disease","risk_factors":["minimal change disease","focal segmental glomerulosclerosis","membranous nephropathy","diabetic nephropathy","amyloidosis","lupus nephritis"]},"pathophysiology":"Injury to the glomerular filtration barrier (the podocytes) lets large amounts of protein leak into the urine, causing low serum albumin, edema and a compensatory rise in hepatic lipoprotein synthesis. Urinary loss of anticoagulant proteins makes patients hypercoagulable.","timeline":{"onset":"Usually over weeks","course":"Minimal change disease often remits with steroids; other causes may progress to chronic kidney disease"},"key_findings":{"history":["swelling around the eyes and legs","foamy urine","weight gain"],"exam":["pitting edema","periorbital edema","ascites or pleural effusions"],"labs":["proteinuria above 3.5 g/day","serum albumin below 3 g/dL","hyperlipidemia","fatty casts and oval fat bodies in the urine"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urine protein-to-creatinine ratio","24-hour urine protein","kidney biopsy to find the cause in adults"],"criteria":["proteinuria above 3.5 g/day with hypoalbuminemia and edema; hyperlipidemia is common"]},"management":{"first_line":["ACE inhibitor or ARB to reduce proteinuria","loop diuretics and salt restriction for edema","treat the underlying cause"],"next_line":["corticosteroids for minimal change disease","statin for persistent hyperlipidemia","anticoagulation for thrombosis"]},"complications":["renal vein thrombosis","deep vein thrombosis and pulmonary embolism","infection","acute kidney injury"]}'::jsonb),
  ('niacin', 1, 'in_review', null, null, '{"kind":"drug","name":"Niacin","aliases":["nicotinic acid"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"fibrates","how_to_tell_apart":"Niacin raises HDL the most and works by inhibiting lipolysis in fat; fibrates mainly lower triglycerides by activating PPAR-alpha."}],"pearls":["Aspirin taken 30 minutes before niacin reduces the flushing, which is prostaglandin-mediated.","Niacin raises HDL more than any other drug, but raising HDL this way did not prevent heart attacks.","Niacin deficiency causes pellagra: dermatitis, diarrhea and dementia."],"difficulty_tiers":{"MS1-2":["mechanism","adverse_effects"],"MS3":["indications"],"MS4":["pharmacokinetics","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}],"class":"Lipid-lowering vitamin (vitamin B3, nicotinic acid)","class_members":["niacin, immediate-release","niacin, extended-release"],"mechanism":"Inhibits lipolysis in adipose tissue and reduces VLDL production by the liver, so LDL and triglycerides fall and HDL rises more than with any other drug.","pharmacokinetics":["immediate-release niacin causes more flushing; extended-release causes less flushing but more liver toxicity"],"indications":["rarely used now: outcome trials (AIM-HIGH, HPS2-THRIVE) showed no benefit added to a statin","historically for low HDL and mixed dyslipidemia"],"adverse_effects":["flushing and itching from prostaglandin release","hepatotoxicity","hyperglycemia","hyperuricemia and gout","myopathy with statins"],"contraindications":["active liver disease","active peptic ulcer disease"],"interactions":["raises the risk of myopathy with statins"],"monitoring":["liver enzymes","glucose and uric acid"],"overdose":{"features":["flushing","liver injury"],"treatment":["stop the drug"]}}'::jsonb),
  ('nitrates', 1, 'in_review', null, null, '{"kind":"drug","name":"Nitrates","aliases":["organic nitrates"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"hydralazine","how_to_tell_apart":"Nitrates dilate veins and lower preload; hydralazine dilates arterioles and lowers afterload. Together, as isosorbide dinitrate with hydralazine, they treat heart failure."}],"pearls":["A nitrate-free interval of 10 to 12 hours each day prevents tolerance.","Workers exposed to nitrates in explosives factories get headaches and dizziness at the start of the week that fade by the weekend (Monday disease).","Avoid nitrates in right ventricular infarction (low blood pressure, raised JVP, clear lungs), which depends on preload."],"difficulty_tiers":{"MS1-2":["mechanism","adverse_effects"],"MS3":["indications","contraindications"],"MS4":["overdose","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2023 AHA/ACC/ACCP/ASPC/NLA/PCNA Guideline for the Management of Patients With Chronic Coronary Disease"}],"class":"Organic nitrates (nitric oxide donors)","class_members":["nitroglycerin","isosorbide dinitrate","isosorbide mononitrate"],"mechanism":"Release nitric oxide in vascular smooth muscle, which raises cGMP and relaxes the vessel. Veins dilate much more than arteries, so preload and ventricular wall stress fall and the heart needs less oxygen.","pharmacokinetics":["nitroglycerin has high first-pass metabolism, so it is given sublingually, as a patch or IV","isosorbide mononitrate is taken by mouth once daily"],"indications":["relief of an angina attack (sublingual nitroglycerin)","angina prevention (long-acting nitrates)","chest pain in acute coronary syndrome","acute pulmonary edema","hypertensive emergency (IV nitroglycerin)","heart failure, as isosorbide dinitrate with hydralazine"],"adverse_effects":["headache","flushing","hypotension","reflex tachycardia","tolerance with continuous use"],"contraindications":["use of a PDE5 inhibitor: sildenafil in the past 24 hours or tadalafil in the past 48 hours","right ventricular infarction","severe aortic stenosis","hypertrophic obstructive cardiomyopathy"],"interactions":["PDE5 inhibitors cause severe hypotension"],"monitoring":["blood pressure"],"overdose":{"features":["hypotension","methemoglobinemia"],"treatment":["methylene blue for methemoglobinemia"]}}'::jsonb),
  ('non-dihydropyridine-calcium-channel-blockers', 1, 'in_review', null, null, '{"kind":"drug","name":"Verapamil and diltiazem","aliases":["non-dihydropyridine calcium channel blockers","non-dihydropyridines"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"dihydropyridine-calcium-channel-blockers","how_to_tell_apart":"Verapamil and diltiazem act mainly on the heart, slowing the rate and AV conduction; dihydropyridines act mainly on arteries and lower blood pressure without slowing the heart.","compare":[{"label":"Acts on","text":"Heart","source_field":"mechanism"},{"label":"Heart rate","text":"Slowed","source_field":"mechanism"}]},{"script_id":"adenosine","how_to_tell_apart":"Both stop SVT by blocking the AV node, but verapamil and diltiazem act for hours and also slow the rate in atrial fibrillation, while adenosine works for only seconds."}],"pearls":["Verapamil is the calcium channel blocker most likely to cause constipation.","Never give AV nodal blockers such as verapamil for atrial fibrillation with Wolff-Parkinson-White syndrome; they can speed conduction down the accessory pathway.","High blood sugar in a bradycardic overdose points to a calcium channel blocker rather than a beta blocker."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","contraindications"],"MS4":["pearls[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}],"class":"Non-dihydropyridine calcium channel blockers (class IV antiarrhythmics)","class_members":["verapamil","diltiazem"],"mechanism":"Block L-type calcium channels mainly in the heart, slowing the SA node, slowing conduction through the AV node and reducing contractility. They dilate arteries less than dihydropyridines do.","pharmacokinetics":["both are metabolized by the liver and inhibit CYP3A4","IV diltiazem is used for quick rate control"],"indications":["rate control in atrial fibrillation or flutter","supraventricular tachycardia","stable angina","vasospastic angina","hypertension","cluster headache prevention (verapamil)"],"adverse_effects":["bradycardia","AV block","constipation, especially with verapamil","worsening heart failure","hypotension","peripheral edema","gingival hyperplasia"],"contraindications":["heart failure with reduced ejection fraction","second- or third-degree AV block or sick sinus syndrome","atrial fibrillation with Wolff-Parkinson-White syndrome","hypotension"],"interactions":["beta blockers add to bradycardia and AV block","they inhibit CYP3A4, raising levels of simvastatin and other drugs","raise digoxin levels"],"monitoring":["heart rate","blood pressure","PR interval"],"overdose":{"features":["bradycardia","hypotension","AV block","hyperglycemia"],"treatment":["IV calcium","high-dose insulin with glucose","vasopressors","pacing"]}}'::jsonb),
  ('patent-ductus-arteriosus', 1, 'in_review', null, null, '{"kind":"disease","name":"Patent ductus arteriosus","aliases":["PDA"],"systems":["cardio"],"rotation":["peds"],"confused_with":[{"script_id":"ventricular-septal-defect","how_to_tell_apart":"A PDA gives a continuous machine-like murmur below the left clavicle with bounding pulses; a VSD gives a holosystolic murmur at the left lower sternal border."}],"pearls":["Indomethacin closes the duct; prostaglandin E1 keeps it open.","Congenital rubella classically causes PDA, cataracts and deafness.","Eisenmenger syndrome from a PDA turns the toes blue but not the fingers, because deoxygenated blood enters the aorta after the arch vessels."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["management.first_line"],"MS4":["management.next_line","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Moss & Adams'' Heart Disease in Infants, Children, and Adolescents"},{"title":"2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"}],"epidemiology":{"who":"Premature infants, and infants exposed to rubella in pregnancy","risk_factors":["prematurity","congenital rubella","high altitude","female sex"]},"pathophysiology":"The ductus arteriosus, which links the pulmonary artery to the aorta in the fetus, fails to close after birth. Blood shunts from the aorta into the pulmonary artery, overloading the lungs and left heart. Prostaglandin E2 keeps the duct open; rising oxygen and falling prostaglandins normally close it.","timeline":{"onset":"Days after birth, as pulmonary resistance falls","course":"Small ducts may close in the first months; large ones cause heart failure or, untreated, Eisenmenger syndrome"},"key_findings":{"history":["poor feeding","fast breathing","failure to thrive"],"exam":["continuous machine-like murmur below the left clavicle","bounding pulses with a wide pulse pressure","differential cyanosis in Eisenmenger syndrome: blue toes, pink fingers"],"labs":[],"imaging":["echocardiogram showing the duct and the shunt","chest X-ray with increased pulmonary vascular markings"]},"diagnosis":{"confirmatory_tests":["echocardiogram"],"criteria":[]},"management":{"first_line":["indomethacin, ibuprofen or acetaminophen to close a hemodynamically significant duct in premature infants"],"next_line":["catheter or surgical closure for a large duct that persists or when drugs fail"]},"complications":["heart failure","infective endarteritis","Eisenmenger syndrome with differential cyanosis"]}'::jsonb),
  ('pcsk9-inhibitors', 1, 'in_review', null, null, '{"kind":"drug","name":"PCSK9 inhibitors","aliases":["PCSK9 antibodies"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"ezetimibe","how_to_tell_apart":"PCSK9 inhibitors are injected and lower LDL by about 50 to 60%; ezetimibe is a pill that lowers LDL by about 20%."}],"pearls":["The FOURIER (evolocumab) and ODYSSEY OUTCOMES (alirocumab) trials showed fewer cardiovascular events.","Gain-of-function PCSK9 variants cause familial hypercholesterolemia; loss-of-function variants lower LDL for life.","Statins raise PCSK9 levels, one reason adding a PCSK9 inhibitor works so well."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications"],"MS4":["pearls[1]","pharmacokinetics[1]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"},{"title":"2022 ACC Expert Consensus Decision Pathway on the Role of Nonstatin Therapies for LDL-Cholesterol Lowering in the Management of Atherosclerotic Cardiovascular Disease Risk"}],"class":"PCSK9 inhibitors (monoclonal antibodies and small interfering RNA)","class_members":["evolocumab","alirocumab","inclisiran"],"mechanism":"Block PCSK9, a protein that tags LDL receptors for breakdown. More LDL receptors recycle to the liver cell surface, so LDL falls by about 50 to 60%.","pharmacokinetics":["evolocumab and alirocumab are injected every 2 to 4 weeks","inclisiran is an siRNA that stops PCSK9 being made, injected twice a year after the first two doses"],"indications":["familial hypercholesterolemia","established atherosclerotic disease with LDL above goal despite a statin and ezetimibe","statin intolerance with high cardiovascular risk"],"adverse_effects":["injection-site reactions","nasopharyngitis","muscle aches, uncommon"],"contraindications":["hypersensitivity to the drug"],"interactions":["few drug interactions; not metabolized by CYP enzymes"],"monitoring":["lipid panel"],"overdose":{"features":[],"treatment":[]}}'::jsonb),
  ('peripheral-artery-disease', 1, 'in_review', null, null, '{"kind":"disease","name":"Peripheral artery disease","aliases":["peripheral arterial disease","PAD"],"systems":["cardio"],"rotation":["IM","surgery"],"confused_with":[],"pearls":["Neurogenic claudication from spinal stenosis improves with sitting or bending forward; vascular claudication improves with standing still.","Cilostazol is contraindicated in heart failure.","An ABI above 1.40 means stiff, calcified arteries, common in diabetes and kidney disease; use the toe-brachial index instead."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.history[0]"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[2]"]},"anki_refs":[],"sources":[{"title":"2024 ACC/AHA/AACVPR/APMA/ABC/SCAI/SVM/SVN/SVS/SIR/VESS Guideline for the Management of Lower Extremity Peripheral Artery Disease"}],"epidemiology":{"who":"Adults over 50, especially smokers and people with diabetes","risk_factors":["smoking","diabetes","hypertension","hyperlipidemia","older age","chronic kidney disease"]},"pathophysiology":"Atherosclerosis narrows the leg arteries, so blood flow cannot rise with exercise and the muscles become ischemic. Severe disease causes pain at rest, ulcers and gangrene.","timeline":{"onset":"Gradual over years","course":"Most stay stable; a minority progress to limb-threatening ischemia; the risk of heart attack and stroke is high"},"key_findings":{"history":["intermittent claudication: calf pain on walking, relieved by rest","rest pain in the foot, worse with the leg raised","nonhealing ulcers"],"exam":["weak or absent pedal pulses","cool, hairless, shiny skin","delayed capillary refill","dependent rubor, with pallor on elevation","arterial ulcers on the toes and pressure points"],"labs":["lipid panel and HbA1c"],"imaging":["ankle-brachial index","toe-brachial index when the arteries are incompressible","duplex ultrasound, CT or MR angiography to plan revascularization"]},"diagnosis":{"confirmatory_tests":["ankle-brachial index"],"criteria":["an ABI of 0.90 or less is diagnostic; above 1.40 means stiff, incompressible arteries"]},"management":{"first_line":["supervised exercise therapy","stop smoking","high-intensity statin","antiplatelet therapy with aspirin or clopidogrel","blood pressure and diabetes control"],"next_line":["cilostazol for claudication","revascularization, endovascular or bypass, for lifestyle-limiting claudication or limb-threatening ischemia","low-dose rivaroxaban with aspirin in selected patients"]},"complications":["chronic limb-threatening ischemia","amputation","myocardial infarction","stroke"]}'::jsonb),
  ('polyarteritis-nodosa', 1, 'in_review', null, null, '{"kind":"disease","name":"Polyarteritis nodosa","aliases":["PAN"],"systems":["cardio","renal"],"rotation":["IM"],"confused_with":[{"script_id":"microscopic-polyangiitis","how_to_tell_apart":"Polyarteritis nodosa inflames medium arteries, spares the lungs and glomeruli and is ANCA-negative; microscopic polyangiitis inflames small vessels, causes glomerulonephritis and lung hemorrhage and is usually MPO-ANCA positive."}],"pearls":["Polyarteritis nodosa spares the lungs.","Its classic association is hepatitis B.","Angiography shows a beaded, rosary-like pattern of microaneurysms in the renal and mesenteric arteries."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[1]"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["epidemiology.risk_factors[1]"]},"anki_refs":[],"sources":[{"title":"2021 American College of Rheumatology/Vasculitis Foundation Guideline for the Management of Polyarteritis Nodosa"},{"title":"Robbins and Cotran Pathologic Basis of Disease"}],"epidemiology":{"who":"Middle-aged adults; linked to hepatitis B","risk_factors":["hepatitis B infection","hairy cell leukemia","hepatitis C, less often"]},"pathophysiology":"Necrotizing inflammation of medium-sized muscular arteries, with segmental lesions of different ages and microaneurysms. It spares the lungs and the glomeruli and is not associated with ANCA.","timeline":{"onset":"Weeks to months of systemic symptoms","course":"Fatal untreated; most remit with treatment and rarely relapse"},"key_findings":{"history":["fever, weight loss and muscle pain","abdominal pain after meals from mesenteric ischemia","testicular pain","foot or wrist drop from mononeuritis multiplex"],"exam":["livedo reticularis","subcutaneous nodules and skin ulcers","new hypertension"],"labs":["raised ESR or CRP","negative ANCA","positive hepatitis B surface antigen in some"],"imaging":["mesenteric or renal angiography with microaneurysms and stenoses"]},"diagnosis":{"confirmatory_tests":["biopsy of affected skin, nerve or muscle showing necrotizing arteritis","angiography showing microaneurysms"],"criteria":[]},"management":{"first_line":["glucocorticoids, plus cyclophosphamide for severe disease","hepatitis B related disease: antivirals with a short course of glucocorticoids"],"next_line":["azathioprine or methotrexate for maintenance"]},"complications":["bowel infarction","kidney infarction and hypertension","myocardial infarction","stroke"]}'::jsonb),
  ('pulmonary-embolism', 1, 'in_review', null, null, '{"kind":"disease","name":"Pulmonary embolism","aliases":["PE"],"systems":["pulm","heme_onc"],"rotation":["IM","EM","surgery"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough, focal crackles and a consolidation on chest X-ray; PE more often has clear lungs and a near-normal X-ray despite hypoxemia.","compare":[{"label":"Lungs","text":"Clear","source_field":"key_findings.exam[3]"},{"label":"Imaging","text":"Filling defect on CTPA","source_field":"key_findings.imaging[0]"},{"label":"Treat","text":"Anticoagulation","source_field":"management.first_line[0]"}]},{"script_id":"deep-vein-thrombosis","how_to_tell_apart":"DVT is the usual source of PE: look for unilateral leg swelling and calf pain, and confirm with compression ultrasound.","compare":[{"label":"Symptom","text":"Sudden dyspnea","source_field":"key_findings.history[0]"},{"label":"Test","text":"CT pulmonary angiogram","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"Treat","text":"DOAC","source_field":"management.first_line[0]"}]},{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"Acute coronary syndrome causes pressure-like chest pain with ST changes on the ECG and a rise and fall of troponin; pulmonary embolism causes sudden dyspnea, pleuritic pain and hypoxemia.","compare":[{"label":"Pain","text":"Pleuritic","source_field":"key_findings.history[1]"},{"label":"First test","text":"CT pulmonary angiogram","source_field":"diagnosis.confirmatory_tests[0]"},{"label":"First drug","text":"Anticoagulation","source_field":"management.first_line[0]"}]}],"pearls":["The most common ECG finding in PE is sinus tachycardia; the classic S1Q3T3 pattern is uncommon."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["epidemiology.risk_factors","diagnosis.confirmatory_tests[0]","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]","diagnosis.criteria[1]"]},"anki_refs":[{"kind":"note","id":"1495883335732","rung":"recall"},{"kind":"note","id":"1495883587351","rung":"recall"},{"kind":"note","id":"1550710294654","rung":"recall"},{"kind":"note","id":"1474426264636","rung":"management"},{"kind":"note","id":"1550710228646","rung":"management"},{"kind":"note","id":"1557155284271","rung":"management"}],"sources":[{"title":"2019 ESC Guidelines for the diagnosis and management of acute pulmonary embolism"},{"title":"Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline and Expert Panel Report (2021)"}],"epidemiology":{"who":"Adults with risk factors for venous thromboembolism","risk_factors":["recent surgery","immobilization","active cancer","prior VTE","estrogen use or pregnancy","inherited thrombophilia"]},"pathophysiology":"A thrombus, usually from the deep veins of the legs, lodges in the pulmonary arteries, causing ventilation-perfusion mismatch and hypoxemia; a large clot strains the right ventricle and can cause shock.","timeline":{"onset":"Sudden","course":"Most stable patients recover with anticoagulation; massive PE can cause sudden death"},"key_findings":{"history":["sudden dyspnea","pleuritic chest pain","hemoptysis","unilateral leg swelling"],"exam":["tachycardia","tachypnea","hypoxemia","clear lungs"],"labs":["raised D-dimer","raised troponin or BNP with right ventricular strain"],"imaging":["CT pulmonary angiography showing a filling defect","echocardiogram may show right ventricular dilation"]},"diagnosis":{"confirmatory_tests":["CT pulmonary angiography","V/Q scan if CT contrast is contraindicated"],"criteria":["use the Wells score to estimate pretest probability","with low pretest probability, a negative D-dimer rules out PE"]},"management":{"first_line":["anticoagulation, preferably a direct oral anticoagulant such as apixaban or rivaroxaban"],"next_line":["systemic thrombolysis for high-risk PE with hypotension","catheter-directed therapy or surgical embolectomy if thrombolysis fails or is contraindicated","IVC filter only if anticoagulation is contraindicated"]},"complications":["right heart failure","obstructive shock","pulmonary infarction","chronic thromboembolic pulmonary hypertension"]}'::jsonb),
  ('renin-angiotensin-aldosterone-system', 1, 'in_review', null, null, '{"kind":"pathway","name":"Renin-angiotensin-aldosterone system","aliases":["RAAS","renin-angiotensin system"],"systems":["cardio","renal","endo"],"rotation":[],"confused_with":[],"pearls":["ANP and BNP oppose the RAAS: they dilate vessels and cause sodium loss.","The aldosterone-to-renin ratio screens for primary hyperaldosteronism.","Angiotensin II constricts the efferent arteriole more than the afferent, which keeps GFR up when perfusion falls."],"difficulty_tiers":{"MS1-2":["steps","regulation"],"MS3":["deficiencies","drug_targets"],"MS4":["pearls[1]","treatment"]},"anki_refs":[],"sources":[{"title":"Guyton and Hall Textbook of Medical Physiology"},{"title":"Costanzo Physiology"}],"location":"Kidney (juxtaglomerular cells), liver, lungs, adrenal cortex and blood vessels","purpose":"Keeps up blood pressure and blood volume by constricting arterioles and making the kidney hold on to sodium and water.","steps":["juxtaglomerular cells release renin when renal perfusion falls, when the macula densa senses low sodium chloride, or on beta-1 stimulation","renin cleaves angiotensinogen, made by the liver, to angiotensin I","angiotensin-converting enzyme, mostly in the lungs, converts angiotensin I to angiotensin II and breaks down bradykinin","angiotensin II constricts arterioles and the efferent arteriole, releases aldosterone and ADH, triggers thirst and increases proximal sodium reabsorption","aldosterone acts on the collecting duct to reabsorb sodium and excrete potassium and hydrogen"],"rate_limiting_enzyme":"renin","regulation":["low renal perfusion pressure raises renin","low sodium chloride at the macula densa raises renin","sympathetic beta-1 stimulation raises renin","angiotensin II and ANP lower renin release","high potassium stimulates aldosterone directly"],"cofactors":[],"deficiencies":["primary hyperaldosteronism: high aldosterone with low renin, causing hypertension and hypokalemia","renal artery stenosis: high renin with high aldosterone (secondary hyperaldosteronism)","Addison disease: low aldosterone with high renin, causing hyperkalemia and hypotension","Bartter and Gitelman syndromes: high renin and aldosterone with normal blood pressure"],"drug_targets":["aliskiren inhibits renin","ACE inhibitors block angiotensin-converting enzyme","ARBs block the AT1 receptor","spironolactone and eplerenone block the aldosterone receptor","beta blockers reduce renin release"],"treatment":["primary hyperaldosteronism: spironolactone, or adrenalectomy for a single adenoma","Addison disease: fludrocortisone with hydrocortisone"]}'::jsonb),
  ('restrictive-cardiomyopathy', 1, 'in_review', null, null, '{"kind":"disease","name":"Restrictive cardiomyopathy","aliases":["restrictive heart disease"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"constrictive-pericarditis","how_to_tell_apart":"Both fill poorly and raise venous pressure, but restrictive cardiomyopathy has stiff heart muscle, a high BNP and a normal pericardium; constrictive pericarditis has a thick, often calcified pericardium, a pericardial knock and a lower BNP.","compare":[{"label":"Problem","text":"Stiff ventricles","source_field":"pathophysiology"},{"label":"BNP","text":"Raised","source_field":"key_findings.labs[0]"}]}],"pearls":["Amyloidosis is the classic cause: a low-voltage ECG with thick ventricular walls on echo.","In cardiac amyloidosis, avoid non-dihydropyridine calcium channel blockers and use digoxin only with caution, because they bind the fibrils and cause toxicity.","Kussmaul sign, a rise in JVP on inspiration, occurs in both restrictive cardiomyopathy and constrictive pericarditis."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.risk_factors"],"MS3":["key_findings.imaging","management.first_line"],"MS4":["pearls[1]","key_findings.imaging[3]"]},"anki_refs":[],"sources":[{"title":"2023 ESC Guidelines for the management of cardiomyopathies"},{"title":"2023 ACC Expert Consensus Decision Pathway on Comprehensive Multidisciplinary Care for the Patient With Cardiac Amyloidosis"}],"epidemiology":{"who":"Adults; the least common cardiomyopathy","risk_factors":["amyloidosis","sarcoidosis","hemochromatosis","radiation","endomyocardial fibrosis","Loeffler endocarditis (hypereosinophilia)","Fabry disease"]},"pathophysiology":"Stiff ventricles fill poorly in diastole, with normal or near-normal wall thickness and systolic function (thick walls in infiltrative disease such as amyloidosis). Filling pressures rise, causing heart failure with a preserved ejection fraction and large atria.","timeline":{"onset":"Gradual","course":"Progressive; the outlook depends on the cause and is poor in amyloidosis"},"key_findings":{"history":["exertional dyspnea","fatigue","leg swelling","abdominal swelling"],"exam":["raised jugular venous pressure that rises on inspiration (Kussmaul sign)","S3","edema and ascites"],"labs":["raised BNP","serum free light chains and immunofixation for AL amyloidosis"],"imaging":["echocardiogram with normal-sized ventricles, large atria and diastolic dysfunction","low-voltage ECG despite thick walls in amyloidosis","cardiac MRI with late gadolinium enhancement","technetium pyrophosphate scan, which diagnoses transthyretin amyloidosis without a biopsy once light-chain tests rule out AL amyloidosis"]},"diagnosis":{"confirmatory_tests":["echocardiogram","cardiac MRI","endomyocardial biopsy when the cause is unclear"],"criteria":[]},"management":{"first_line":["diuretics for congestion","treat the cause: tafamidis or acoramidis (stabilizers) or vutrisiran (a silencer) for transthyretin amyloidosis, chemotherapy for AL amyloidosis, phlebotomy for hemochromatosis"],"next_line":["heart transplant in selected patients"]},"complications":["heart failure","atrial fibrillation","thromboembolism","sudden death"]}'::jsonb),
  ('rheumatic-fever', 1, 'in_review', null, null, '{"kind":"disease","name":"Acute rheumatic fever","aliases":["rheumatic fever"],"systems":["cardio","msk"],"rotation":["peds"],"confused_with":[],"pearls":["Mitral stenosis is the classic late valve lesion of rheumatic heart disease.","Treating strep throat within 9 days prevents rheumatic fever; it does not prevent post-streptococcal glomerulonephritis.","Aschoff bodies, which contain Anitschkow cells, are the histologic hallmark of rheumatic carditis."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[2]"],"MS3":["diagnosis.criteria","management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"Revision of the Jones Criteria for the Diagnosis of Acute Rheumatic Fever in the Era of Doppler Echocardiography (AHA Scientific Statement, 2015)"},{"title":"Nelson Textbook of Pediatrics"}],"epidemiology":{"who":"Children aged 5 to 15, 2 to 4 weeks after untreated group A streptococcal pharyngitis; now rare in high-income countries","risk_factors":["untreated group A streptococcal pharyngitis","crowded housing","poverty","prior rheumatic fever"]},"pathophysiology":"Antibodies against the streptococcal M protein cross-react with heart, joint, brain and skin tissue (molecular mimicry, a type II hypersensitivity). Carditis can leave lasting valve damage, called rheumatic heart disease.","timeline":{"onset":"2 to 4 weeks after a sore throat","course":"The acute illness settles over weeks to months; valve damage can progress for decades"},"key_findings":{"history":["recent sore throat","migrating joint pain","jerky involuntary movements (Sydenham chorea)"],"exam":["migratory polyarthritis of large joints","carditis with a new murmur, often mitral regurgitation","erythema marginatum","subcutaneous nodules","Sydenham chorea"],"labs":["raised ASO or anti-DNase B titers","raised ESR or CRP","prolonged PR interval on ECG"],"imaging":["echocardiogram showing valvulitis, most often mitral regurgitation"]},"diagnosis":{"confirmatory_tests":["evidence of recent group A strep infection: ASO or anti-DNase B titers, or a positive throat culture"],"criteria":["Jones criteria (2015 revision): 2 major, or 1 major plus 2 minor, with evidence of strep infection; recurrences can also be diagnosed with 3 minor criteria","major criteria: carditis, clinical or found only on echo, arthritis, chorea, erythema marginatum, subcutaneous nodules","minor criteria: fever, arthralgia, raised ESR or CRP, prolonged PR interval","thresholds for arthritis and the minor criteria are lower in moderate- and high-risk populations; a prolonged PR does not count when carditis is counted, nor arthralgia when arthritis is"]},"management":{"first_line":["penicillin to clear the streptococcus","high-dose aspirin or NSAIDs for the arthritis"],"next_line":["secondary prophylaxis with benzathine penicillin G injections every 3 to 4 weeks for years","glucocorticoids considered for severe carditis"]},"complications":["rheumatic heart disease","mitral stenosis decades later","heart failure","atrial fibrillation"]}'::jsonb),
  ('sacubitril-valsartan', 1, 'in_review', null, null, '{"kind":"drug","name":"Sacubitril-valsartan","aliases":["Entresto","ARNI"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"ace-inhibitors","how_to_tell_apart":"Sacubitril-valsartan is preferred over an ACE inhibitor in heart failure with reduced ejection fraction and lowers mortality further; the two must never overlap, so the ACE inhibitor is stopped 36 hours before the switch."}],"pearls":["Follow NT-proBNP, not BNP, in heart failure on sacubitril-valsartan.","Stop the ACE inhibitor 36 hours before the first dose.","The PARADIGM-HF trial showed lower mortality than with enalapril."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","contraindications"],"MS4":["pharmacokinetics[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}],"class":"Angiotensin receptor-neprilysin inhibitor (ARNI)","class_members":["sacubitril-valsartan"],"mechanism":"Sacubitril inhibits neprilysin, the enzyme that breaks down natriuretic peptides, bradykinin and other vasoactive peptides, so natriuretic peptides rise and cause vasodilation and sodium loss. Valsartan blocks the AT1 receptor; it is needed because neprilysin also breaks down angiotensin II.","pharmacokinetics":["sacubitril is a prodrug","BNP rises on treatment because neprilysin breaks it down; NT-proBNP does not"],"indications":["heart failure with reduced ejection fraction, first-line in place of an ACE inhibitor or ARB","heart failure with mildly reduced or preserved ejection fraction, in selected patients"],"adverse_effects":["hypotension","hyperkalemia","rise in creatinine","angioedema"],"contraindications":["within 36 hours of an ACE inhibitor","history of angioedema","pregnancy"],"interactions":["never combine with an ACE inhibitor: neprilysin and ACE both break down bradykinin, so the risk of angioedema rises"],"monitoring":["blood pressure","potassium and creatinine"],"overdose":{"features":["hypotension"],"treatment":["supportive care"]}}'::jsonb),
  ('septic-shock', 1, 'in_review', null, null, '{"kind":"disease","name":"Sepsis and septic shock","aliases":["sepsis","septic shock"],"systems":["general"],"rotation":["IM","EM"],"confused_with":[{"script_id":"adrenal-insufficiency","how_to_tell_apart":"Adrenal crisis also causes shock that doesn''t respond to fluids, often with hyponatremia, hyperkalemia and hypoglycemia; suspect it in anyone on long-term steroids.","compare":[{"label":"Key lab","text":"Lactate over 2 mmol/L","source_field":"key_findings.labs[0]"},{"label":"Clue","text":"Fever or chills","source_field":"key_findings.history[0]"},{"label":"Treat","text":"Antibiotics within 1 hour","source_field":"management.first_line[0]"}]},{"script_id":"cardiogenic-shock","how_to_tell_apart":"Septic shock is usually warm, with a normal or high cardiac output, low systemic resistance and a low wedge pressure; cardiogenic shock is cold and wet, with a low output, a high wedge pressure and high systemic resistance."}],"pearls":["Target a mean arterial pressure of at least 65 mmHg; norepinephrine is the first-line vasopressor."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1494892379716"},{"kind":"note","id":"1530550150741"},{"kind":"note","id":"1536437425019"},{"kind":"note","id":"1539537920733"},{"kind":"note","id":"1557739493988"}],"sources":[{"title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021"},{"title":"The Third International Consensus Definitions for Sepsis and Septic Shock (Sepsis-3, 2016)"}],"epidemiology":{"who":"Anyone with an infection; highest risk in older adults and the immunocompromised","risk_factors":["pneumonia","urinary tract infection","intra-abdominal infection","skin and soft tissue infection","indwelling lines or catheters"]},"pathophysiology":"A dysregulated host response to infection causes vasodilation, capillary leak and organ dysfunction.","timeline":{"onset":"Hours","course":"Mortality rises with each hour of delayed antibiotics in septic shock"},"key_findings":{"history":["fever or chills","confusion","symptoms of the source infection"],"exam":["hypotension","tachycardia","tachypnea","altered mental status","warm or mottled skin"],"labs":["lactate above 2 mmol/L","signs of organ dysfunction: rising creatinine or bilirubin, low platelets"],"imaging":["imaging to find the source, guided by symptoms"]},"diagnosis":{"confirmatory_tests":["blood cultures before antibiotics","serum lactate","SOFA score for organ dysfunction"],"criteria":["sepsis: suspected infection with an acute rise of 2 or more SOFA points","septic shock: vasopressors needed to keep MAP at 65 mmHg or more, with lactate above 2 mmol/L despite fluids"]},"management":{"first_line":["broad-spectrum antibiotics within 1 hour","30 mL/kg IV crystalloid for hypotension or lactate of 4 mmol/L or more","norepinephrine if hypotension persists"],"next_line":["source control","add vasopressin for rising norepinephrine needs","hydrocortisone for refractory shock"]},"complications":["multi-organ failure","ARDS","acute kidney injury","disseminated intravascular coagulation","death"]}'::jsonb),
  ('stable-angina', 1, 'in_review', null, null, '{"kind":"disease","name":"Stable angina","aliases":["chronic stable angina","angina pectoris"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"Stable angina comes on with exertion, settles with rest and leaves troponin normal; acute coronary syndrome brings pain at rest or a new crescendo pattern, and a myocardial infarction raises troponin."}],"pearls":["Beta blockers can worsen vasospastic (Prinzmetal) angina; calcium channel blockers treat it.","Nitrates are contraindicated within 24 hours of sildenafil or 48 hours of tadalafil, because the combination causes severe hypotension.","Nitrates relieve angina mainly by venodilation, which lowers preload and wall stress."],"difficulty_tiers":{"MS1-2":["pathophysiology","pearls[2]"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2023 AHA/ACC/ACCP/ASPC/NLA/PCNA Guideline for the Management of Patients With Chronic Coronary Disease"},{"title":"2024 ESC Guidelines for the management of chronic coronary syndromes"}],"epidemiology":{"who":"Middle-aged and older adults with atherosclerotic coronary disease","risk_factors":["smoking","hypertension","diabetes","high LDL cholesterol","family history of premature coronary disease","older age","male sex"]},"pathophysiology":"A fixed atherosclerotic plaque narrows a coronary artery, usually by 70% or more, so blood flow cannot rise to meet the heart''s oxygen demand during exertion. The ischemia is brief and reverses with rest, without myocardial necrosis.","timeline":{"onset":"Predictable chest pain with exertion, building over months","course":"A stable pattern; pain at rest or a crescendo pattern means unstable angina"},"key_findings":{"history":["substernal chest pressure brought on by exertion or emotion","pain relieved by rest or nitroglycerin within minutes","radiation to the arm, neck or jaw","dyspnea on exertion"],"exam":["often normal between episodes","signs of atherosclerosis such as carotid bruits or xanthelasma"],"labs":["normal troponin","lipid panel and HbA1c to assess risk"],"imaging":["resting ECG often normal","exercise ECG showing ST depression","stress echocardiography or nuclear perfusion imaging showing ischemia","coronary CT angiography showing plaque"]},"diagnosis":{"confirmatory_tests":["stress testing: exercise ECG, stress echocardiography or myocardial perfusion imaging","coronary CT angiography","invasive coronary angiography when risk is high or symptoms persist"],"criteria":["Typical angina has three features: substernal discomfort, brought on by exertion or emotional stress, and relieved by rest or nitroglycerin"]},"management":{"first_line":["sublingual nitroglycerin for attacks","beta blocker or calcium channel blocker for symptom control","aspirin","high-intensity statin","risk factor control: stop smoking, treat blood pressure and diabetes"],"next_line":["long-acting nitrates or ranolazine added for persistent angina","revascularization with PCI or CABG for symptoms despite medical therapy or for high-risk anatomy such as left main disease"]},"complications":["acute coronary syndrome","heart failure","arrhythmias"]}'::jsonb),
  ('staphylococcus-aureus', 1, 'in_review', null, null, '{"kind":"bug","name":"Staphylococcus aureus","aliases":["S. aureus","Staph aureus"],"systems":["cardio","derm","msk"],"rotation":[],"confused_with":[{"script_id":"viridans-streptococci","how_to_tell_apart":"S. aureus grows in clusters, is catalase- and coagulase-positive and causes acute endocarditis over days; viridans streptococci grow in chains, are catalase-negative and cause subacute endocarditis over weeks.","compare":[{"label":"Gram stain","text":"Cocci in clusters","source_field":"morphology"},{"label":"Course","text":"Acute endocarditis","source_field":"diseases[1]"},{"label":"Key test","text":"Coagulase-positive","source_field":"lab_features[1]"}]},{"script_id":"enterococcus","how_to_tell_apart":"S. aureus grows in clusters and is catalase-positive; enterococci grow in pairs and short chains, are catalase-negative and grow in 6.5% salt.","compare":[{"label":"Gram stain","text":"Cocci in clusters","source_field":"morphology"},{"label":"Course","text":"Acute endocarditis","source_field":"diseases[1]"},{"label":"Key test","text":"Coagulase-positive","source_field":"lab_features[1]"}]}],"pearls":["MRSA resists beta-lactams because the mecA gene encodes an altered penicillin-binding protein (PBP2a).","Daptomycin is inactivated by lung surfactant, so it cannot treat pneumonia.","S. aureus in a blood culture should never be dismissed as a contaminant: repeat blood cultures and get an echocardiogram."],"difficulty_tiers":{"MS1-2":["morphology","lab_features","virulence_factors"],"MS3":["diseases","treatment"],"MS4":["pearls[1]","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"Clinical Practice Guidelines by the Infectious Diseases Society of America for the Treatment of Methicillin-Resistant Staphylococcus aureus Infections in Adults and Children"}],"morphology":"Gram-positive cocci in clusters","lab_features":["catalase-positive","coagulase-positive","beta-hemolytic","golden-yellow colonies","ferments mannitol on mannitol salt agar"],"transmission":["colonizes the anterior nares of about 30% of people","spreads by direct contact and on hands","enters through broken skin, catheters and injection drug use"],"virulence_factors":["protein A, which binds the Fc region of IgG and blocks opsonization","coagulase, which coats the bacteria in fibrin","Panton-Valentine leukocidin, which kills white cells, in community MRSA","toxic shock syndrome toxin (TSST-1), a superantigen","exfoliative toxins, which cause scalded skin syndrome","preformed enterotoxins, which cause food poisoning"],"diseases":["skin and soft tissue infections: abscesses, furuncles, cellulitis and impetigo","acute endocarditis, often of the tricuspid valve in people who inject drugs","osteomyelitis","septic arthritis","pneumonia, especially after influenza","toxic shock syndrome","staphylococcal scalded skin syndrome","food poisoning with vomiting within hours"],"diagnosis":["Gram stain and culture of blood, pus or tissue","catalase and coagulase tests","mecA gene PCR or susceptibility testing for MRSA"],"treatment":["MSSA: nafcillin, oxacillin or cefazolin","MRSA bacteremia: vancomycin or daptomycin (daptomycin not for pneumonia)","MRSA pneumonia or skin infection: linezolid is also an option","drain abscesses","remove infected lines and devices"],"prevention":["hand hygiene","nasal mupirocin decolonization before some surgeries"]}'::jsonb),
  ('statins', 1, 'in_review', null, null, '{"kind":"drug","name":"Statins","aliases":["HMG-CoA reductase inhibitors"],"systems":["cardio"],"rotation":[],"confused_with":[{"script_id":"fibrates","how_to_tell_apart":"Statins mainly lower LDL by inhibiting HMG-CoA reductase; fibrates mainly lower triglycerides by activating PPAR-alpha."},{"script_id":"ezetimibe","how_to_tell_apart":"Statins block cholesterol synthesis in the liver and lower LDL by 30 to 50% or more; ezetimibe blocks cholesterol absorption in the gut and lowers LDL by about 20%."}],"pearls":["High-intensity statin therapy (atorvastatin 40 to 80 mg or rosuvastatin 20 to 40 mg) lowers LDL by 50% or more.","Short-acting statins such as simvastatin work best taken in the evening, when the liver makes most of its cholesterol.","Gemfibrozil with a statin carries a much higher risk of myopathy than fenofibrate."],"difficulty_tiers":{"MS1-2":["class","mechanism"],"MS3":["indications","adverse_effects"],"MS4":["interactions","pearls[0]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2018 AHA/ACC Guideline on the Management of Blood Cholesterol"}],"class":"HMG-CoA reductase inhibitors","class_members":["atorvastatin","rosuvastatin","simvastatin","pravastatin","lovastatin","pitavastatin","fluvastatin"],"mechanism":"Inhibit HMG-CoA reductase, the rate-limiting enzyme of cholesterol synthesis in the liver. Liver cells respond by making more LDL receptors, which pull LDL out of the blood. LDL falls most; triglycerides fall a little and HDL rises a little.","pharmacokinetics":["simvastatin, lovastatin and atorvastatin are metabolized by CYP3A4","rosuvastatin and pravastatin depend little on CYP3A4"],"indications":["established atherosclerotic cardiovascular disease","LDL of 190 mg/dL or higher","diabetes in adults aged 40 to 75","high 10-year cardiovascular risk"],"adverse_effects":["muscle aches","myopathy","rhabdomyolysis, rarely","raised liver enzymes","a small rise in the risk of diabetes"],"contraindications":["active liver disease","pregnancy and breastfeeding, for most patients"],"interactions":["CYP3A4 inhibitors such as clarithromycin, azole antifungals and grapefruit juice raise levels and the risk of myopathy","gemfibrozil raises the risk of myopathy"],"monitoring":["lipid panel 4 to 12 weeks after starting","liver enzymes at baseline","CK only if muscle symptoms appear"],"overdose":{"features":[],"treatment":[]}}'::jsonb),
  ('streptococcus-gallolyticus', 1, 'in_review', null, null, '{"kind":"bug","name":"Streptococcus gallolyticus","aliases":["Streptococcus bovis","S. bovis"],"systems":["cardio","gi"],"rotation":[],"confused_with":[{"script_id":"enterococcus","how_to_tell_apart":"Both are group D and hydrolyze bile esculin, but S. gallolyticus does not grow in 6.5% salt and is usually penicillin-susceptible; enterococci grow in 6.5% salt."}],"pearls":["S. gallolyticus bacteremia or endocarditis calls for a colonoscopy, because of its link with colorectal cancer.","Unlike enterococci, it does not grow in 6.5% salt.","It used to be called Streptococcus bovis biotype I."],"difficulty_tiers":{"MS1-2":["morphology","lab_features"],"MS3":["diseases","diagnosis[2]"],"MS4":["pearls[2]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"}],"morphology":"Gram-positive cocci in chains","lab_features":["nonhemolytic (gamma-hemolytic)","catalase-negative","Lancefield group D","grows in bile and hydrolyzes esculin","does not grow in 6.5% NaCl"],"transmission":["normal flora of the colon","enters the blood through a break in the colonic mucosa"],"virulence_factors":["adhesion to collagen on heart valves","biofilm formation"],"diseases":["subacute endocarditis","bacteremia"],"diagnosis":["blood cultures","echocardiogram","colonoscopy to look for colorectal cancer"],"treatment":["penicillin G, amoxicillin or ampicillin, or ceftriaxone"],"prevention":[]}'::jsonb),
  ('supraventricular-tachycardia', 1, 'in_review', null, null, '{"kind":"disease","name":"Paroxysmal supraventricular tachycardia","aliases":["SVT","PSVT"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"wolff-parkinson-white-syndrome","how_to_tell_apart":"AV nodal reentrant tachycardia (AVNRT) has a normal resting ECG and a circuit inside the AV node; WPW shows a delta wave and short PR at rest from an accessory pathway."},{"script_id":"ventricular-tachycardia","how_to_tell_apart":"SVT is usually a narrow-complex tachycardia that responds to vagal maneuvers or adenosine; VT is a wide-complex tachycardia with AV dissociation, fusion and capture beats, usually with structural heart disease."}],"pearls":["The modified Valsalva maneuver, a strain followed by lying flat with the legs raised, converts more SVT than the standard maneuver.","AVNRT is the most common type of paroxysmal SVT.","Avoid carotid sinus massage in patients with a carotid bruit or a prior stroke."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["management.first_line"],"MS4":["pearls[0]","key_findings.imaging[0]"]},"anki_refs":[],"sources":[{"title":"2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia"},{"title":"2019 ESC Guidelines for the management of patients with supraventricular tachycardia"}],"epidemiology":{"who":"Young adults, more often women","risk_factors":["caffeine and stimulants","stress","an accessory pathway (AVRT)","often no trigger"]},"pathophysiology":"A reentrant circuit involving the AV node causes a sudden, regular narrow-complex tachycardia. In AV nodal reentrant tachycardia (AVNRT, the most common) the circuit uses two pathways inside the AV node; in AV reentrant tachycardia (AVRT) it uses an accessory pathway.","timeline":{"onset":"Starts and stops suddenly","course":"Recurrent; cured by ablation"},"key_findings":{"history":["palpitations that start and stop abruptly","pounding in the neck","dizziness","passing a lot of urine after an episode"],"exam":["regular tachycardia, often 150 to 250 beats per minute"],"labs":["thyroid function tests","electrolytes"],"imaging":["ECG with a regular narrow-complex tachycardia and no visible P waves, or a pseudo-R prime in V1"]},"diagnosis":{"confirmatory_tests":["ECG during the episode"],"criteria":[]},"management":{"first_line":["vagal maneuvers: modified Valsalva or carotid sinus massage","IV adenosine if vagal maneuvers fail","synchronized cardioversion if unstable"],"next_line":["IV verapamil, diltiazem or a beta blocker if adenosine fails","catheter ablation for recurrent episodes"]},"complications":["syncope","tachycardia-induced cardiomyopathy, rarely"]}'::jsonb),
  ('takayasu-arteritis', 1, 'in_review', null, null, '{"kind":"disease","name":"Takayasu arteritis","aliases":["pulseless disease","Takayasu"],"systems":["cardio"],"rotation":["IM"],"confused_with":[{"script_id":"giant-cell-arteritis","how_to_tell_apart":"Takayasu arteritis affects women under 40 and narrows the aorta and its branches, causing weak arm pulses; giant cell arteritis affects people over 50 and favors the temporal and other cranial arteries."}],"pearls":["Takayasu arteritis is called pulseless disease because the arm pulses fade.","Age separates it from giant cell arteritis: under 40 versus over 50.","Measure blood pressure in both arms and the legs; renal artery stenosis can cause hypertension."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.who"],"MS3":["key_findings.exam","management.first_line"],"MS4":["management.next_line"]},"anki_refs":[],"sources":[{"title":"2021 American College of Rheumatology/Vasculitis Foundation Guideline for the Management of Giant Cell Arteritis and Takayasu Arteritis"},{"title":"2022 American College of Rheumatology/EULAR Classification Criteria for Takayasu Arteritis"}],"epidemiology":{"who":"Women under 40, especially of East Asian descent","risk_factors":["female sex","age under 40","East Asian ancestry"]},"pathophysiology":"Granulomatous inflammation of the aorta and its major branches thickens the walls and narrows the lumen, causing stenoses, occlusions and aneurysms.","timeline":{"onset":"An early systemic phase of fever, malaise and joint pain, then a vascular phase over months to years","course":"Chronic and relapsing"},"key_findings":{"history":["fever, weight loss and fatigue","arm claudication","dizziness or visual changes","chest pain"],"exam":["weak or absent arm pulses","systolic blood pressure differing by 20 mmHg or more between the arms","bruits over the subclavian arteries or aorta","hypertension from renal artery stenosis"],"labs":["raised ESR or CRP"],"imaging":["CT or MR angiography showing aortic wall thickening and branch stenoses","PET for active inflammation"]},"diagnosis":{"confirmatory_tests":["CT or MR angiography"],"criteria":[]},"management":{"first_line":["high-dose glucocorticoids","a steroid-sparing drug such as methotrexate, azathioprine, mycophenolate, leflunomide or a TNF inhibitor"],"next_line":["tocilizumab","revascularization for critical stenoses, preferably when inflammation is quiet"]},"complications":["aortic regurgitation","renovascular hypertension","stroke","aortic aneurysm","heart failure"]}'::jsonb),
  ('tetralogy-of-fallot', 1, 'in_review', null, null, '{"kind":"disease","name":"Tetralogy of Fallot","aliases":["TOF","Fallot tetralogy"],"systems":["cardio"],"rotation":["peds"],"confused_with":[{"script_id":"ventricular-septal-defect","how_to_tell_apart":"Tetralogy of Fallot causes cyanosis because outflow obstruction drives blood right to left across the VSD; an isolated VSD shunts left to right, so the child stays pink unless Eisenmenger syndrome develops."},{"script_id":"transposition-of-the-great-arteries","how_to_tell_apart":"Tetralogy of Fallot usually causes cyanosis later in infancy with a boot-shaped heart; transposition causes severe cyanosis in the first days of life with an egg-on-a-string heart."}],"pearls":["Squatting raises systemic vascular resistance, which pushes more blood through the lungs and relieves cyanosis.","The mnemonic PROVe: pulmonary stenosis, right ventricular hypertrophy, overriding aorta, VSD.","A tet spell is treated by raising systemic resistance and calming the child, never with inotropes."],"difficulty_tiers":{"MS1-2":["pathophysiology","epidemiology.risk_factors"],"MS3":["key_findings.imaging","management.first_line"],"MS4":["management.next_line"]},"anki_refs":[],"sources":[{"title":"Moss & Adams'' Heart Disease in Infants, Children, and Adolescents"},{"title":"Nelson Textbook of Pediatrics"}],"epidemiology":{"who":"Infants; the most common cyanotic congenital heart disease beyond the newborn period","risk_factors":["22q11.2 deletion (DiGeorge syndrome)","maternal diabetes","trisomy 21"]},"pathophysiology":"Anterosuperior displacement of the infundibular septum causes four features: pulmonary stenosis (right ventricular outflow obstruction), right ventricular hypertrophy, an overriding aorta and a ventricular septal defect. The degree of outflow obstruction decides how much blood shunts right to left, and so how cyanotic the child is.","timeline":{"onset":"Cyanosis in infancy, sometimes within days","course":"Repaired surgically in the first year; most now survive into adulthood"},"key_findings":{"history":["cyanotic spells (tet spells) with crying or feeding","squatting in older children"],"exam":["cyanosis","harsh systolic ejection murmur at the left upper sternal border from the pulmonary stenosis","clubbing in older children"],"labs":["polycythemia from chronic hypoxemia"],"imaging":["boot-shaped heart on chest X-ray","echocardiogram showing the four features"]},"diagnosis":{"confirmatory_tests":["echocardiogram"],"criteria":[]},"management":{"first_line":["tet spell: knees to chest, oxygen, morphine and IV fluids","complete surgical repair in the first year of life"],"next_line":["phenylephrine to raise systemic vascular resistance in a spell that does not settle","propranolol to prevent spells before repair"]},"complications":["tet spells","pulmonary regurgitation after repair","arrhythmias","paradoxical embolism"]}'::jsonb),
  ('thiazide-diuretics', 1, 'in_review', null, null, '{"kind":"drug","name":"Thiazide diuretics","aliases":["thiazides","thiazide-like diuretics"],"systems":["cardio","renal"],"rotation":[],"confused_with":[{"script_id":"loop-diuretics","how_to_tell_apart":"Thiazides act on the distal convoluted tubule and keep calcium; loop diuretics act on the thick ascending limb, are stronger and lose calcium.","compare":[{"label":"Site","text":"Distal convoluted tubule","source_field":"mechanism"},{"label":"Calcium","text":"Kept: hypercalcemia","source_field":"adverse_effects[2]"}]}],"pearls":["The hyper side effects: hyperglycemia, hyperlipidemia, hyperuricemia and hypercalcemia.","Thiazides cause hyponatremia more often than loop diuretics, especially in older women.","Thiazides paradoxically reduce urine output in nephrogenic diabetes insipidus."],"difficulty_tiers":{"MS1-2":["class","mechanism","adverse_effects"],"MS3":["indications","monitoring"],"MS4":["pharmacokinetics","pearls[2]"]},"anki_refs":[],"sources":[{"title":"Katzung''s Basic and Clinical Pharmacology"},{"title":"Goodman & Gilman''s The Pharmacological Basis of Therapeutics"},{"title":"2025 AHA/ACC Guideline for the Prevention, Detection, Evaluation, and Management of High Blood Pressure in Adults"}],"class":"Thiazide and thiazide-like diuretics","class_members":["hydrochlorothiazide","chlorthalidone","indapamide","metolazone"],"mechanism":"Block the sodium-chloride cotransporter (NCC) in the distal convoluted tubule. They also increase calcium reabsorption, so urine calcium falls.","pharmacokinetics":["chlorthalidone lasts longer than hydrochlorothiazide and still works in advanced chronic kidney disease","metolazone is often added to a loop diuretic for resistant edema"],"indications":["hypertension","edema, alone or added to a loop diuretic","calcium kidney stones from hypercalciuria","nephrogenic diabetes insipidus"],"adverse_effects":["hypokalemia","hyponatremia","hypercalcemia","hyperuricemia and gout","hyperglycemia","hyperlipidemia","metabolic alkalosis","sulfonamide allergy reactions"],"contraindications":["gout, as a relative caution","hyponatremia"],"interactions":["raise lithium levels","hypokalemia raises the risk of digoxin toxicity"],"monitoring":["sodium, potassium and calcium","uric acid and glucose"],"overdose":{"features":["dehydration","electrolyte loss"],"treatment":["IV fluids and electrolyte replacement"]}}'::jsonb),
  ('transposition-of-the-great-arteries', 1, 'in_review', null, null, '{"kind":"disease","name":"Transposition of the great arteries","aliases":["transposition","TGA","D-TGA"],"systems":["cardio"],"rotation":["peds"],"confused_with":[{"script_id":"tetralogy-of-fallot","how_to_tell_apart":"Transposition causes severe cyanosis in the first days of life with an egg-on-a-string heart; tetralogy of Fallot usually causes cyanosis later in infancy with a boot-shaped heart."}],"pearls":["Transposition is the most common cyanotic lesion presenting in the newborn period; tetralogy of Fallot is the most common cyanotic lesion overall.","Infants of diabetic mothers have a higher risk of transposition.","The arterial switch swaps the great arteries and reimplants the coronary arteries."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.imaging[0]"],"MS3":["management.first_line"],"MS4":["pearls[2]"]},"anki_refs":[],"sources":[{"title":"Moss & Adams'' Heart Disease in Infants, Children, and Adolescents"},{"title":"2018 AHA/ACC Guideline for the Management of Adults With Congenital Heart Disease"}],"epidemiology":{"who":"Newborns; the most common cyanotic heart lesion presenting in the first days of life","risk_factors":["maternal diabetes","male sex"]},"pathophysiology":"The aorta arises from the right ventricle and the pulmonary artery from the left ventricle, creating two parallel circulations. Survival depends on mixing through a patent ductus arteriosus, a patent foramen ovale or a septal defect.","timeline":{"onset":"Severe cyanosis within hours to days of birth as the duct closes","course":"Fatal within weeks untreated; excellent outcome after the arterial switch"},"key_findings":{"history":["cyanosis soon after birth"],"exam":["profound cyanosis that does not improve with oxygen","single loud S2","often no murmur"],"labs":["severe hypoxemia that does not correct with 100% oxygen (a failed hyperoxia test)"],"imaging":["chest X-ray with an egg-on-a-string heart","echocardiogram showing the transposed great arteries"]},"diagnosis":{"confirmatory_tests":["echocardiogram"],"criteria":[]},"management":{"first_line":["prostaglandin E1 to keep the ductus open","balloon atrial septostomy to improve mixing if needed","arterial switch operation in the first weeks of life"],"next_line":["lifelong follow-up for coronary and neoaortic problems"]},"complications":["death without mixing","coronary problems after the switch","neoaortic regurgitation"]}'::jsonb),
  ('upper-gi-bleeding', 1, 'in_review', null, null, '{"kind":"disease","name":"Upper gastrointestinal bleeding","aliases":["upper GI bleed","UGIB"],"systems":["gi"],"rotation":["IM","EM","surgery"],"confused_with":[],"pearls":["In suspected variceal bleeding, give octreotide and antibiotics before endoscopy; antibiotics reduce infection and death."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1531907221280"},{"kind":"note","id":"1535752586086"},{"kind":"note","id":"1543178936469"},{"kind":"note","id":"1543191124336"},{"kind":"note","id":"1550842808822"}],"sources":[{"title":"ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding (2021)"},{"title":"Baveno VII: Renewing consensus in portal hypertension (2022)"}],"epidemiology":{"who":"Adults; peptic ulcer disease is the most common cause","risk_factors":["peptic ulcer disease","esophageal varices","NSAIDs","Helicobacter pylori","anticoagulants","Mallory-Weiss tear"]},"pathophysiology":"Bleeding above the ligament of Treitz, most often from a peptic ulcer eroding a vessel, or from varices in portal hypertension.","timeline":{"onset":"Acute","course":"Most bleeds stop on their own; rebleeding raises mortality"},"key_findings":{"history":["hematemesis or coffee-ground vomit","melena","lightheadedness or syncope","NSAID or alcohol use"],"exam":["tachycardia and hypotension","signs of chronic liver disease in variceal bleeding"],"labs":["falling hemoglobin","raised BUN-to-creatinine ratio from digested blood"],"imaging":[]},"diagnosis":{"confirmatory_tests":["upper endoscopy within 24 hours"],"criteria":["the Glasgow-Blatchford score identifies low-risk patients for outpatient care"]},"management":{"first_line":["two large-bore IV lines and fluid resuscitation","transfuse to a hemoglobin of 7 g/dL (8 with cardiovascular disease)","IV proton pump inhibitor","upper endoscopy within 24 hours"],"next_line":["for varices: octreotide and antibiotics (ceftriaxone) before endoscopy, then band ligation","test for and treat Helicobacter pylori"]},"complications":["hemorrhagic shock","rebleeding","death"]}'::jsonb),
  ('ventricular-septal-defect', 1, 'in_review', null, null, '{"kind":"disease","name":"Ventricular septal defect","aliases":["VSD"],"systems":["cardio"],"rotation":["peds"],"confused_with":[{"script_id":"tetralogy-of-fallot","how_to_tell_apart":"An isolated VSD shunts left to right, so the child is pink with a holosystolic murmur; tetralogy of Fallot adds outflow obstruction that drives blood right to left and causes cyanosis."},{"script_id":"atrial-septal-defect","how_to_tell_apart":"A VSD gives a harsh holosystolic murmur at the left lower sternal border in infancy; an ASD gives wide fixed splitting of S2 and a soft pulmonary flow murmur, often found in adults."},{"script_id":"patent-ductus-arteriosus","how_to_tell_apart":"A VSD gives a holosystolic murmur at the left lower sternal border; a PDA gives a continuous machine-like murmur below the left clavicle with bounding pulses."}],"pearls":["Smaller defects are louder, because blood jets through a small hole at high speed.","Once Eisenmenger syndrome sets in, the defect can no longer be closed.","Muscular defects are the ones most likely to close on their own."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.exam[0]"],"MS3":["management.first_line","management.next_line"],"MS4":["pearls[1]","complications[3]"]},"anki_refs":[],"sources":[{"title":"Moss & Adams'' Heart Disease in Infants, Children, and Adolescents"},{"title":"Nelson Textbook of Pediatrics"}],"epidemiology":{"who":"Infants and children; the most common congenital heart defect, apart from a bicuspid aortic valve","risk_factors":["trisomy 21","trisomy 13","trisomy 18","fetal alcohol syndrome"]},"pathophysiology":"A hole in the ventricular septum, most often membranous, lets blood shunt left to right. A large defect floods the lungs and causes heart failure; untreated, rising pulmonary resistance can reverse the shunt (Eisenmenger syndrome).","timeline":{"onset":"The murmur appears days to weeks after birth as pulmonary resistance falls","course":"Many small muscular defects close on their own; large ones need repair"},"key_findings":{"history":["often no symptoms if small","poor feeding, sweating and failure to thrive if large","fast breathing"],"exam":["harsh holosystolic murmur at the left lower sternal border","a louder murmur often means a smaller defect","signs of heart failure in large defects"],"labs":[],"imaging":["echocardiogram showing the defect and the shunt","chest X-ray with increased pulmonary vascular markings in large defects"]},"diagnosis":{"confirmatory_tests":["echocardiogram"],"criteria":[]},"management":{"first_line":["watch small defects, since many close by themselves","diuretics for heart failure while waiting"],"next_line":["surgical or device closure for large defects with heart failure, failure to thrive or rising pulmonary pressure"]},"complications":["heart failure","Eisenmenger syndrome","infective endocarditis","aortic regurgitation"]}'::jsonb),
  ('ventricular-tachycardia', 1, 'in_review', null, null, '{"kind":"disease","name":"Ventricular tachycardia","aliases":["VT"],"systems":["cardio"],"rotation":["IM","EM"],"confused_with":[{"script_id":"supraventricular-tachycardia","how_to_tell_apart":"VT is a wide-complex tachycardia with AV dissociation, fusion and capture beats, usually with structural heart disease; SVT is usually narrow-complex and responds to vagal maneuvers or adenosine."},{"script_id":"long-qt-syndrome","how_to_tell_apart":"Scar-related VT is usually monomorphic, with structural heart disease; long QT syndrome causes polymorphic VT (torsades de pointes) with a long QT between episodes, treated with magnesium."}],"pearls":["Treat any wide-complex tachycardia as VT if in doubt, especially after an MI.","Fusion and capture beats prove AV dissociation and make the diagnosis VT.","Torsades de pointes is polymorphic VT with a long QT; give IV magnesium."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.imaging[0]","management.first_line"],"MS4":["management.next_line","pearls[1]"]},"anki_refs":[],"sources":[{"title":"2017 AHA/ACC/HRS Guideline for Management of Patients With Ventricular Arrhythmias and the Prevention of Sudden Cardiac Death"},{"title":"2022 ESC Guidelines for the management of patients with ventricular arrhythmias and the prevention of sudden cardiac death"}],"epidemiology":{"who":"Adults with structural heart disease, most often a prior myocardial infarction","risk_factors":["prior myocardial infarction with scar","cardiomyopathy","heart failure with a low ejection fraction","electrolyte disturbances such as low potassium or magnesium","long QT, causing torsades de pointes","drug toxicity"]},"pathophysiology":"A rapid rhythm starting in the ventricles, usually from reentry around scar after an MI, at rates above 100 and usually 150 to 250, with wide QRS complexes. It can degenerate into ventricular fibrillation.","timeline":{"onset":"Sudden","course":"Sustained VT lasts over 30 seconds or needs earlier termination because of hemodynamic compromise; it can cause shock and cardiac arrest"},"key_findings":{"history":["palpitations","dizziness or syncope","chest pain","cardiac arrest"],"exam":["tachycardia","hypotension or no pulse","cannon A waves from AV dissociation"],"labs":["potassium and magnesium","troponin"],"imaging":["ECG: regular wide-complex tachycardia with AV dissociation, fusion beats and capture beats","echocardiogram, cardiac MRI and coronary assessment after recovery"]},"diagnosis":{"confirmatory_tests":["12-lead ECG"],"criteria":["a wide-complex tachycardia in a patient with structural heart disease is VT until proven otherwise"]},"management":{"first_line":["pulseless VT: defibrillation and advanced life support","unstable VT with a pulse: synchronized cardioversion","stable VT: synchronized cardioversion, or IV procainamide, amiodarone or sotalol"],"next_line":["ICD for secondary prevention","catheter ablation for recurrent VT","IV magnesium for torsades de pointes"]},"complications":["ventricular fibrillation","cardiac arrest","sudden death"]}'::jsonb),
  ('viridans-streptococci', 1, 'in_review', null, null, '{"kind":"bug","name":"Viridans group streptococci","aliases":["viridans streptococci","Streptococcus viridans"],"systems":["cardio","general"],"rotation":[],"confused_with":[{"script_id":"staphylococcus-aureus","how_to_tell_apart":"Viridans streptococci grow in chains, are catalase-negative and cause subacute endocarditis over weeks, often after dental work; S. aureus grows in clusters, is coagulase-positive and causes acute endocarditis over days.","compare":[{"label":"Gram stain","text":"Cocci in chains","source_field":"morphology"},{"label":"Course","text":"Subacute endocarditis","source_field":"diseases[0]"},{"label":"Key test","text":"Catalase-negative","source_field":"lab_features[1]"}]},{"script_id":"enterococcus","how_to_tell_apart":"Both cause subacute endocarditis. Viridans streptococci are alpha-hemolytic, come from the mouth and follow dental work; enterococci grow in 6.5% salt, come from the gut and urinary tract and follow GI or urinary procedures.","compare":[{"label":"Gram stain","text":"Cocci in chains","source_field":"morphology"},{"label":"Source","text":"Mouth flora","source_field":"transmission[0]"},{"label":"Key test","text":"Alpha-hemolytic","source_field":"lab_features[0]"}]},{"script_id":"hacek-organisms","how_to_tell_apart":"Both cause subacute endocarditis from the mouth, but viridans streptococci are gram-positive cocci in chains that grow readily, while HACEK organisms are fastidious gram-negative rods that grow slowly."}],"pearls":["Viridans streptococci and S. pneumoniae are both alpha-hemolytic; optochin resistance and no bile solubility mark viridans.","Subacute endocarditis from viridans streptococci typically follows dental work and causes weeks of low fever and weight loss.","S. mutans uses sucrose to make dextran, which glues it to teeth."],"difficulty_tiers":{"MS1-2":["morphology","lab_features","virulence_factors"],"MS3":["diseases[0]","treatment"],"MS4":["prevention[1]"]},"anki_refs":[],"sources":[{"title":"Sherris & Ryan''s Medical Microbiology"},{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"Prevention of Viridans Group Streptococcal Infective Endocarditis: A Scientific Statement From the American Heart Association (2021)"}],"morphology":"Gram-positive cocci in chains","lab_features":["alpha-hemolytic (green, partial hemolysis)","catalase-negative","optochin-resistant","not bile-soluble"],"transmission":["normal flora of the mouth","enter the blood after dental procedures or with poor dental hygiene"],"virulence_factors":["dextran, which helps them stick to fibrin and platelets on damaged valves","Streptococcus mutans makes acid that causes dental caries"],"diseases":["subacute endocarditis on damaged or abnormal valves","dental caries (S. mutans)","brain and liver abscesses (S. anginosus group)"],"diagnosis":["blood cultures","echocardiogram for endocarditis","alpha hemolysis and optochin resistance in the lab"],"treatment":["endocarditis: penicillin G or ceftriaxone, guided by penicillin susceptibility","gentamicin may be added for less susceptible strains"],"prevention":["good dental hygiene","amoxicillin before dental work for the highest-risk patients, including those with a prosthetic valve or prosthetic material used for valve repair, prior endocarditis, unrepaired cyanotic congenital heart disease, recently repaired congenital heart disease with prosthetic material, or a heart transplant with valve disease"]}'::jsonb),
  ('wolff-parkinson-white-syndrome', 1, 'in_review', null, null, '{"kind":"disease","name":"Wolff-Parkinson-White syndrome","aliases":["WPW","Wolff-Parkinson-White"],"systems":["cardio"],"rotation":["IM","peds"],"confused_with":[{"script_id":"supraventricular-tachycardia","how_to_tell_apart":"WPW shows a delta wave and short PR at rest from an accessory pathway; AV nodal reentrant tachycardia has a normal resting ECG and a circuit inside the AV node."}],"pearls":["Pre-excited atrial fibrillation looks like an irregular, very fast, wide-complex tachycardia with changing QRS shapes.","Ablation cures most patients.","Ebstein anomaly is often associated with accessory pathways."],"difficulty_tiers":{"MS1-2":["pathophysiology","key_findings.imaging[0]"],"MS3":["management.first_line"],"MS4":["management.next_line","pearls[0]"]},"anki_refs":[],"sources":[{"title":"2015 ACC/AHA/HRS Guideline for the Management of Adult Patients With Supraventricular Tachycardia"},{"title":"2019 ESC Guidelines for the management of patients with supraventricular tachycardia"}],"epidemiology":{"who":"Children and young adults; the pattern is found in about 1 to 3 per 1000 people","risk_factors":["Ebstein anomaly","hypertrophic cardiomyopathy","family history"]},"pathophysiology":"An accessory pathway (bundle of Kent) connects the atria and ventricles, bypassing the AV node. The ventricles are pre-excited, and the pathway can carry reentrant tachycardias or conduct atrial fibrillation very fast to the ventricles.","timeline":{"onset":"Palpitations often begin in childhood or adolescence","course":"Many have no symptoms; a small risk of sudden death from pre-excited atrial fibrillation"},"key_findings":{"history":["episodes of palpitations","dizziness or syncope","sudden death, rarely, as the first sign"],"exam":["often normal between episodes"],"labs":[],"imaging":["ECG with a short PR interval, a delta wave and a wide QRS","echocardiogram to look for structural disease such as Ebstein anomaly"]},"diagnosis":{"confirmatory_tests":["ECG","electrophysiology study"],"criteria":["WPW syndrome: pre-excitation on the ECG plus a tachyarrhythmia"]},"management":{"first_line":["catheter ablation of the accessory pathway for patients with symptoms","vagal maneuvers or adenosine for orthodromic reentrant tachycardia with a narrow QRS"],"next_line":["procainamide, ibutilide or electrical cardioversion for pre-excited atrial fibrillation","avoid AV nodal blockers (adenosine, beta blockers, verapamil, diltiazem, digoxin) and IV amiodarone in pre-excited atrial fibrillation"]},"complications":["atrioventricular reentrant tachycardia","pre-excited atrial fibrillation turning into ventricular fibrillation","sudden cardiac death"]}'::jsonb);
