  ('zorblax-syndrome.pearl.1', 'zorblax-syndrome', 1, 'pearl', '{"prompt":"Which vital-sign finding argues against Zorblax syndrome?","source_fields":["pearls[0]"],"accepted_answers":[{"answer":"fever","synonyms":["febrile","high temperature"]}],"kind":"single"}'::jsonb),
  ('zorblax-syndrome.management.2', 'zorblax-syndrome', 1, 'management', '{"prompt":"Zorbicillin has failed. What next?","source_fields":["management.next_line"],"accepted_answers":[{"answer":"plasma swap","synonyms":["plasma exchange"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.recall.1', 'abdominal-aortic-aneurysm', 1, 'recall', '{"prompt":"A 72-year-old former smoker has a pulsatile mass above the umbilicus. Ultrasound shows a 4.2 cm aorta. Diagnosis?","source_fields":["name","aliases"],"accepted_answers":[{"answer":"Abdominal aortic aneurysm","synonyms":["AAA","aortic aneurysm"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.recall.2', 'abdominal-aortic-aneurysm', 1, 'recall', '{"prompt":"What aortic diameter defines an abdominal aortic aneurysm?","source_fields":["diagnosis.criteria[0]"],"accepted_answers":[{"answer":"3 cm or more","synonyms":["3 cm","3 centimeters","30 mm","over 3 cm"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.second-order.1', 'abdominal-aortic-aneurysm', 1, 'second_order', '{"prompt":"Name three risk factors for abdominal aortic aneurysm.","source_fields":["epidemiology.risk_factors"],"accepted_answers":[{"answer":"smoking","synonyms":["smoker","tobacco","cigarettes"]},{"answer":"male sex","synonyms":["male","being male"]},{"answer":"age over 65","synonyms":["older age","old age","age","elderly"]},{"answer":"family history","synonyms":[]},{"answer":"hypertension","synonyms":["high blood pressure","HTN"]},{"answer":"atherosclerosis","synonyms":[]}],"kind":"list","required_count":3}'::jsonb),
  ('abdominal-aortic-aneurysm.second-order.2', 'abdominal-aortic-aneurysm', 1, 'second_order', '{"prompt":"Where along the aorta do most abdominal aortic aneurysms form?","source_fields":["pearls[1]"],"accepted_answers":[{"answer":"infrarenal","synonyms":["below the renal arteries","infrarenal aorta"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.differentiate.1', 'abdominal-aortic-aneurysm', 1, 'differentiate', '{"prompt":"Name the classic triad of a ruptured abdominal aortic aneurysm.","source_fields":["pearls[0]"],"accepted_answers":[{"answer":"back pain","synonyms":["abdominal pain","flank pain"]},{"answer":"hypotension","synonyms":["low blood pressure","shock"]},{"answer":"pulsatile mass","synonyms":["pulsatile abdominal mass"]}],"kind":"list","required_count":3}'::jsonb),
  ('abdominal-aortic-aneurysm.differentiate.2', 'abdominal-aortic-aneurysm', 1, 'differentiate', '{"prompt":"Abdominal aortic aneurysm or aortic dissection: which is a tear in the intima with sudden tearing pain to the back?","source_fields":["confused_with[0].how_to_tell_apart"],"accepted_answers":[{"answer":"aortic dissection","synonyms":["dissection"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.workup.1', 'abdominal-aortic-aneurysm', 1, 'workup', '{"prompt":"Who should get a one-time ultrasound screen for abdominal aortic aneurysm?","source_fields":["management.first_line[0]"],"accepted_answers":[{"answer":"men aged 65 to 75 who have ever smoked","synonyms":["men 65 to 75 who have ever smoked","men 65 75 who have ever smoked","men aged 65 to 75 who smoked","men 65 to 75 who smoked","male smokers 65 to 75","men who have smoked","male smokers over 65","older men who smoked"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.workup.2', 'abdominal-aortic-aneurysm', 1, 'workup', '{"prompt":"Which test screens for and follows an abdominal aortic aneurysm?","source_fields":["diagnosis.confirmatory_tests[0]"],"accepted_answers":[{"answer":"abdominal ultrasound","synonyms":["ultrasound","ultrasonography"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.management.1', 'abdominal-aortic-aneurysm', 1, 'management', '{"prompt":"At what diameter is elective repair offered to a man?","source_fields":["management.next_line[0]"],"accepted_answers":[{"answer":"5.5 cm","synonyms":["5.5","55 mm","5.5 centimeters"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.management.2', 'abdominal-aortic-aneurysm', 1, 'management', '{"prompt":"Name the minimally invasive repair.","source_fields":["management.next_line[0]"],"accepted_answers":[{"answer":"EVAR","synonyms":["endovascular aneurysm repair","endovascular repair","endovascular","stent graft"]}],"kind":"single"}'::jsonb),
  ('abdominal-aortic-aneurysm.pearl.1', 'abdominal-aortic-aneurysm', 1, 'pearl', '{"prompt":"Which common disease is linked to a lower risk of abdominal aortic aneurysm?","source_fields":["pearls[2]"],"accepted_answers":[{"answer":"diabetes","synonyms":["diabetes mellitus"]}],"kind":"single"}'::jsonb),
